// ensureImport adds `import <path>` to f if not already imported.
// New nodes are anchored at real source positions (just after the
// package clause): go/printer interleaves comments by position, and
// unpositioned nodes make it emit the import split across the next
// declaration's doc comment.
func ensureImport(f *ast.File, path string) {
	if f == nil {
		return
	}
	for _, imp := range f.Imports {
		if unquote(imp.Path.Value) == path {
			return
		}
	}
	anchor := f.Name.End()
	mkSpec := func(pos token.Pos) *ast.ImportSpec {
		return &ast.ImportSpec{Path: &ast.BasicLit{Kind: token.STRING, Value: strconv.Quote(path), ValuePos: pos}}
	}
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if ok && gd.Tok == token.IMPORT {
			pos := anchor
			if n := len(gd.Specs); n > 0 {
				pos = gd.Specs[n-1].End()
			}
			gd.Specs = append(gd.Specs, mkSpec(pos))
			return
		}
	}
	f.Decls = append([]ast.Decl{&ast.GenDecl{
		Tok:	token.IMPORT,
		TokPos:	anchor,
		Specs:	[]ast.Spec{mkSpec(anchor)},
	}}, f.Decls...)
}

// addDeprecatedRepoShorthand adds a -r parameter (deprecated shorthand for --repo)
// which instructs the user to use -R instead.
func addDeprecatedRepoShorthand(cmd *cobra.Command, target *string) error {
	cmd.Flags().StringVarP(target, "repo-deprecated", "r", "", "(Deprecated) Shorthand for --repo")

	if err := cmd.Flags().MarkHidden("repo-deprecated"); err != nil {
		return fmt.Errorf("error marking `-r` shorthand as hidden: %w", err)
	}

	if err := cmd.Flags().MarkShorthandDeprecated("repo-deprecated", "use `-R` instead"); err != nil {
		return fmt.Errorf("error marking `-r` shorthand as deprecated: %w", err)
	}

	if cmd.Flag("codespace") != nil {
		cmd.MarkFlagsMutuallyExclusive("codespace", "repo-deprecated")
	}

	return nil
}

// addBias adds a bias vector to every row of a [rows*cols] matrix in place.
func addBias(data []float32, rows, cols int, bias *Tensor) {
	if bias == nil {
		return
	}
	bd := bias.Data
	for r := 0; r < rows; r++ {
		base := r * cols
		for c := 0; c < cols; c++ {
			data[base+c] += bd[c]
		}
	}
}

