// explainWithCodeIntent answers an explanation-seeking question by composing
// analyzer facts with neural prose. It returns ok=false when the symbol
// doesn't resolve, the model is unavailable, or the model produces nothing
// usable — callers fall back to the deterministic template.
func explainWithCodeIntent(p *analyze.Project, name, question, projectRoot string) (string, bool) {
	facts, ok := p.FactsForExplain(name, question)
	if !ok {
		return "", false
	}
	model := loadCodeIntentExplainer(projectRoot)
	if model == nil {
		return "", false
	}
	raw, err := model.Predict(facts.Input, 100)
	if err != nil || strings.TrimSpace(raw) == "" {
		return "", false
	}
	prose := extractProse(raw)
	if !prosePassesGate(prose, facts.Summary) {
		return "", false
	}
	var b strings.Builder
	b.WriteString(facts.Sig + "\n")
	b.WriteString("  " + facts.FileLine + "\n")
	b.WriteString("  " + facts.Summary + "\n")
	b.WriteString("\nIn plain words: " + prose + "\n")
	return b.String(), true
}

// Recall answers questions about the conversation itself by quoting the
// transcript verbatim. It returns the reply text and true when the input
// is a recall question; deterministic lookup, never the neural model.
func (c *Conversation) Recall(input string) (string, bool) {
	switch {
	case recallYouSaid.MatchString(input):
		if t := c.lastUserText(); t != "" {
			return fmt.Sprintf("you said: %q", t), true
		}
		return "we are just getting started, you have not said anything yet", true
	case recallISaid.MatchString(input):
		if t := c.lastReply(); t != "" {
			return fmt.Sprintf("i said: %q", t), true
		}
		return "i have not said anything yet", true
	case recallCommand.MatchString(input):
		if t := c.lastCommand(); t != "" {
			return fmt.Sprintf("the last command was: %s", t), true
		}
		return "i have not given you a command yet this session", true
	}
	return "", false
}

