}

// ApplyRepetitionPenalty applies a penalty to the logits of tokens that have already appeared.
func (t *Tensor) ApplyRepetitionPenalty(indices []int, penalty float32) {
	for _, idx := range indices {
		if idx >= 0 && idx < len(t.Data) {
			if t.Data[idx] < 0 {
				t.Data[idx] *= penalty
			} else {
				t.Data[idx] /= penalty
			}
		}
	}
}

// applyDropout applies dropout to a tensor during training.
// During training, randomly sets dropoutRate fraction of values to 0 and scales remaining by 1/(1-dropoutRate).
// During inference (training=false), returns the tensor unchanged.
func applyDropout(tensor *Tensor, dropoutRate float32, training bool) *Tensor {
	if !training || dropoutRate == 0.0 {
		return tensor
	}

	mask := NewTensor(tensor.Shape, make([]float32, len(tensor.Data)), false)
	scale := 1.0 / (1.0 - dropoutRate)

	for i := range mask.Data {
		if rand.Float32() < dropoutRate {
			mask.Data[i] = 0.0
		} else {
			mask.Data[i] = scale
		}
	}

	output := NewTensor(tensor.Shape, make([]float32, len(tensor.Data)), tensor.RequiresGrad)
	MulVectors(tensor.Data, mask.Data, output.Data)

	return output
}

// segmentWord applies learned BPE merges to segment a single word into subword units.
func (b *BPETokenizer) segmentWord(word string) []string {
	if word == "" {
		return nil
	}

	segments := make([]string, 0, len(word))
	for _, r := range word {
		segments = append(segments, string(r))
	}

	for _, merge := range b.Merges {
		var newSegments []string
		i := 0
		for i < len(segments) {
			if i+1 < len(segments) && segments[i] == merge.Left && segments[i+1] == merge.Right {
				newSegments = append(newSegments, merge.Left+merge.Right)
				i += 2
			} else {
				newSegments = append(newSegments, segments[i])
				i++
			}
		}
		segments = newSegments
	}

	return segments
}

// pickBest applies safety penalties to the MCTS-ranked nodes and
// returns the highest safety-adjusted fitness (ID tiebreak).
func pickBest(ranked []synthesis.CandidateNode, penalties []int) scoredCandidate {
	scored := make([]scoredCandidate, 0, len(ranked))
	for _, node := range ranked {
		pen, idx := 0, -1
		if i, ok := survivorIndexOf(node.ID); ok && i < len(penalties) {
			pen, idx = penalties[i], i
		}
		final := node.Score - float64(pen)
		allocs := "n/a"
		if len(node.Errors) == 0 {
			allocs = fmt.Sprintf("%d", node.Metrics.AllocsPerOp)
		}
		scored = append(scored, scoredCandidate{node: node, final: final, index: idx})
		fmt.Printf("   %s: raw=%.1f safety=-%d final=%.1f allocs/op=%s errors=%d\n",
			node.ID, node.Score, pen, final, allocs, len(node.Errors))
	}
	sort.Slice(scored, func(a, b int) bool {
		if scored[a].final != scored[b].final {
			return scored[a].final > scored[b].final
		}
		return scored[a].node.ID < scored[b].node.ID
	})
	return scored[0]
}

