// Softmax applies the softmax function to the last dimension of the tensor.
func Softmax(tensor *Tensor) *Tensor {
	shape := tensor.Shape
	lastDim := shape[len(shape)-1]
	numRows := len(tensor.Data) / lastDim
	output := NewTensor(shape, make([]float32, len(tensor.Data)), false)

	numWorkers := runtime.NumCPU()
	if numWorkers > 8 {
		numWorkers = 8
	}
	rowsPerWorker := (numRows + numWorkers - 1) / numWorkers

	var wg sync.WaitGroup
	for w := 0; w < numWorkers; w++ {
		start := w * rowsPerWorker
		end := (w + 1) * rowsPerWorker
		if start >= numRows {
			break
		}
		if end > numRows {
			end = numRows
		}
		wg.Add(1)
		go func(s, e int) {
			defer wg.Done()
			for i := s; i < e; i++ {
				offset := i * lastDim
				maxVal := float32(math.Inf(-1))
				for j := 0; j < lastDim; j++ {
					if tensor.Data[offset+j] > maxVal {
						maxVal = tensor.Data[offset+j]
					}
				}

				var sumExp float64
				for j := 0; j < lastDim; j++ {
					sumExp += math.Exp(float64(tensor.Data[offset+j] - maxVal))
				}

				for j := 0; j < lastDim; j++ {
					output.Data[offset+j] = float32(math.Exp(float64(tensor.Data[offset+j]-maxVal)) / sumExp)
				}
			}
		}(start, end)
	}
	wg.Wait()

	return output
}

// newVideoAsset applies what only holds for a video: a player has no alt
// attribute to fill, so the author cannot supply one, and the name that stands
// in keeps its extension because it goes where a filename would in a link.
func newVideoAsset(f asset, alt string) (UserAsset, error) {
	a := &videoAsset{f}
	if err := checkMaxSize(a.asset, maxVideoBytes, "videos"); err != nil {
		return nil, err
	}

	if alt != "" {
		return nil, errors.New("cannot set alt text on video")
	}
	a.alt = filepath.Base(a.path)

	return a, nil
}

// newImageAsset applies what only holds for an image: the author may write alt
// text, and the fallback mirrors the web uploader by stripping the extension
// and replacing the remaining dots with spaces.
func newImageAsset(f asset, alt string) (UserAsset, error) {
	a := &imageAsset{f}
	if err := checkMaxSize(a.asset, maxImageBytes, "images"); err != nil {
		return nil, err
	}

	if alt == "" {
		base := filepath.Base(a.path)
		alt = strings.ReplaceAll(strings.TrimSuffix(base, filepath.Ext(base)), ".", " ")
	}
	a.alt = alt

	if err := checkAltStaysInside(a); err != nil {
		return nil, err
	}

	return a, nil
}

// LocalNonPersistentFlags are flags specific to this command which will NOT persist to subcommands.
// This function does not modify the flags of the current command, it's purpose is to return the current state.
func (c *Command) LocalNonPersistentFlags() *flag.FlagSet {
	persistentFlags := c.PersistentFlags()

	out := flag.NewFlagSet(c.DisplayName(), flag.ContinueOnError)
	c.LocalFlags().VisitAll(func(f *flag.Flag) {
		if persistentFlags.Lookup(f.Name) == nil {
			out.AddFlag(f)
		}
	})
	return out
}

// offerRunGoCommand asks for confirmation, then runs a gocli command in
// the chat's working directory and prints its output. The answer is read
// through the chat's line reader so stdin stays on one reader.
func offerRunGoCommand(r *LineReader, cmd string) {
	cwd, _ := os.Getwd()
	if !stdinIsTerminal() {

		return
	}
	yn, err := r.ReadLine(fmt.Sprintf("[run it here? %s] [y/n]: ", cwd))
	if err != nil {
		fmt.Println("[cancelled]")
		return
	}
	yn = strings.ToLower(strings.TrimSpace(yn))
	if yn != "y" && yn != "yes" {
		fmt.Println("[not run]")
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	fields := strings.Fields(cmd)
	out, err := exec.CommandContext(ctx, fields[0], fields[1:]...).CombinedOutput()
	if len(out) > 0 {
		fmt.Printf("%s", out)
	}
	if err != nil {
		fmt.Printf("[exit: %v]\n", err)
		return
	}
	fmt.Println("[done]")
}

// offerRunMakeCommand asks for confirmation, then runs a makefile target
// in the repo root with output streaming straight to the terminal.
// There is no timeout: long targets (make smarter, make eval) need
// their time, and the user confirmed interactively. Ctrl-C interrupts.
func offerRunMakeCommand(r *LineReader, projectRoot, target string) {
	if !stdinIsTerminal() {

		return
	}
	yn, err := r.ReadLine(fmt.Sprintf("[run it here? 'make %s'] [y/n]: ", target))
	if err != nil {
		fmt.Println("[cancelled]")
		return
	}
	yn = strings.ToLower(strings.TrimSpace(yn))
	if yn != "y" && yn != "yes" {
		fmt.Println("[not run]")
		return
	}
	fmt.Printf("[running: make %s — Ctrl-C to interrupt]\n", target)

	cmd := exec.Command("make", target)
	cmd.Dir = projectRoot
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		fmt.Printf("[exit: %v]\n", err)
		return
	}
	fmt.Println("[done]")
}

