// recordingHandler attaches a record to the request context so the proxy can
// fill in the outcome, then writes exactly one line per request once the proxy
// is done with it.
func recordingHandler(proxy http.Handler, rec *recorder) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		entry := &record{
			Time:		time.Now().UTC().Format(time.RFC3339Nano),
			Method:		r.Method,
			Path:		r.URL.RequestURI(),
			Host:		r.Host,
			AuthHeader:	r.Header.Get("Authorization") != "",
		}
		proxy.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), recordKey{}, entry)))
		rec.Write(entry)
	})
}

// SetEmbedding attaches a vector embedding to a node. The slice is
// copied. It is a no-op for unknown IDs or a nil graph.
func (g *KnowledgeGraph) SetEmbedding(id string, emb []float32) {
	if g == nil {
		return
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	n, ok := g.Nodes[id]
	if !ok {
		return
	}
	cp := make([]float32, len(emb))
	copy(cp, emb)
	n.Embedding = cp
	g.Nodes[id] = n
}

// Error attaches an error to the current context. The error is pushed to a list of errors.
// It's a good idea to call Error for each error that occurred during the resolution of a request.
// A middleware can be used to collect all the errors and push them to a database together,
// print a log, or append it in the HTTP response.
// Error will panic if err is nil.
func (c *Context) Error(err error) *Error {
	if err == nil {
		panic("err is nil")
	}

	var parsedError *Error
	ok := errors.As(err, &parsedError)
	if !ok {
		parsedError = &Error{
			Err:	err,
			Type:	ErrorTypePrivate,
		}
	}

	c.Errors = append(c.Errors, parsedError)
	return parsedError
}

