// Decompose breaks a hard problem into simple steps.
// It uses pattern knowledge: what kinds of pieces are needed.
func Decompose(problem string) []Step {
	problem = strings.ToLower(problem)
	var steps []Step

	if strings.Contains(problem, "valid") {

		steps = append(steps, Step{
			Description:	"validation step",
			Prompt:		"write a function that validates input",
		})
	}

	if strings.Contains(problem, "create") || strings.Contains(problem, "make") || strings.Contains(problem, "new") {
		steps = append(steps, Step{
			Description:	"construction step",
			Prompt:		"write a function that creates a struct",
		})
	}

	if strings.Contains(problem, "http") || strings.Contains(problem, "handler") || strings.Contains(problem, "server") {
		steps = append(steps, Step{
			Description:	"http handler step",
			Prompt:		"write an http handler function",
		})
	}

	if len(steps) == 0 {
		steps = append(steps, Step{
			Description:	"single step",
			Prompt:		problem,
		})
	}

	return steps
}

// Expand broadcasts the current tensor to a larger shape by repeating data.
func (t *Tensor) Expand(shape []int) *Tensor {
	if t == nil {
		return nil
	}
	totalSize := 1
	for _, s := range shape {
		totalSize *= s
	}
	newData := make([]float32, totalSize)

	for i := 0; i < totalSize; i++ {
		newData[i] = t.Data[i%len(t.Data)]
	}
	return NewTensor(shape, newData, false)
}

