func NewLineReader(in io.Reader) *LineReader {
	r := &LineReader{in: in, histPos: -1}
	if f, ok := in.(*os.File); ok && rawSupported && isCharDevice(f) {
		r.term = f
		r.histPath = gollemerHistoryPath()
		r.history = loadHistory(r.histPath, 500)
