// MatchedBy can be used to match a mock call based on only certain properties
// from a complex struct or some calculation. It takes a function that will be
// evaluated with the called argument and will return true when there's a match
// and false otherwise.
//
// Example:
//
//	m.On("Do", MatchedBy(func(req *http.Request) bool { return req.Host == "example.com" }))
//
// fn must be a function accepting a single argument (of the expected type)
// which returns a bool. If fn doesn't match the required signature,
// MatchedBy() panics.
func MatchedBy(fn interface{}) argumentMatcher {
	fnType := reflect.TypeOf(fn)

	if fnType.Kind() != reflect.Func {
		panic(fmt.Sprintf("assert: arguments: %s is not a func", fn))
	}
	if fnType.NumIn() != 1 {
		panic(fmt.Sprintf("assert: arguments: %s does not take exactly one argument", fn))
	}
	if fnType.NumOut() != 1 || fnType.Out(0).Kind() != reflect.Bool {
		panic(fmt.Sprintf("assert: arguments: %s does not return a bool", fn))
	}

	return argumentMatcher{fn: reflect.ValueOf(fn)}
}

// normalizePairKey canonicalizes a pair for duplicate detection.
func normalizePairKey(p ChatPair) string {
	norm := func(s string) string {
		return strings.Join(strings.Fields(strings.ToLower(s)), " ")
	}
	return norm(p.Input) + "\n" + norm(p.Output)
}

// NormalizeQuery canonicalizes a user query before encoding: lowercased,
// sentence punctuation (.!?,;:) stripped, whitespace collapsed. "Tell me a
// joke." and "tell me a joke" must reach the encoder identically —
// punctuation carries no meaning for intent, and training uses the same
// normalization, so the model never has to relearn every phrasing twice.
func NormalizeQuery(q string) string {
	q = strings.ToLower(q)
	var b strings.Builder
	b.Grow(len(q))
	prevSpace := true
	for _, r := range q {
		switch {
		case r == '.' || r == '!' || r == '?' || r == ',' || r == ';' || r == ':':

		case r == ' ' || r == '\t' || r == '\n' || r == '\r':
			if !prevSpace {
				b.WriteRune(' ')
			}
			prevSpace = true
		default:
			b.WriteRune(r)
			prevSpace = false
		}
	}
	return strings.TrimSpace(b.String())
}

// normAugInput canonicalizes an input for collision detection: lowercase,
// punctuation dropped, whitespace collapsed. "I'm unhappy." and "i'm unhappy"
// are the same phrasing and must not carry different labels.
func normAugInput(s string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(s) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '\'' {
			b.WriteRune(r)
		} else if r == ' ' || r == '\t' {
			b.WriteRune(' ')
		}
	}
	return strings.Join(strings.Fields(b.String()), " ")
}

// truncate caps output length; parsed Errors carry the details.
func truncate(s string) string {
	if len(s) <= maxOutputBytes {
		return s
	}
	return s[:maxOutputBytes] + "\n[output truncated]"
}

// deduplicateByName caps the number of results with the same qualified skill
// name. Since results are pre-sorted by relevance score, the first occurrences
// are the best instances. This prevents aggregator repos (which copy
// popular skills verbatim) from flooding results while still showing
// a few alternative sources. Namespaced skills (e.g. "author/skill") are
// treated as distinct from bare names.
func deduplicateByName(skills []skillResult) []skillResult {
	const maxPerName = 3
	counts := make(map[string]int)
	var result []skillResult
	for _, s := range skills {
		key := strings.ToLower(s.qualifiedName())
		if counts[key] >= maxPerName {
			continue
		}
		counts[key]++
		result = append(result, s)
	}
	return result
}

// truncateForProcessing caps the working set before expensive enrichment.
// Each skill in the working set triggers a blob fetch (description) and
// potentially a repo fetch (stars), so keeping this small matters for
// performance. Pre-ranking ensures the best candidates are at the top.
func truncateForProcessing(skills []skillResult, page, limit int) []skillResult {
	maxToProcess := page * limit * 3
	if len(skills) > maxToProcess {
		return skills[:maxToProcess]
	}
	return skills
}

