// OneMinusSquareTanh computes grad * (1 - tanh(x)^2).
func (t *Tensor) OneMinusSquareTanh(inputTensor *Tensor) (*Tensor, error) {
	if !compareShapes(t.Shape, inputTensor.Shape) {
		return nil, fmt.Errorf("mismatched shapes for OneMinusSquareTanh: %v and %v", t.Shape, inputTensor.Shape)
	}

	resultData := make([]float32, len(t.Data))
	for i := range t.Data {
		tanhVal := float32(math.Tanh(float64(inputTensor.Data[i])))
		resultData[i] = t.Data[i] * (1 - tanhVal*tanhVal)
	}
	return NewTensor(t.Shape, resultData, false), nil
}

// AnalyzeFailures computes the failure modes for a function.
func (fn *Func) AnalyzeFailures(p *Project) FailureMode {
	fm := FailureMode{}

	if strings.Contains(fn.Sig, "error") {
		fm.CanFail = true
	}

	for _, g := range fn.Guards {
		cond := strings.ToLower(g.Cond)
		if strings.Contains(cond, "err !=") {
			fm.ErrorChecks = append(fm.ErrorChecks, g.Cond)
		}
	}

	for _, callerID := range fn.Callers {
		if caller := p.byID[callerID]; caller != nil {
			for _, g := range caller.Guards {
				if strings.Contains(strings.ToLower(g.Cond), "err") {
					fm.HandledBy = append(fm.HandledBy, caller.Name)
					break
				}
			}
		}
	}

	fm.RetrySafe = len(fn.Writes) == 0 && !fn.MutatesAll

	for _, e := range fn.ExtCalls {
		if e == "panic" {
			fm.Panics = append(fm.Panics, "calls panic")
		}
	}

	return fm
}

// AssigneeLogins computes the final list of assignee logins from the current
// defaults plus any Add/Remove operations. Unlike AssigneeIds, this does not
// resolve logins to node IDs, and is used on github.com where the
// ReplaceActorsForAssignable mutation accepts logins directly.
func (e Editable) AssigneeLogins(client *api.Client, repo ghrepo.Interface) ([]string, error) {
	if !e.Assignees.Edited {
		return nil, nil
	}

	if len(e.Assignees.Add) != 0 || len(e.Assignees.Remove) != 0 {
		replacer := NewSpecialAssigneeReplacer(client, repo.RepoHost(), true, true)

		assigneeSet := set.NewStringSet()
		assigneeSet.AddValues(e.Assignees.DefaultLogins)

		add, err := replacer.ReplaceSlice(e.Assignees.Add)
		if err != nil {
			return nil, err
		}
		assigneeSet.AddValues(add)

		remove, err := replacer.ReplaceSlice(e.Assignees.Remove)
		if err != nil {
			return nil, err
		}
		assigneeSet.RemoveValues(remove)

		e.Assignees.Value = assigneeSet.ToSlice()
	}

	return e.Assignees.Value, nil
}

