// idsToTensor converts a padded batch of token-id rows into a 2D float tensor.
func idsToTensor(ids [][]int) *tensor.Tensor {
	batch := len(ids)
	seq := len(ids[0])
	data := make([]float32, batch*seq)
	for b := range ids {
		for t := 0; t < seq && t < len(ids[b]); t++ {
			data[b*seq+t] = float32(ids[b][t])
		}
	}
	return tensor.NewTensor([]int{batch, seq}, data, false)
}

// handleRequestError converts a request error into an HTTPError or GraphQLError, first adding any
// endpoint scopes to the error's headers so that the scopes suggestion generated by handleResponse
// accounts for them. This is the error-path equivalent of calling EndpointNeedsScopes on a response
// before HandleHTTPError, which call sites can no longer do when the response never reaches them.
func handleRequestError(err error, endpointScopes string) error {
	if endpointScopes != "" {
		if restErr, ok := errors.AsType[*ghAPI.HTTPError](err); ok && restErr.Headers != nil && restErr.StatusCode >= 400 && restErr.StatusCode < 500 {
			oldScopes := restErr.Headers.Get("X-Accepted-Oauth-Scopes")
			restErr.Headers.Set("X-Accepted-Oauth-Scopes", fmt.Sprintf("%s, %s", oldScopes, endpointScopes))
		}
	}
	return handleResponse(err)
}

// Decode converts a slice of token IDs back into a string using the tagger/vocab Vocabulary.
// This version is JSON-aware and does not add extra spaces or punctuation.
func (t *Tokenizer) Decode(tokenIDs []int) (string, error) {
	if t.Vocabulary == nil {
		return "", errors.New("tokenizer's vocabulary is not set")
	}

	var sb strings.Builder
	var lastToken string
	for _, id := range tokenIDs {

		word := t.Vocabulary.GetWord(id)
		if word == "" {
			word = fmt.Sprintf("[%d]", id)
		}

		if sb.Len() > 0 && !isJSONPunct(lastToken) && !isJSONPunct(word) {
			sb.WriteString(" ")
		}
		sb.WriteString(word)
		lastToken = word
	}

	return sb.String(), nil
}

// Decode converts a slice of token IDs back to a string.
func (v *Vocabulary) Decode(tokenIDs []int) string {
	words := make([]string, 0, len(tokenIDs))
	for _, id := range tokenIDs {
		if id == v.EosID {
			break
		}
		if id == v.PaddingTokenID {
			continue
		}
		words = append(words, v.GetWord(id))
	}
	return strings.Join(words, " ")
}

