// countUnboundedAllocs counts append calls whose target slice has no
// statically known capacity: each is a potential growth reallocation.
func countUnboundedAllocs(file *ast.File) int {
	n := 0
	ast.Inspect(file, func(x ast.Node) bool {
		if call, ok := x.(*ast.CallExpr); ok {
			if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "append" {
				n++
			}
		}
		return true
	})
	return n
}

// visitStructFieldsDocs counts exported struct fields and their doc
// comments (go/doc shows trailing line comments as field docs).
func (m *styleMiner) visitStructFieldsDocs(st *ast.StructType) {
	if st == nil || st.Fields == nil {
		return
	}
	for _, field := range st.Fields.List {
		if field == nil {
			continue
		}
		for _, name := range field.Names {
			if name == nil || !name.IsExported() {
				continue
			}
			m.exportedIdents++
			if field.Doc != nil || field.Comment != nil {
				m.documented++
			}
		}
	}
}

// countAllocSites counts static allocation sites: make/new/append
// calls and composite literals.
func countAllocSites(file *ast.File) int {
	n := 0
	ast.Inspect(file, func(x ast.Node) bool {
		switch t := x.(type) {
		case *ast.CallExpr:
			if id, ok := t.Fun.(*ast.Ident); ok {
				switch id.Name {
				case "make", "new", "append":
					n++
				}
			}
		case *ast.CompositeLit:
			n++
		}
		return true
	})
	return n
}

