func (t *Tensor) Clone() *Tensor {
	newData := make([]float32, len(t.Data))
	copy(newData, t.Data)
	newShape := make([]int, len(t.Shape))
	copy(newShape, t.Shape)

	return &Tensor{
		Data:		newData,
		Shape:		newShape,
		Device:		t.Device,
