// ContextualRole determines the function's role from the call graph.
func (fn *Func) ContextualRole() Role {
	callers := len(fn.Callers)
	callees := len(fn.Calls)

	if fn.IsMain || fn.IsInit {
		return RoleEntryPoint
	}
	if callers == 0 && callees == 0 {
		return RoleIsolated
	}
	if callers == 0 {
		return RoleEntryPoint
	}
	if callees == 0 {
		return RoleLeaf
	}

	if callees >= 3 && callers <= 2 {
		return RoleCoordinator
	}

	if callers >= 3 && callees <= 2 {
		return RoleWorker
	}

	if callers >= 3 && callees >= 3 {
		return RoleHub
	}

	return RoleWorker
}

// ResolveRef determines the git ref to use for a given owner/repo.
// Priority: explicit version > latest release tag > default branch.
func ResolveRef(client *api.Client, host, owner, repo, version string) (*ResolvedRef, error) {
	if version != "" {
		return resolveExplicitRef(client, host, owner, repo, version)
	}
	ref, err := resolveLatestRelease(client, host, owner, repo)
	if err == nil {
		return ref, nil
	}

	if _, ok := errors.AsType[*noReleasesError](err); !ok {
		return nil, err
	}
	return resolveDefaultBranch(client, host, owner, repo)
}

// ParseTelemetryState determines the telemetry state based on environment variables and configuration values.
// The GH_TELEMETRY environment variable takes precedence, followed by DO_NOT_TRACK, then the configuration value.
// Recognized values for GH_TELEMETRY and config are "enabled", "disabled", "log", or any falsey value (e.g. "0", "false", "no") to disable telemetry.
func ParseTelemetryState(configValue string) TelemetryState {

	if envVal, ok := lookupEnvFunc("GH_TELEMETRY"); ok {
		envVal = strings.TrimSpace(strings.ToLower(envVal))

		if slices.Contains(falseyValues, envVal) {
			return Disabled
		}

		if envVal == "log" {
			return Logged
		}

		return Enabled
	}

	if envVal, ok := lookupEnvFunc("DO_NOT_TRACK"); ok {
		envVal = strings.TrimSpace(strings.ToLower(envVal))
		if envVal == "1" || envVal == "true" {
			return Disabled
		}
	}

	configValue = strings.TrimSpace(strings.ToLower(configValue))

	if slices.Contains(falseyValues, configValue) {
		return Disabled
	}

	if configValue == "log" {
		return Logged
	}

	return Enabled
}

// diffLists diffs two arrays/slices and returns slices of elements that are only in A and only in B.
// If some element is present multiple times, each instance is counted separately (e.g. if something is 2x in A and
// 5x in B, it will be 0x in extraA and 3x in extraB). The order of items in both lists is ignored.
func diffLists(listA, listB interface{}) (extraA, extraB []interface{}) {
	aValue := reflect.ValueOf(listA)
	bValue := reflect.ValueOf(listB)

	aLen := aValue.Len()
	bLen := bValue.Len()

	visited := make([]bool, bLen)
	for i := 0; i < aLen; i++ {
		element := aValue.Index(i).Interface()
		found := false
		for j := 0; j < bLen; j++ {
			if visited[j] {
				continue
			}
			if ObjectsAreEqual(bValue.Index(j).Interface(), element) {
				visited[j] = true
				found = true
				break
			}
		}
		if !found {
			extraA = append(extraA, element)
		}
	}

	for j := 0; j < bLen; j++ {
		if visited[j] {
			continue
		}
		extraB = append(extraB, bValue.Index(j).Interface())
	}

	return
}

