// problemStatement distills the issue body into a short problem
// description: the first meaningful lines after stripping the title,
// markdown headers, code fences, and unfilled template boilerplate.
func problemStatement(c IssueConcepts) string {
	body := fenceRe.ReplaceAllString(c.Body, "")
	title := strings.TrimSpace(c.Title)
	var keep []string
	for _, ln := range strings.Split(body, "\n") {
		t := strings.TrimSpace(ln)
		if t == "" || t == title {
			continue
		}
		if strings.HasPrefix(t, "A clear and concise description") {
			continue
		}
		if strings.HasPrefix(t, "#") ||
			(strings.HasPrefix(t, "**") && strings.HasSuffix(t, "**")) {

			if len(keep) > 0 {
				break
			}
			continue
		}
		keep = append(keep, t)
		if len(keep) >= 3 {
			break
		}
	}
	s := strings.Join(strings.Fields(strings.Join(keep, " ")), " ")
	if len(s) > 400 {
		s = s[:397] + "..."
	}
	if s == "" {
		return title
	}
	return s
}

// updateRouteTree do update to the route tree recursively
func updateRouteTree(n *node) {
	n.path = strings.ReplaceAll(n.path, escapedColon, colon)
	n.fullPath = strings.ReplaceAll(n.fullPath, escapedColon, colon)
	n.indices = strings.ReplaceAll(n.indices, backslash, colon)
	if n.children == nil {
		return
	}
	for _, child := range n.children {
		updateRouteTree(child)
	}
}

// updateRouteTrees do update to the route trees
func (engine *Engine) updateRouteTrees() {
	for _, tree := range engine.trees {
		updateRouteTree(tree.root)
	}
}

