// fetchExpectedChecksum downloads the SHA256SUMS.txt file and returns the expected checksum for the given archive name.
func fetchExpectedChecksum(httpClient *http.Client, checksumsURL safeurl.SafeURL, archiveName string) (string, error) {
	resp, err := httpClient.Get(checksumsURL.String())
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("failed to download checksums: %s", resp.Status)
	}

	scanner := bufio.NewScanner(resp.Body)
	for scanner.Scan() {
		line := scanner.Text()
		fields := strings.Fields(line)
		if len(fields) >= 2 {
			checksum := fields[0]
			filename := fields[1]
			if filename == archiveName {
				return checksum, nil
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return "", fmt.Errorf("failed to read checksums: %w", err)
	}

	return "", fmt.Errorf("checksum not found for %s", archiveName)
}

// diagramBox draws a titled box of fixed inner width. When outlet is
// true the bottom border carries a ┬ where the next arrow continues.
func diagramBox(title string, rows []string, outlet bool) string {
	var b strings.Builder
	bar := strings.Repeat("─", diagramWidth)
	b.WriteString("┌" + bar + "┐\n")
	b.WriteString("│" + padCenter(title, diagramWidth) + "│\n")
	b.WriteString("├" + bar + "┤\n")
	for _, r := range rows {
		b.WriteString("│" + padRight(r, diagramWidth) + "│\n")
	}
	if outlet {
		b.WriteString("└" + strings.Repeat("─", diagramWidth/2) + "┬" +
			strings.Repeat("─", diagramWidth/2-1) + "┘")
	} else {
		b.WriteString("└" + bar + "┘")
	}
	return b.String()
}

