// rootIdent drills through selector chains to the base identifier:
// f.Body.Close -> f.
func rootIdent(e ast.Expr) *ast.Ident {
	for {
		switch t := e.(type) {
		case *ast.Ident:
			return t
		case *ast.SelectorExpr:
			e = t.X
		default:
			return nil
		}
	}
}

// cleanStepDesc drops a description that merely echoes the title
// ("Main — calls worker." for title "Main" becomes "calls worker").
func cleanStepDesc(desc, title string) string {
	desc = strings.TrimSpace(desc)
	if desc == "" {
		return ""
	}
	if strings.HasPrefix(desc, title) {
		desc = strings.TrimSpace(strings.TrimPrefix(desc, title))
		desc = strings.TrimPrefix(desc, "—")
		desc = strings.TrimPrefix(desc, "-")
		desc = strings.TrimSpace(desc)
	}

	if strings.Trim(desc, ".!") == "" {
		return ""
	}
	return desc
}

// invalidate drops facts mentioning k (e.g. after k is reassigned).
func (e *pathEnv) invalidate(k varKey) {
	prefix := k.String() + "<"
	for f := range e.facts {
		if strings.HasPrefix(f, prefix) {
			delete(e.facts, f)
		}
	}
}

// unescapePunctuation drops the backslash from every backslash-escaped ASCII
// punctuation character, which is how markdown spells a literal one.
func unescapePunctuation(s string) string {
	if !strings.Contains(s, `\`) {
		return s
	}
	const punct = `!"#$%&'()*+,-./:;<=>?@[\]^_` + "`" + `{|}~`
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); {
		if s[i] == '\\' && i+1 < len(s) && strings.IndexByte(punct, s[i+1]) >= 0 {
			i++
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String()
}

// withoutPath drops the path from a file system error about the file itself,
// since the result line already names it. Such an error can name the file by
// the path given, by its name in the directory opened for it, or by the open
// file's full path, so only the last element is compared.
func withoutPath(err error, path string) error {
	if pathErr, ok := errors.AsType[*fs.PathError](err); ok && filepath.Base(pathErr.Path) == filepath.Base(path) {
		return pathErr.Err
	}
	return err
}

// trimTrailingSeparators drops the separators that end path, but keeps a root
// such as / or C:\ whole.
func trimTrailingSeparators(path string) string {
	end := len(path)
	for end > len(filepath.VolumeName(path))+1 && os.IsPathSeparator(path[end-1]) {
		end--
	}
	return path[:end]
}

