			if _, ok := errors.AsType[safepaths.PathTraversalError](err); ok {
				continue
			}
			return fmt.Errorf("error extracting %q: %w", zf.Name, err)
		}
	}
	return nil
}

// FromURL extracts the GitHub repository information from a git remote URL
func FromURL(u *url.URL) (Interface, error) {
	if u.Hostname() == "" {
		return nil, fmt.Errorf("no hostname detected")
	}

	parts := strings.SplitN(strings.Trim(u.Path, "/"), "/", 3)
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid path: %s", u.Path)
	}

	return NewWithHost(parts[0], strings.TrimSuffix(parts[1], ".git"), u.Hostname()), nil
}

// FromFullName extracts the GitHub repository information from the following
// formats: "OWNER/REPO", "HOST/OWNER/REPO", and a full URL.
func FromFullName(nwo string) (Interface, error) {
	return FromFullNameWithHost(nwo, defaultHost())
}

// methodName extracts the new method's name: "Implement Info method"
// -> "Info". Generic verbs ("Add method", "new method") don't count.
func methodName(c IssueConcepts) string {
	for _, m := range methodRe.FindAllStringSubmatch(c.Title, -1) {
		n := m[1]
		if planStopwords[strings.ToLower(n)] {
			continue
		}
		return strings.ToUpper(n[:1]) + n[1:]
	}
	return ""
}

// nextPage extracts the next page number from an API response's link header. if
// the provided link header is empty or there is no next page, zero is returned.
//
// See API [docs] on pagination for more information.
//
// [docs]: https://docs.github.com/en/rest/using-the-rest-api/using-pagination-in-the-rest-api
func nextPage(link string) (page int) {

	for _, m := range linkRE.FindAllStringSubmatch(link, -1) {
		if !(len(m) > 2 && m[2] == "next") {
			continue
		}
		p := pageRE.FindStringSubmatch(m[1])
		if len(p) == 3 {
			i, err := strconv.Atoi(p[2])
			if err == nil {
				return i
			}
		}
	}
	return 0
}

// parseWhereTask extracts the task description from "where would I add X".
// It strips a trailing path ("... in ~/foo" / "... in this project").
func parseWhereTask(line string) (task string, isWhere bool) {
	m := whereTask.FindStringSubmatch(line)
	if m == nil {
		return "", false
	}
	task = strings.TrimSpace(m[2])

	if i := strings.LastIndex(task, " in "); i > 0 {
		task = strings.TrimSpace(task[:i])
	}
	task = strings.Trim(task, `"'.,`)
	if task == "" {
		return "", false
	}
	return task, true
}

