// deduplicateResults extracts unique (repo, namespace, skill name) triples from code search hits.
func deduplicateResults(items []codeSearchItem) []skillResult {
	// skillResultKey is a typed map key that deduplicates by (repo, namespace,
	// skill name). All fields are lowercased for case-insensitive comparison.
	type skillResultKey struct {
		repo		string
		namespace	string
		skillName	string
	}
	seen := make(map[skillResultKey]struct{})
	var results []skillResult

	for _, item := range items {
		skillName, namespace := extractSkillInfo(item.Path)
		if skillName == "" {
			continue
		}
		key := skillResultKey{
			repo:		strings.ToLower(item.Repository.FullName),
			namespace:	strings.ToLower(namespace),
			skillName:	strings.ToLower(skillName),
		}
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}

		owner, repoName := splitRepo(item.Repository.FullName)
		results = append(results, skillResult{
			Repo:		item.Repository.FullName,
			Owner:		owner,
			RepoName:	repoName,
			SkillName:	skillName,
			Namespace:	namespace,
			Path:		item.Path,
			BlobSHA:	item.SHA,
		})
	}

	return results
}

// Parse extracts YAML frontmatter from a SKILL.md file.
// Frontmatter is delimited by --- on its own lines.
func Parse(content string) (*ParseResult, error) {
	trimmed := strings.TrimLeft(content, "\r\n")
	if !strings.HasPrefix(trimmed, delimiter) {
		return &ParseResult{Body: content}, nil
	}

	rest := trimmed[len(delimiter):]
	rest = strings.TrimLeft(rest, "\r\n")
	before, after, ok := strings.Cut(rest, "\n"+delimiter)
	if !ok {
		return &ParseResult{Body: content}, nil
	}

	yamlContent := before
	body := after
	body = strings.TrimLeft(body, "\r\n")

	var rawYAML map[string]any
	if err := yaml.Unmarshal([]byte(yamlContent), &rawYAML); err != nil {
		return nil, fmt.Errorf("invalid frontmatter YAML: %w", err)
	}

	var meta Metadata
	if err := yaml.Unmarshal([]byte(yamlContent), &meta); err != nil {
		return nil, fmt.Errorf("invalid frontmatter YAML: %w", err)
	}

	return &ParseResult{
		Metadata:	meta,
		Body:		body,
		RawYAML:	rawYAML,
	}, nil
}

// fail fails the current test with the given formatted format and args.
// In case that a test was defined, it uses the test APIs for failing a test,
// otherwise it uses panic.
func (m *Mock) fail(format string, args ...interface{}) {
	m.mutex.Lock()
	defer m.mutex.Unlock()

	if m.test == nil {
		panic(fmt.Sprintf(format, args...))
	}
	m.test.Errorf(format, args...)
	m.test.FailNow()
}

