// linkInternal fills each package's Internal list from its Imports.
func (p *Project) linkInternal() {
	for _, pkg := range p.Packages {
		var internal []string
		for _, imp := range pkg.Imports {
			if target := p.importTarget(imp); target != nil {
				dir := target.Dir
				if dir != pkg.Dir && !contains(internal, dir) {
					internal = append(internal, dir)
				}
			}
		}
		sort.Strings(internal)
		pkg.Internal = internal
	}
}

// propagateEffects fills EffectsAll (transitive effect categories) by
// fixpoint over the call graph, then derives Mutates/MutatesAll from the
// fs-write category.
func (p *Project) propagateEffects() {
	for _, fn := range p.byID {
		set := map[string]bool{}
		for _, e := range fn.ExtCalls {
			for _, c := range callEffects[e] {
				set[c] = true
			}
		}
		fn.Effects = sortedKeys(set)
	}
	for changed := true; changed; {
		changed = false
		for _, fn := range p.byID {
			set := map[string]bool{}
			for _, c := range fn.EffectsAll {
				set[c] = true
			}
			for _, c := range fn.Effects {
				if !set[c] {
					set[c] = true
					changed = true
				}
			}
			for _, id := range fn.Calls {
				if g := p.byID[id]; g != nil {
					for _, c := range g.EffectsAll {
						if !set[c] {
							set[c] = true
							changed = true
						}
					}
				}
			}
			fn.EffectsAll = sortedKeys(set)
		}
	}
	for _, fn := range p.byID {
		fn.Mutates = hasEffect(fn.Effects, fxWrite)
		fn.MutatesAll = hasEffect(fn.EffectsAll, fxWrite)
	}
}

// parseMakeDocs fills makeTargetDocs and makeTargetRecipes from the raw
// Makefile text. "## target: description" lines give the docs (with "#"
// continuation lines joined in); indented lines after "target:" give the
// recipe preview.
func parseMakeDocs(data string) {
	lines := strings.Split(data, "\n")
	for i, line := range lines {
		if m := makeDocLine.FindStringSubmatch(line); m != nil {
			doc := m[2]

			for j := i + 1; j < len(lines); j++ {
				c := strings.TrimSpace(lines[j])
				if strings.HasPrefix(c, "#") && !strings.HasPrefix(c, "##") {
					rest := strings.TrimSpace(strings.TrimPrefix(c, "#"))
					if rest == "" {
						break
					}
					doc += " " + rest
				} else {
					break
				}
			}
			makeTargetDocs[m[1]] = doc
		}
		if m := makeTargetLine.FindStringSubmatch(line); m != nil {
			var recipe []string
			for j := i + 1; j < len(lines) && len(recipe) < 6; j++ {
				rl := lines[j]
				if rl == "" {
					break
				}
				if rl[0] == '\t' || rl[0] == ' ' {
					recipe = append(recipe, strings.TrimSpace(rl))
				} else {
					break
				}
			}
			if len(recipe) > 0 {
				makeTargetRecipes[m[1]] = recipe
			}
		}
	}
}

