// preallocateSlices finds `var s []T` + counted append loop patterns
// and rewrites them to `s := make([]T, 0, N)`.
func preallocateSlices(file *ast.File, rep *OptimizationReport) {
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		ast.Inspect(fn.Body, func(x ast.Node) bool {
			if blk, ok := x.(*ast.BlockStmt); ok {
				preallocateInBlock(blk, rep)
			}
			return true
		})
	}
}

// MatchCategory finds a category by name or slug (case-insensitive).
// It prefers an exact slug match over a name match, so users are
// encouraged to use slugs for unambiguous lookups.
func MatchCategory(input string, categories []client.DiscussionCategory) (*client.DiscussionCategory, error) {
	for i := range categories {
		if strings.EqualFold(categories[i].Slug, input) {
			return &categories[i], nil
		}
	}
	for i := range categories {
		if strings.EqualFold(categories[i].Name, input) {
			return &categories[i], nil
		}
	}

	slugs := make([]string, len(categories))
	for i, c := range categories {
		slugs[i] = c.Slug
	}
	slices.Sort(slugs)
	return nil, fmt.Errorf("unknown category: %q; must be one of: %s", input, strings.Join(slugs, ", "))
}

// extractAnalyzePath finds a filesystem path or GitHub URL in the message.
func extractAnalyzePath(line string) string {
	if m := quotedPath.FindStringSubmatch(line); m != nil {
		for _, g := range m[1:] {
			if g != "" {
				return g
			}
		}
	}
	if u := githubURL.FindString(line); u != "" {
		return u
	}
	lower := strings.ToLower(line)
	for _, phrase := range []string{"this project", "this repo", "this repository", "this codebase"} {
		if strings.Contains(lower, phrase) {
			return unifiedProjectRoot
		}
	}
	for _, tok := range strings.Fields(line) {
		clean := strings.TrimRight(tok, `.,;:!?`)

		clean = strings.TrimPrefix(clean, `"`)
		clean = strings.TrimPrefix(clean, `'`)
		clean = strings.TrimPrefix(clean, "(")
		clean = strings.TrimPrefix(clean, "[")
		clean = strings.TrimSuffix(clean, `"`)
		clean = strings.TrimSuffix(clean, `'`)
		clean = strings.TrimSuffix(clean, ")")
		clean = strings.TrimSuffix(clean, "]")
		if clean == "and/or" {
			continue
		}
		if strings.Contains(clean, "/") || strings.HasPrefix(clean, "~") {
			return clean
		}
	}
	return ""
}

