		"name":		githubv4.String(repo.RepoName()),
	}

	if err := client.Query(repo.RepoHost(), "FindRepoBranchID", &query, variables); err != nil {
		return "", "", err
	}

	branchID := query.Repository.Ref.Target.Oid
	if branchID == "" {
