				fields[strings.ToLower(f)] = true
			}
			var hits, newKeys []string
			for _, k := range keys {
				if fields[k] {
					hits = append(hits, k)
				} else {
					newKeys = append(newKeys, k)
				}
			}
			if len(hits) >= 2 {
				out = append(out, ConfigMatch{
					Type:	t,
					Pkg:	pkg,
					Hits:	hits,
					New:	newKeys,
					Score:	len(hits),
				})
			}
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Score != out[j].Score {
			return out[i].Score > out[j].Score
		}
		if out[i].Type.Exported != out[j].Type.Exported {
			return out[i].Type.Exported
		}
		return len(out[i].Type.Fields) < len(out[j].Type.Fields)
	})
	return out
}

// tidyDecode fixes the spacing the word-join decoder leaves around punctuation.
func tidyDecode(s string) string {
	for _, p := range []string{"?", "!", ".", ",", ":", ";", "'"} {
		s = strings.ReplaceAll(s, " "+p, p)
	}
	s = strings.ReplaceAll(s, "  ", " ")
	return strings.TrimSpace(s)
}

// docText flattens a comment group to one line.
func docText(cg *ast.CommentGroup) string {
	if cg == nil {
		return ""
	}
	t := strings.TrimSpace(cg.Text())
	t = strings.Join(strings.Fields(t), " ")
	if len(t) > 220 {
		t = t[:217] + "..."
	}
	return t
}

// chainExamples follows an if/else-if chain and collects the conditions
// that compare against a literal, e.g. `if line == "/flow"`.
func chainExamples(fset *token.FileSet, src []byte, s *ast.IfStmt) ([]string, int, bool) {
	var conds []string
	cur := s
	for cur != nil {
		if comparesLiteral(cur.Cond) {
			conds = append(conds, "if "+truncateRunes(nodeText(fset, src, cur.Cond), 56))
		}
		els, ok := cur.Else.(*ast.IfStmt)
		if !ok {
			break
		}
		cur = els
	}
	ex, more := capExamples(conds, 5)
	return ex, more, true
}

