// ForkRepo forks the repository on GitHub and returns the new repository
func ForkRepo(client *Client, repo ghrepo.Interface, org, newName string, defaultBranchOnly bool) (*Repository, error) {
	path, err := safeurl.JoinPath("repos", repo.RepoOwner(), repo.RepoName(), "forks")
	if err != nil {
		return nil, err
	}

	params := map[string]any{}
	if org != "" {
		params["organization"] = org
	}
	if newName != "" {
		params["name"] = newName
	}
	if defaultBranchOnly {
		params["default_branch_only"] = true
	}

	body := &bytes.Buffer{}
	enc := json.NewEncoder(body)
	if err := enc.Encode(params); err != nil {
		return nil, err
	}

	result := repositoryV3{}
	err = client.REST(repo.RepoHost(), "POST", path.String(), body, &result)
	if err != nil {
		return nil, err
	}

	newRepo := &Repository{
		ID:		result.NodeID,
		Name:		result.Name,
		CreatedAt:	result.CreatedAt,
		Owner: RepositoryOwner{
			Login: result.Owner.Login,
		},
		ViewerPermission:	"WRITE",
		hostname:		repo.RepoHost(),
	}

	if ghrepo.IsSame(repo, newRepo) {
		return newRepo, fmt.Errorf("%s cannot be forked. A single user account cannot own both a parent and fork.", ghrepo.FullName(repo))
	}

	return newRepo, nil
}

// FormatSize formats a byte count using binary units (B, KB, MB, GB, TB, PB).
// Values below a kilobyte are shown as whole bytes; larger values are shown with
// one decimal place of precision.
func FormatSize(n int64) string {
	const unit = 1024
	if n < unit {
		return fmt.Sprintf("%d B", n)
	}

	units := []string{"KB", "MB", "GB", "TB", "PB"}

	div, exp := int64(unit), 0
	for v := n / unit; v >= unit && exp < len(units)-1; v /= unit {
		div *= unit
		exp++
	}

	value := float64(n) / float64(div)
	return fmt.Sprintf("%.1f %s", value, units[exp])
}

