// Fire forwards the provided logrus Entry to the underlying slog.Logger's
// Handler, mapping it to a slog.Record. Time and caller information are
// preserved when available, and Entry.Data is converted to attributes.
// If Entry.Context is nil, context.Background() is used.
func (h *Hook) Fire(entry *logrus.Entry) error {
	ctx := entry.Context
	if ctx == nil {
		ctx = context.Background()
	}

	ctx = withLogrusLogger(ctx, entry.Logger)

	level := h.toSlogLevel(entry.Level)
	handler := h.logger.Handler()
	if !handler.Enabled(ctx, level) {
		return nil
	}
	attrs := make([]slog.Attr, 0, len(entry.Data))
	for k, v := range entry.Data {
		attrs = append(attrs, slog.Any(k, v))
	}
	var pc uintptr
	if entry.Caller != nil {
		pc = entry.Caller.PC
	}
	r := slog.NewRecord(entry.Time, level, entry.Message, pc)
	r.AddAttrs(attrs...)
	return handler.Handle(ctx, r)
}

// ForwardPortToListener forwards the specified port to the given TCP listener.
func (fwd *CodespacesPortForwarder) ForwardPortToListener(ctx context.Context, opts ForwardPortOpts, listener *net.TCPListener) error {
	err := fwd.ForwardPort(ctx, opts)
	if err != nil {
		return fmt.Errorf("error forwarding port: %w", err)
	}

	done := make(chan error)
	go func() {

		port, err := convertIntToUint16(opts.Port)
		if err != nil {
			done <- fmt.Errorf("error converting port: %w", err)
			return
		}

		err = fwd.connection.TunnelClient.WaitForForwardedPort(ctx, port)
		if err != nil {
			done <- fmt.Errorf("wait for forwarded port failed: %v", err)
			return
		}

		err = fwd.connectListenerToForwardedPort(ctx, opts, listener)
		if err != nil {
			done <- fmt.Errorf("connect to forwarded port failed: %v", err)
		}
	}()

	select {
	case err := <-done:
		if err != nil {
			return fmt.Errorf("error connecting to tunnel: %w", err)
		}
		return nil
	case <-ctx.Done():
		return nil
	}
}

