func (l *LSTM) GetInputGradStep(t int) *Tensor {
	if l.timeStepCells == nil || t < 0 || t >= len(l.timeStepCells[0]) {
		return nil
	}
	return l.timeStepCells[0][t].InputTensor.Grad
}

func (l *LSTM) GetInputGrad() *Tensor {
	if len(l.timeStepCells) > 0 && len(l.timeStepCells[0]) > 0 {
		creator := l.timeStepCells[0][0].InputTensor.Creator
		if creator != nil {
			if t, ok := creator.(*Tensor); ok {
				return t.Grad
			}
		}
	}
	return nil
}

// PushRevision gets the value of the @{push} revision syntax
// An error here doesn't necessarily mean something is broken, but may mean that the @{push}
// revision syntax couldn't be resolved, such as in non-centralized workflows with
// push.default = simple. Downstream consumers should consider how to handle this error.
func (c *Client) PushRevision(ctx context.Context, branch string) (RemoteTrackingRef, error) {
	revParseOut, err := c.revParse(ctx, "--symbolic-full-name", branch+"@{push}")
	if err != nil {
		return RemoteTrackingRef{}, err
	}

	ref, err := ParseRemoteTrackingRef(firstLine(revParseOut))
	if err != nil {
		return RemoteTrackingRef{}, fmt.Errorf("could not parse push revision: %v", err)
	}

	return ref, nil
}

// Is gets whether the objects match the arguments specified.
func (args Arguments) Is(objects ...interface{}) bool {
	for i, obj := range args {
		if obj != objects[i] {
			return false
		}
	}
	return true
}

// isEmpty gets whether the specified object is considered empty or not.
func isEmpty(object interface{}) bool {

	if object == nil {
		return true
	}

	return isEmptyValue(reflect.ValueOf(object))
}

// isEmptyValue gets whether the specified reflect.Value is considered empty or not.
func isEmptyValue(objValue reflect.Value) bool {
	if objValue.IsZero() {
		return true
	}

	switch objValue.Kind() {

	case reflect.Chan, reflect.Map, reflect.Slice:
		return objValue.Len() == 0

	case reflect.Ptr:
		return isEmptyValue(objValue.Elem())
	}
	return false
}

// IsTTY gets whether the TablePrinter will render to a terminal.
func (t *TablePrinter) IsTTY() bool {
	return t.isTTY
}

// ObjectsAreEqualValues gets whether two objects are equal, or if their
// values are equal.
func ObjectsAreEqualValues(expected, actual interface{}) bool {
	if ObjectsAreEqual(expected, actual) {
		return true
	}

	expectedValue := reflect.ValueOf(expected)
	actualValue := reflect.ValueOf(actual)
	if !expectedValue.IsValid() || !actualValue.IsValid() {
		return false
	}

	expectedType := expectedValue.Type()
	actualType := actualValue.Type()
	if !expectedType.ConvertibleTo(actualType) {
		return false
	}

	if !isNumericType(expectedType) || !isNumericType(actualType) {

		return reflect.DeepEqual(
			expectedValue.Convert(actualType).Interface(), actual,
		)
	}

	if expectedType.Size() >= actualType.Size() {
		return actualValue.Convert(expectedType).Interface() == expected
	}

	return expectedValue.Convert(actualType).Interface() == actual
}

// handleFlowCommand handles "/flow <prompt>": it runs the prompt through
// the reactive engine pipeline (synthesis, safety proving, auto-tuning,
// visual trace) in-process and returns the beginner-friendly rendering.
// The engine is imported directly: no subprocess, no shell.
func handleFlowCommand(line string) (string, bool) {
	if line != "/flow" && !strings.HasPrefix(line, "/flow ") {
		return "", false
	}
	prompt := strings.TrimSpace(strings.TrimPrefix(line, "/flow"))
	if prompt == "" {
		return "usage: /flow <prompt> — e.g. /flow create a worker pool", true
	}
	ctx, cancel := context.WithTimeout(context.Background(), flowTimeout)
	defer cancel()
	res, err := engine.ExecutePipeline(ctx, prompt, nil)
	if err != nil {
		return fmt.Sprintf("flow error: %v", err), true
	}
	return res.RenderDiagram(prompt) + "\n\n" + res.RenderBeginner(), true
}

