// answerWhyCalls handles "why does X call Y": the callee's purpose in
// infinitive form, plus the guard the call sits inside, if any.
func (p *Project) answerWhyCalls(callerName, calleeName string) (string, bool) {
	caller, _, _, _ := p.resolve(callerName)
	callee, _, _, _ := p.resolve(calleeName)
	if caller == nil || callee == nil {
		return "", false
	}
	callsIt := false
	for _, id := range caller.Calls {
		if id == callee.ID {
			callsIt = true
			break
		}
	}
	if !callsIt {
		return fmt.Sprintf("%s doesn't call %s.", caller.Display(), callee.Display()), true
	}
	vp := verbPhrase(callee.Name, false)
	if strings.HasPrefix(vp, "handles ") {

		return fmt.Sprintf("%s calls %s. %s", caller.Display(), callee.Display(), callee.Intent()), true
	}
	var b strings.Builder
	fmt.Fprintf(&b, "%s calls %s to %s.", caller.Display(), callee.Display(), vp)
	for _, g := range caller.Guards {
		for _, id := range g.Calls {
			if id == callee.ID {
				fmt.Fprintf(&b, " (inside the `%s` check)", g.Cond)
				break
			}
		}
	}
	return b.String(), true
}

func (l *LSTM) BackwardStep(gradH, gradC *Tensor, timestep int) error {
	if l.timeStepCells == nil || timestep < 0 || timestep >= len(l.timeStepCells[0]) {
		return fmt.Errorf("invalid timestep for BackwardStep")
	}

	currentGradH := gradH
	currentGradC := gradC

	for layer := l.NumLayers - 1; layer >= 0; layer-- {
		cell := l.timeStepCells[layer][timestep]
		err := cell.Backward(currentGradH, currentGradC)
		if err != nil {
			return err
		}
		currentGradH = cell.InputTensor.Grad
		currentGradC = cell.PrevCell.Grad
	}
	return nil
}

// tryDirectRunMake handles a bare "run make <target>" typed by the user:
// the target is validated against the Makefile allowlist and, when valid,
// the reply is printed and the run is offered — no brain needed.
func tryDirectRunMake(line string, r *LineReader, projectRoot string, conv *Conversation) bool {
	m := directRunMakeRe.FindStringSubmatch(line)
	if m == nil {
		return false
	}
	target := strings.ToLower(m[1])
	if t := runnableMakeTarget("run make " + target); t != "" {
		out := "run make " + t
		fmt.Printf("gollemer [%s]> %s\n", MakefileDomain, out)
		conv.AddReply(out, MakefileDomain, false)
		offerRunMakeCommand(r, projectRoot, t)
		return true
	}

	if isMakeTarget(target) {
		out := fmt.Sprintf("make %s starts a nested chat session — I can't run that from inside the chat.", target)
		fmt.Printf("gollemer [%s]> %s\n", MakefileDomain, out)
		conv.AddReply(out, MakefileDomain, false)
		return true
	}
	out := fmt.Sprintf("I don't know a make target called %q. Say \"list the commands\" to see them all.", target)
	fmt.Printf("gollemer [%s]> %s\n", MakefileDomain, out)
	conv.AddReply(out, MakefileDomain, false)
	return true
}

// tryBareMakeTarget handles a bare target name typed on its own
// ("eval", "explain", "smarter"): the chat treats it as
// "run make <target>" — validated against the Makefile allowlist and
// offered immediately. Only a single token ever matches, so normal
// sentences ("help me", "start over") can't trip it.
func tryBareMakeTarget(line string, r *LineReader, projectRoot string, conv *Conversation) bool {
	fields := strings.Fields(line)
	if len(fields) != 1 {
		return false
	}
	target := strings.ToLower(strings.Trim(fields[0], "?!.,;:"))
	if t := runnableMakeTarget("run make " + target); t != "" {
		out := "run make " + t
		fmt.Printf("gollemer [%s]> %s\n", MakefileDomain, out)
		conv.AddReply(out, MakefileDomain, false)
		offerRunMakeCommand(r, projectRoot, t)
		return true
	}
	return false
}

