func (b *builder) callEdge(srcID string, call *ast.CallExpr, recvName, recvType string) {
	switch fun := call.Fun.(type) {
	case *ast.Ident:

		if _, isType := b.types[fun.Name]; isType {
			return
		}
		if tid, ok := b.funcs[fun.Name]; ok {
			b.addEdge(srcID, tid, RelationCalls)
		}
	case *ast.SelectorExpr:
		x, ok := fun.X.(*ast.Ident)
		if !ok || x == nil {
			return
		}
		if b.imports[x.Name] {
			return
		}
		b.methodCallEdge(srcID, x.Name, fun.Sel.Name, recvName, recvType)
	}
}

func (a *analyzer) callSignature(call *ast.CallExpr) *types.Signature {
	if a.info == nil || call == nil {
		return nil
	}
	sig, _ := a.info.TypeOf(call.Fun).(*types.Signature)
	return sig
}

func callString(method string, arguments Arguments, includeArgumentValues bool) string {
	var argValsString string
	if includeArgumentValues {
		var argVals []string
		for argIndex, arg := range arguments {
			if _, ok := arg.(*FunctionalOptionsArgument); ok {
				argVals = append(argVals, fmt.Sprintf("%d: %s", argIndex, arg))
				continue
			}
			argVals = append(argVals, fmt.Sprintf("%d: %#v", argIndex, arg))
		}
		argValsString = fmt.Sprintf("\n\t\t%s", strings.Join(argVals, "\n\t\t"))
	}

	return fmt.Sprintf("%s(%s)%s", method, arguments.String(), argValsString)
}

