	if force {
		path, err = safeurl.JoinPath("repos", repo.RepoOwner(), repo.RepoName(), "actions", "runs", runID, "force-cancel")
	} else {
		path, err = safeurl.JoinPath("repos", repo.RepoOwner(), repo.RepoName(), "actions", "runs", runID, "cancel")
	}
	if err != nil {
		return err
	}

	err = client.REST(repo.RepoHost(), "POST", path.String(), nil, nil)
	if err != nil {
		return err
	}

	return nil
}

func CapiClientFunc(f *cmdutil.Factory) func() (capi.CapiClient, error) {
	return func() (capi.CapiClient, error) {
		cfg, err := f.Config()
		if err != nil {
			return nil, err
		}

		httpClient, err := f.HttpClient()
		if err != nil {
			return nil, err
		}

		authCfg := cfg.Authentication()
		host, _ := authCfg.DefaultHost()
		token, _ := authCfg.ActiveToken(host)

		cachedClient := api.NewCachedHTTPClient(httpClient, time.Minute*10)
		capiBaseURL, err := resolveCapiURL(cachedClient, host)
		if err != nil {
			return nil, fmt.Errorf("failed to resolve Copilot API URL: %w", err)
		}

		return capi.NewCAPIClient(httpClient, token, host, capiBaseURL), nil
	}
}

func capitalize(s string) string {
	if s == "" {
		return ""
	}
	r := []rune(s)
	if r[0] >= 'a' && r[0] <= 'z' {
		r[0] -= 'a' - 'A'
	}
	return string(r)
}

func CategorizeHost(host string) string {
	if host == defaultHostname {
		return "github.com"
	}

	if ghauth.IsEnterprise(host) {
		return "ghes"
	}

	if ghauth.IsTenancy(host) {
		return "tenancy"
	}

	return "uncategorized"
}

func changelogURL(version string) string {
	path := "https://github.com/cli/cli"
	r := regexp.MustCompile(`^v?\d+\.\d+\.\d+(-[\w.]+)?$`)
	if !r.MatchString(version) {
		return fmt.Sprintf("%s/releases/latest", path)
	}

	url := fmt.Sprintf("%s/releases/tag/v%s", path, strings.TrimPrefix(version, "v"))
	return url
}

func (a *analyzer) checkDeref(x ast.Expr, env *pathEnv, what string) {
	id, ok := x.(*ast.Ident)
	if !ok || id.Name == "_" {
		return
	}
	key := a.vkey(id)
	switch env.nils[key] {
	case nilIsNil:
		a.addViolation(SeverityCritical, CategoryCriticalNilDereference, id, id.Pos(), id.Name,
			fmt.Sprintf("definite nil %s: %q is nil here", what, id.Name), hintNilDeref)
	case nilUnknown:
		if a.nilChecked[key] {
			a.addViolation(SeverityWarning, CategoryCriticalNilDereference, id, id.Pos(), id.Name,
				fmt.Sprintf("possible nil %s: %q is nil-checked in this function but not guarded on this path", what, id.Name), hintNilDeref)
		}
	}
}

func checkForUnauthorizedOrDeniedErr(err transport.Error) error {
	for _, diagnostic := range err.Errors {
		switch diagnostic.Code {
		case transport.UnauthorizedErrorCode:
			return ErrRegistryAuthz
		case transport.DeniedErrorCode:
			return ErrDenied
		}
	}
	return nil
}

func (a *analyzer) checkIndex(t *ast.IndexExpr, env *pathEnv) {
	if a.info == nil {
		return
	}
	if !isSliceOrArray(a.info.TypeOf(t.X)) {
		return
	}
	switch idx := t.Index.(type) {
	case *ast.Ident:
		if idx.Name == "_" {
			return
		}
		need := boundFact(a.vkey(idx), exprText(t.X))
		if !env.facts[need] {
			a.addViolation(SeverityWarning, CategorySliceBoundsRisk, t, t.Pos(), idx.Name,
				fmt.Sprintf("unguarded slice index: no check ensures %s < len(%s)", idx.Name, exprText(t.X)), hintBounds)
		}
	case *ast.BasicLit:

	default:
		a.addViolation(SeverityWarning, CategorySliceBoundsRisk, t, t.Pos(), "index",
			fmt.Sprintf("index expression cannot be statically bounded for %s", exprText(t.X)), hintBounds)
	}
}

