func (a *analyzer) nilnessOf(e ast.Expr, env *pathEnv) nilness {
	if e == nil {
		return nilUnknown
	}
	switch t := e.(type) {
	case *ast.Ident:
		if t.Name == "nil" {
			return nilIsNil
		}
		return env.nils[a.vkey(t)]
	case *ast.UnaryExpr:
		if t.Op == token.AND {
			return nilNotNil
		}
	case *ast.CallExpr:
		if id, ok := t.Fun.(*ast.Ident); ok && (id.Name == "new" || id.Name == "make") {
			return nilNotNil
		}
	case *ast.FuncLit:
		return nilNotNil
	case *ast.CompositeLit:
		return nilNotNil
	}
	return nilUnknown
}

