func preciseAgo(now time.Time, createdAt time.Time) string {
	ago := now.Sub(createdAt)

	if ago < 30*24*time.Hour {
		s := ago.Truncate(time.Second).String()
		return fmt.Sprintf("%s ago", s)
	}

	return createdAt.Format("Jan _2, 2006")
}

func predicatePhrase(name string) string {
	for _, prefix := range []string{"Is", "Has", "Can", "Should", "Needs", "Wants"} {
		if strings.HasPrefix(name, prefix) {
			rest := strings.TrimPrefix(name, prefix)
			words := camelToWords(rest)
			switch prefix {
			case "Is":
				return words
			case "Has":
				return "it has " + words
			case "Can":
				return "it can " + words
			default:
				return words
			}
		}
	}
	return camelToWords(name)
}

