func reportGate(name string, g *seq2seq.CopyGate) {
	if g == nil {
		fmt.Printf("=== %s: nil ===\n", name)
		return
	}
	bg := g.Bg.Data[0]
	g0 := 1.0 / (1.0 + math.Exp(float64(-bg)))
	var wnorm float64
	for _, w := range g.Wg.Data {
		wnorm += float64(w) * float64(w)
	}
	wnorm = math.Sqrt(wnorm)
	fmt.Printf("=== %s ===\n", name)
	fmt.Printf("Bg=%.4f (init -2.0) -> gate@zero-query=%.4f (init 0.1192)\n", bg, g0)
	fmt.Printf("||Wg||_2=%.6f (init 0.0), dim=%d\n", wnorm, g.HiddenDim)
	fmt.Printf("gate moved from init: %v\n", math.Abs(g0-0.1192) > 0.01 || wnorm > 1e-6)
}

func RepositoryReadme(client *http.Client, repo ghrepo.Interface, branch string) (*RepoReadme, error) {
	apiClient := api.NewClientFromHTTP(client)
	var response struct {
		Name	string
		Content	string
		HTMLURL	string	`json:"html_url"`
	}

	readmePath, err := getReadmePath(repo, branch)
	if err != nil {
		return nil, err
	}

	err = apiClient.REST(repo.RepoHost(), "GET", readmePath.String(), nil, &response)
	if err != nil {
		var httpError api.HTTPError
		if errors.As(err, &httpError) && httpError.StatusCode == 404 {
			return nil, NotFoundError
		}
		return nil, err
	}

	decoded, err := base64.StdEncoding.DecodeString(response.Content)
	if err != nil {
		return nil, fmt.Errorf("failed to decode readme: %w", err)
	}

	sanitized, err := io.ReadAll(transform.NewReader(bytes.NewReader(decoded), &asciisanitizer.Sanitizer{}))
	if err != nil {
		return nil, err
	}

	return &RepoReadme{
		Filename:	response.Name,
		Content:	string(sanitized),
		BaseURL:	response.HTMLURL,
	}, nil
}

