func starLine(r *rand.Rand, width int) string {
	var line strings.Builder
	starChance := 0.1
	for range width {
		chance := r.Float64()
		if chance <= starChance {
			charRoll := r.Float64()
			switch {
			case charRoll < 0.3:
				line.WriteString(".")
			case charRoll > 0.3 && charRoll < 0.6:
				line.WriteString("+")
			default:
				line.WriteString("*")
			}
		} else {
			line.WriteString(" ")
		}
	}

	return line.String()
}

