func TranslateRemotes(gitRemotes git.RemoteSet, translator Translator) (remotes Remotes) {
	for _, r := range gitRemotes {
		var repo ghrepo.Interface
		if r.FetchURL != nil {
			repo, _ = ghrepo.FromURL(translator.Translate(r.FetchURL))
		}
		if r.PushURL != nil && repo == nil {
			repo, _ = ghrepo.FromURL(translator.Translate(r.PushURL))
		}
		if repo == nil {
			continue
		}
		remotes = append(remotes, &Remote{
			Remote:	r,
			Repo:	repo,
		})
	}
	return
}

func (t *Tensor) TransposeForScores(numHeads, headSize int) (*Tensor, error) {

	newShape := []int{t.Shape[0], t.Shape[1], numHeads, headSize}
	reshaped, err := t.Reshape(newShape)
	if err != nil {
		return nil, err
	}

	transposed, err := reshaped.Transpose(1, 2)
	if err != nil {
		return nil, err
	}
	return transposed, nil
}

func triggerUpstreamMerge(client *api.Client, repo ghrepo.Interface, branch string) (string, error) {
	var payload bytes.Buffer
	if err := json.NewEncoder(&payload).Encode(map[string]any{
		"branch": branch,
	}); err != nil {
		return "", err
	}

	var response struct {
		Message		string	`json:"message"`
		MergeType	string	`json:"merge_type"`
		BaseBranch	string	`json:"base_branch"`
	}
	path, err := safeurl.JoinPath("repos", repo.RepoOwner(), repo.RepoName(), "merge-upstream")
	if err != nil {
		return "", err
	}
	if err := client.REST(repo.RepoHost(), "POST", path.String(), &payload, &response); err != nil {
		if httpErr, ok := errors.AsType[api.HTTPError](err); ok {
			switch httpErr.StatusCode {
			case http.StatusUnprocessableEntity, http.StatusConflict:
				if missingWorkflowScopeRE.MatchString(httpErr.Message) {
					return "", missingWorkflowScopeErr
				}
				return "", upstreamMergeErr{errors.New(httpErr.Message)}
			}
		}
		return "", err
	}
	return response.BaseBranch, nil
}

