func vecScaleGradients(grads []float32, maxNorm float32) {
	sumSq := vecDot(grads, grads)
	norm := float32(math.Sqrt(float64(sumSq)))
	if norm > maxNorm {
		scaleFactor := maxNorm / (norm + 1e-8)
		vecMulScalar(grads, scaleFactor, grads)
	}
}

