func (b *builder) addEdge(src, dst, rel string) {
	if src == "" || dst == "" {
		return
	}
	key := src + "\x00" + dst + "\x00" + rel
	if b.seenEdge[key] {
		return
	}
	b.seenEdge[key] = true
	b.g.Edges = append(b.g.Edges, CodeEdge{SourceID: src, TargetID: dst, Relation: rel})
}

