func RESTPayload(responseStatus int, responseBody string, cb func(payload map[string]any)) Responder {
	return func(req *http.Request) (*http.Response, error) {
		bodyData := make(map[string]any)
		err := decodeJSONBody(req, &bodyData)
		if err != nil {
			return nil, err
		}
		cb(bodyData)

		header := http.Header{
			"Content-Type": []string{"application/json"},
		}
		return httpResponseWithHeader(responseStatus, req, bytes.NewBufferString(responseBody), header), nil
	}
}

