// vocabFingerprint hashes the training vocabulary so resume can refuse a
// checkpoint trained on different data — a vocab index shift would silently
// corrupt the resumed weights.
func vocabFingerprint(v *vocab.Vocabulary) uint64 {
	h := fnv.New64a()
	fmt.Fprintf(h, "size=%d;", v.Size())
	for i := 0; i < v.Size(); i++ {
		fmt.Fprintf(h, "%d=%s;", i, v.GetWord(i))
	}
	return h.Sum64()
}

// Helper function to calculate strides
func calculateStrides(shape []int) []int {
	strides := make([]int, len(shape))
	stride := 1
	for i := len(shape) - 1; i >= 0; i-- {
		strides[i] = stride
		stride *= shape[i]
	}
	return strides
}

// Helper function to get N-dimensional coordinates from a flat index
func getCoords(flatIndex int, shape, strides []int) []int {
	coords := make([]int, len(shape))
	tempIdx := flatIndex
	for dim := range shape {
		coords[dim] = tempIdx / strides[dim]
		tempIdx %= strides[dim]
	}
	return coords
}

