// suggestNextTag increments the patch version of a semver tag.
func suggestNextTag(latest string) string {
	m := semverPattern.FindStringSubmatch(latest)
	if m == nil {
		return ""
	}

	prefix := ""
	if strings.HasPrefix(latest, "v") {
		prefix = "v"
	}

	major, minor := m[1], m[2]
	patch := 0
	fmt.Sscanf(m[3], "%d", &patch)

	return fmt.Sprintf("%s%s.%s.%d", prefix, major, minor, patch+1)
}

// incrementChildPrio increments the priority of the given child and reorders it if necessary.
func (n *node) incrementChildPrio(pos int) int {
	cs := n.children
	cs[pos].priority++
	prio := cs[pos].priority

	newPos := pos
	for ; newPos > 0 && cs[newPos-1].priority < prio; newPos-- {

		cs[newPos-1], cs[newPos] = cs[newPos], cs[newPos-1]
	}

	if newPos != pos {
		n.indices = n.indices[:newPos] +
			n.indices[pos:pos+1] +
			n.indices[newPos:pos] + n.indices[pos+1:]
	}

	return newPos
}

