// RecordTelemetry instruments a command with an invocation-owned telemetry event.
func RecordTelemetry(cmd *cobra.Command, telemetry ghtelemetry.EventRecorder) {
	if isTelemetryDisabled(cmd) {
		return
	}

	if cmd.RunE == nil {
		return
	}

	var event ghtelemetry.PendingEvent
	currentArgs := cmd.Args
	cmd.Args = func(cmd *cobra.Command, args []string) error {
		event = telemetry.Begin(ghtelemetry.Event{
			Type:	"command_invocation",
			Dimensions: ghtelemetry.Dimensions{
				"command":	cmd.CommandPath(),
				"flags":	telemetryFlags(cmd),
			},
		})
		if currentArgs != nil {
			return currentArgs(cmd, args)
		}
		return nil
	}

	currentRunE := cmd.RunE
	cmd.RunE = func(cmd *cobra.Command, args []string) error {
		runErr := currentRunE(cmd, args)

		event.UpsertDimensions(ghtelemetry.Dimensions{"flags": telemetryFlags(cmd)})
		return runErr
	}
}

// RecordTelemetryForSubcommands instruments all descendants of a command.
func RecordTelemetryForSubcommands(cmd *cobra.Command, telemetry ghtelemetry.EventRecorder) {
	for _, c := range cmd.Commands() {
		RecordTelemetry(c, telemetry)
		RecordTelemetryForSubcommands(c, telemetry)
	}
}

// Internal helper to lazily create a buffer if necessary.
// Calls to this function get inlined.
func bufApp(buf *[]byte, s string, w int, c byte) {
	b := *buf
	if len(b) == 0 {

		if s[w] == c {
			return
		}

		length := len(s)
		if length > cap(b) {
			*buf = make([]byte, length)
		} else {
			*buf = (*buf)[:length]
		}
		b = *buf

		copy(b, s[:w])
	}
	b[w] = c
}

// TrainBPETokenizer is a convenience function that creates, trains, and saves
// a BPE tokenizer. Returns the path to the saved model.
func TrainBPETokenizer(projectRoot string, vocabSize int) (string, error) {
	bpe := NewBPETokenizer(vocabSize)

	bpe.AddSpecialToken("<|im_start|>")
	bpe.AddSpecialToken("<|im_end|>")
	bpe.AddSpecialToken("<pad>")
	bpe.AddSpecialToken("<s>")
	bpe.AddSpecialToken("</s>")
	bpe.AddSpecialToken("UNK")
	bpe.AddSpecialToken("\n")

	if err := bpe.Train(projectRoot); err != nil {
		return "", fmt.Errorf("BPE training failed: %w", err)
	}

	path := filepath.Join(projectRoot, "data/models/gob_models/bpe_tokenizer.gob")
	if err := bpe.Save(path); err != nil {
		return "", fmt.Errorf("BPE save failed: %w", err)
	}

	vocabPath := filepath.Join(projectRoot, "data/models/gob_models/bpe_vocabulary.gob")
	if err := bpe.Vocab.Save(vocabPath); err != nil {
		log.Printf("⚠️  BPE vocab save warning: %v", err)
	}

	log.Printf("✅ BPE Tokenizer saved to %s (vocab=%d, merges=%d)", path, bpe.Vocab.Size(), len(bpe.Merges))
	return path, nil
}

