}

// isVisualWord keeps "show me a visual" out of the symbol path.
func isVisualWord(s string) bool {
	switch strings.ToLower(s) {
	case "visual", "graph", "diagram", "picture", "map":
		return true
	}
	return false
}

// capExamples keeps the first n examples and counts the rest.
func capExamples(in []string, n int) ([]string, int) {
	if len(in) <= n {
		return in, 0
	}
	return in[:n], len(in) - n
}

// snippetHead keeps the first n lines of a code snippet.
func snippetHead(snippet string, n int) string {
	snippet = strings.TrimRight(snippet, "\n")
	lines := strings.Split(snippet, "\n")
	if len(lines) > n {
		lines = lines[:n]
	}
	return strings.Join(lines, "\n")
}

