// listArtifacts lists the artifacts of one type, or of every type when
// artifactType is empty. gh treats generic and plan artifacts alike as
// Markdown documents, so either type lists both: each type is listed up to
// the limit, then the two are merged in number order and cut to the limit.
// Any other type is listed alone.
func listArtifacts(c client.ArtifactClient, repo ghrepo.Interface, issueNumber int, artifactType string, limit int) ([]client.Artifact, error) {
	if artifactType != client.TypeGeneric && artifactType != client.TypePlan {
		return c.List(repo, issueNumber, artifactType, limit)
	}

	var artifacts []client.Artifact
	for _, documentType := range []string{client.TypeGeneric, client.TypePlan} {
		documents, err := c.List(repo, issueNumber, documentType, limit)
		if err != nil {
			return nil, err
		}
		artifacts = append(artifacts, documents...)
	}

	slices.SortStableFunc(artifacts, func(a, b client.Artifact) int {
		return cmp.Compare(a.Number, b.Number)
	})
	if limit > 0 && len(artifacts) > limit {
		artifacts = artifacts[:limit]
	}
	return artifacts, nil
}

// snippetCalls lists the callees by the names they are called with in the
// snippet. A callee is listed only if its bare name appears in the
// function's source, so every named call is visible in the [code] block.
func snippetCalls(p *analyze.Project, fn *analyze.Func) string {
	var names []string
	seen := map[string]bool{}
	for _, id := range fn.Calls {
		callee := p.FuncByID(id)
		if callee == nil || callee.Name == "" || seen[callee.Name] {
			continue
		}
		seen[callee.Name] = true
		if !strings.Contains(fn.Src, callee.Name) {
			continue
		}
		names = append(names, callee.Name)
		if len(names) >= 8 {
			break
		}
	}
	if len(names) == 0 {
		return "Calls in this code: none.\n"
	}
	return "Calls in this code: " + strings.Join(names, ", ") + ".\n"
}

// flowMutations lists the functions reachable from flow that directly
// mutate the filesystem, with the external calls they mutate through.
// Capped so the plan stays readable.
func (p *Project) flowMutations(flow *Func) []mutation {
	seen := map[string]bool{}
	var out []mutation
	var visit func(fn *Func)
	visit = func(fn *Func) {
		if fn == nil || seen[fn.ID] {
			return
		}
		seen[fn.ID] = true
		if fn.Mutates {
			var via []string
			for _, e := range fn.ExtCalls {
				if hasEffect(callEffects[e], fxWrite) {
					via = append(via, e)
				}
			}
			sort.Strings(via)
			out = append(out, mutation{FuncName: fn.Name, Via: via, File: fn.File, Line: fn.Line})
		}
		for _, id := range fn.Calls {
			visit(p.byID[id])
		}
	}
	for _, id := range flow.Calls {
		visit(p.byID[id])
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].FuncName != out[j].FuncName {
			return out[i].FuncName < out[j].FuncName
		}
		return out[i].File < out[j].File
	})
	if len(out) > 4 {
		out = out[:4]
	}
	return out
}

