// readFrom loads the lock file from an open file handle.
// Returns an empty file if the content is empty, corrupt, or incompatible.
func readFrom(f *os.File) (*file, error) {
	if _, err := f.Seek(0, 0); err != nil {
		return nil, fmt.Errorf("could not seek lock file: %w", err)
	}
	data, err := io.ReadAll(f)
	if err != nil {
		return nil, fmt.Errorf("could not read lock file: %w", err)
	}
	if len(data) == 0 {
		return newFile(), nil
	}

	var lf file
	if err := json.Unmarshal(data, &lf); err != nil {
		return newFile(), nil
	}

	if lf.Version != lockVersion || lf.Skills == nil {
		return newFile(), nil
	}

	return &lf, nil
}

// refineTypes loads the project with type info and adds the call edges
// the heuristics missed or got wrong. It runs inside BuildGraph before
// effect propagation, so refined edges carry effects.
func (p *Project) refineTypes() {
	if p.Module == "" {
		return
	}
	cfg := &packages.Config{
		Mode:	packages.NeedName | packages.NeedTypes | packages.NeedSyntax | packages.NeedTypesInfo,
		Dir:	p.Root,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		return
	}
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			return
		}
	}
	p.Typed = true
	for _, pkg := range pkgs {
		p.refinePackage(pkg)
	}
}

// Load loads the Seq2Seq model from a file.
func Load(filePath string, tok *tokenizer.Tokenizer) (*Seq2Seq, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to open file for loading model: %w", err)
	}
	defer file.Close()

	decoder := gob.NewDecoder(file)

	var serializableModel SerializableSeq2Seq
	if err := decoder.Decode(&serializableModel); err != nil {
		return nil, fmt.Errorf("failed to decode model: %w", err)
	}

	model := &Seq2Seq{
		Encoder:	serializableModel.Encoder,
		Decoder:	serializableModel.Decoder,
		Tokenizer:	tok,
		OutputVocab:	serializableModel.OutputVocab,
		HiddenDim:	serializableModel.HiddenDim,
		ExactMap:	serializableModel.ExactMap,
	}

	log.Printf("Seq2Seq model loaded from %s", filePath)
	return model, nil
}

