// findFuncDecl locates the declaration matching fn by name and receiver.
func findFuncDecl(file *ast.File, fn *Func) *ast.FuncDecl {
	var found *ast.FuncDecl
	ast.Inspect(file, func(n ast.Node) bool {
		d, ok := n.(*ast.FuncDecl)
		if !ok || d.Name.Name != fn.Name {
			return true
		}
		hasRecv := d.Recv != nil && len(d.Recv.List) > 0
		if (fn.Receiver != "") != hasRecv {
			return true
		}
		found = d
		return false
	})
	return found
}

// findStringVar locates the first `var <name> string` (no
// initializer) in the function body.
func findStringVar(body *ast.BlockStmt) (*ast.ValueSpec, *ast.Ident) {
	var found *ast.ValueSpec
	var name *ast.Ident
	ast.Inspect(body, func(n ast.Node) bool {
		if found != nil {
			return false
		}
		vs, ok := n.(*ast.ValueSpec)
		if !ok || len(vs.Names) != 1 || len(vs.Values) != 0 {
			return true
		}
		if id, ok := vs.Type.(*ast.Ident); !ok || id.Name != "string" {
			return true
		}
		found, name = vs, vs.Names[0]
		return false
	})
	return found, name
}

