// inlineRanges locates the source of an inline link or image. goldmark reports
// where every inline node starts, so the only thing left to find is where it
// ends, inside a node goldmark has already accepted.
//
// A reference-style link carries no destination beside it and reports false,
// leaving it to the definitions. hi bounds the search to the block.
func inlineRanges(src []byte, n ast.Node, hi int) (refRanges, bool) {
	start := n.Pos()
	if start < 0 || start >= hi {
		return refRanges{}, false
	}
	open := start
	if src[open] == '!' {
		open++
	}
	if open >= hi || src[open] != '[' {
		return refRanges{}, false
	}
	close, ok := closingBracket(src, open, hi, literalText(n))
	if !ok || close+1 >= hi || src[close+1] != '(' {
		return refRanges{}, false
	}
	dest := inlineDestination(src, close+2, hi)
	stop := skipSpace(src, dest.stop, hi)
	if stop < hi && src[stop] != ')' {
		if end, ok := scanTitle(src, stop, hi); ok {
			stop = skipSpace(src, end, hi)
		}
	}
	if stop >= hi || src[stop] != ')' {
		return refRanges{}, false
	}
	return refRanges{
		node:	byteRange{start, stop + 1},
		label:	byteRange{open + 1, close},
		dest:	dest,
	}, true
}

// findTargetObject locates the symbol's object among a package's
// definitions. Bare symbols must be package-level; methods are matched
// by receiver type name because a method's *types.Func is not parented
// to the package scope.
func findTargetObject(p *packages.Package, recv, name string, isMethod bool) *impactTarget {
	scope := p.Types.Scope()
	for _, obj := range p.TypesInfo.Defs {
		if obj == nil || obj.Name() != name {
			continue
		}
		if isMethod {
			fn, ok := obj.(*types.Func)
			if !ok || methodReceiverName(fn) != recv {
				continue
			}
			return &impactTarget{obj: fn, name: name, kind: fmt.Sprintf("%T", fn), recv: recv, isMethod: true}
		}
		if obj.Parent() != scope {
			continue
		}
		return &impactTarget{obj: obj, name: name, kind: fmt.Sprintf("%T", obj)}
	}
	return nil
}

