// tokens lowercases and splits on word characters; mirrors the probe's
// strings.ToLower treatment of the input.
func tokens(s string) []string	{ return wordRe.FindAllString(strings.ToLower(s), -1) }

// wordTokens lowercases text and splits it into alphanumeric tokens,
// keeping digits (identifiers like "utf8" stay whole). Tokens of length
// 1 are dropped as noise.
func wordTokens(text string) []string {
	var toks []string
	var sb strings.Builder
	flush := func() {
		if sb.Len() > 1 {
			toks = append(toks, sb.String())
		}
		sb.Reset()
	}
	for _, r := range strings.ToLower(text) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(r)
		} else {
			flush()
		}
	}
	flush()
	return toks
}

// normalizeRecallInput lowercases, collapses whitespace, and strips
// trailing punctuation so "Have you ever played soccer?" matches the
// trained "have you ever played soccer".
func normalizeRecallInput(s string) string {
