// MapReposToIDs retrieves a set of IDs for the given set of repositories.
// This is similar logic to RepoNetwork, but only fetches databaseId and does not
// discover parent repositories.
func GetRepoIDs(client *Client, host string, repositories []ghrepo.Interface) ([]int64, error) {
	queries := make([]string, 0, len(repositories))
	for i, repo := range repositories {
		queries = append(queries, fmt.Sprintf(`
			repo_%03d: repository(owner: %q, name: %q) {
				databaseId
			}
		`, i, repo.RepoOwner(), repo.RepoName()))
	}

	query := fmt.Sprintf(`query MapRepositoryNames { %s }`, strings.Join(queries, ""))

	graphqlResult := make(map[string]*struct {
		DatabaseID int64 `json:"databaseId"`
	})

	if err := client.GraphQL(host, query, nil, &graphqlResult); err != nil {
		return nil, fmt.Errorf("failed to look up repositories: %w", err)
	}

	repoKeys := make([]string, 0, len(repositories))
	for k := range graphqlResult {
		repoKeys = append(repoKeys, k)
	}
	sort.Strings(repoKeys)

	result := make([]int64, len(repositories))
	for i, k := range repoKeys {
		result[i] = graphqlResult[k].DatabaseID
	}
	return result, nil
}

// resolveCall maps a call expression to a project function, or nil when
// it targets an external package or can't be resolved. Shared by the
// call-graph pass and the effect/guard collection so both see the same
// edges.
func (p *Project) resolveCall(pkg *Package, varPkg map[string]string, paramPkgs map[string]*Package, fn *Func, call *ast.CallExpr) *Func {
	var target *Func
	switch fun := call.Fun.(type) {
	case *ast.Ident:

		target = p.findFunc(pkg, "", fun.Name)
	case *ast.SelectorExpr:

		if id, ok := fun.X.(*ast.Ident); ok {
			target = p.findMethod(pkg, fun.Sel.Name)
			if target == nil {
				if alias, ok := varPkg[id.Name]; ok {
					if q, ok := pkg.aliasCache[alias]; ok {
						target = p.findMethod(q, fun.Sel.Name)
					}
				} else if q, ok := paramPkgs[id.Name]; ok {
					target = p.findMethod(q, fun.Sel.Name)
				} else if q, ok := pkg.aliasCache[id.Name]; ok {
					target = p.findFunc(q, "", fun.Sel.Name)
				}
			}
		}
	}
	if target == fn {
		return nil
	}
	return target
}

// extCallKey maps a call like os.Remove(x) to "os.Remove" when the
// qualifier is an imported external package. Returns "" for project
// packages, unqualified calls, and unknown qualifiers. Dot-imports and
// explicit aliases ("o \"os\"") are not resolved — accepted heuristic gap.
func extCallKey(pkg *Package, call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return ""
	}
	if _, isProj := pkg.aliasCache[id.Name]; isProj {
		return ""
	}
	for _, imp := range pkg.Imports {
		if importBase(imp) == id.Name {
			return id.Name + "." + sel.Sel.Name
		}
	}
	return ""
}

// resolveField maps a field name to "pkg.Type.Field" keys across every
// struct type in the project. A "--flag" prefix is stripped so "what
// reads --verbose" works too.
func (p *Project) resolveField(name string) []string {
	name = strings.Trim(name, "`\"' ")
	name = strings.TrimPrefix(name, "--")
	var keys []string
	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t.Kind != "struct" {
				continue
			}
			for _, f := range t.Fields {
				if strings.EqualFold(f, name) {
					keys = append(keys, pkg.Name+"."+t.Name+"."+f)
				}
			}
		}
	}
	sort.Strings(keys)
	return keys
}

// supportedContentType maps a file extension to the content type the endpoint
// expects. The extension is all gh checks, since the endpoint accepts
// mislabeled bytes anyway.
func supportedContentType(path string) (string, error) {
	ext := strings.ToLower(filepath.Ext(path))
	for _, t := range contentTypes {
		if t.ext == ext {
			return t.contentType, nil
		}
	}

	supported := make([]string, len(contentTypes))
	for i, t := range contentTypes {
		supported[i] = strings.TrimPrefix(t.ext, ".")
	}
	return "", fmt.Errorf("%s is not a supported file type (supported: %s)", path, strings.Join(supported, ", "))
}

