	id, ok := lhs[idx].(*ast.Ident)
	if !ok {
		return
	}
	if t := a.identType(id); isErrorType(t) {
		return
	}
	acquired[a.vkey(id)] = acq{name: id.Name, pos: pos, call: call}
}

