// twirpErrorFromIntermediary maps HTTP errors from non-twirp sources to twirp errors.
// The mapping is similar to gRPC: https://github.com/grpc/grpc/blob/master/doc/http-grpc-status-mapping.md.
// Returned twirp Errors have some additional metadata for inspection.
func twirpErrorFromIntermediary(status int, msg string, bodyOrLocation string) twirp.Error {
	var code twirp.ErrorCode
	if isHTTPRedirect(status) {
		code = twirp.Internal
	} else {
		switch status {
		case 400:
			code = twirp.Internal
		case 401:
			code = twirp.Unauthenticated
		case 403:
			code = twirp.PermissionDenied
		case 404:
			code = twirp.BadRoute
		case 429:
			code = twirp.ResourceExhausted
		case 502, 503, 504:
			code = twirp.Unavailable
		default:
			code = twirp.Unknown
		}
	}

	twerr := twirp.NewError(code, msg)
	twerr = twerr.WithMeta("http_error_from_intermediary", "true")
	twerr = twerr.WithMeta("status_code", strconv.Itoa(status))
	if isHTTPRedirect(status) {
		twerr = twerr.WithMeta("location", bodyOrLocation)
	} else {
		twerr = twerr.WithMeta("body", bodyOrLocation)
	}
	return twerr
}

// importAliases maps import path to the local package name written in
// source, honoring explicit aliases. Blank ("_") and dot (".") imports
// have no usable qualifier and are skipped.
func importAliases(files []*ast.File) map[string]string {
	aliases := make(map[string]string)
	for _, f := range files {
		if f == nil {
			continue
		}
		for _, imp := range f.Imports {
			if imp == nil || imp.Path == nil {
				continue
			}
			path, err := strconv.Unquote(imp.Path.Value)
			if err != nil || path == "" {
				continue
			}
			var name string
			if imp.Name != nil {
				name = imp.Name.Name
			}
			if name == "" {
				name = path
				if i := strings.LastIndex(path, "/"); i >= 0 {
					name = path[i+1:]
				}
			}
			if name == "_" || name == "." {
				continue
			}
			aliases[path] = name
		}
	}
	return aliases
}

// constructorVars maps local variable names to import aliases for the
// common constructor pattern: s := store.New(). This lets s.Save()
// resolve to the Save method in the store package without type info.
func constructorVars(body *ast.BlockStmt, pkg *Package) map[string]string {
	out := map[string]string{}
	ast.Inspect(body, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lhs, ok := assign.Lhs[0].(*ast.Ident)
		if !ok {
			return true
		}
		call, ok := assign.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		if id, ok := sel.X.(*ast.Ident); ok {
			if _, isAlias := pkg.aliasCache[id.Name]; isAlias {
				out[lhs.Name] = id.Name
			}
		}
		return true
	})
	return out
}

// paramPackages maps parameter names to project packages via their
// declared types: RunCLI(fm filemanager.FileManager, ...) lets
// fm.DeleteFile() resolve into the filemanager package. Unwraps pointer
// types; only parameters typed as pkg.Type qualify.
func paramPackages(fn *Func, pkg *Package) map[string]*Package {
	out := map[string]*Package{}
	if fn.decl == nil || fn.decl.Type == nil || fn.decl.Type.Params == nil {
		return out
	}
	for _, field := range fn.decl.Type.Params.List {
		typ := field.Type
		if star, ok := typ.(*ast.StarExpr); ok {
			typ = star.X
		}
		sel, ok := typ.(*ast.SelectorExpr)
		if !ok {
			continue
		}
		id, ok := sel.X.(*ast.Ident)
		if !ok {
			continue
		}
		if q, ok := pkg.aliasCache[id.Name]; ok {
			for _, name := range field.Names {
				out[name.Name] = q
			}
		}
	}
	return out
}

