// varSliceDecl matches `var <name> []T` (no initializer) and returns
// the name and element type.
func varSliceDecl(stmt ast.Stmt) (string, ast.Expr) {
	ds, ok := stmt.(*ast.DeclStmt)
	if !ok {
		return "", nil
	}
	gd, ok := ds.Decl.(*ast.GenDecl)
	if !ok || gd.Tok != token.VAR || len(gd.Specs) != 1 {
		return "", nil
	}
	vs, ok := gd.Specs[0].(*ast.ValueSpec)
	if !ok || len(vs.Names) != 1 || len(vs.Values) != 0 {
		return "", nil
	}
	at, ok := vs.Type.(*ast.ArrayType)
	if !ok || at.Len != nil {
		return "", nil
	}
	return vs.Names[0].Name, at.Elt
}

// Translate matches one error line against the pattern table and
// returns the plain-words help. It reports false when nothing matches,
// so the caller can fall back to the language model.
func Translate(line string) (Help, bool) {
	trimmed := strings.TrimSpace(line)
	for _, p := range patterns {
		if m := p.re.FindStringSubmatch(trimmed); m != nil {
			var meaning, fix string
			if p.custom != nil {
				meaning, fix = p.custom(m)
			} else {
				expand := func(tmpl string) string {
					out := tmpl
					for i, g := range m[1:] {
						out = strings.ReplaceAll(out, "$"+strconv.Itoa(i+1), g)
					}
					return out
				}
				meaning, fix = expand(p.meaning), expand(p.fix)
			}
			return Help{
				Title:		p.title,
				Meaning:	meaning,
				Fix:		fix,
				Matched:	trimmed,
			}, true
		}
	}
	return Help{}, false
}

// ResolveLabels matches user-provided label names (case-insensitive) against a
// set of known labels and returns the corresponding IDs. If any names cannot be
// matched, all unrecognized names are reported in the returned error.
func ResolveLabels(allLabels []client.DiscussionLabel, names []string) ([]string, error) {
	byName := make(map[string]string, len(allLabels))
	for _, l := range allLabels {
		byName[strings.ToLower(l.Name)] = l.ID
	}

	var ids []string
	var missing []string

	for _, name := range names {
		trimmed := strings.TrimSpace(name)
		id, ok := byName[strings.ToLower(trimmed)]
		if !ok {
			missing = append(missing, trimmed)
		} else {
			ids = append(ids, id)
		}
	}

	if len(missing) > 0 {
		return nil, fmt.Errorf("labels not found: %s", strings.Join(missing, ", "))
	}

	return ids, nil
}

