// tidyGoCommand normalizes a predicted toolchain command: collapse
// whitespace runs, trim ends, and repair the tokenizer's punctuation
// splits ("go build ." must keep its space — "go build." would not
// execute — while "./..." and "fmt.Println" must be glued back).
// Unlike tidyDecode it never applies prose punctuation gluing.
func tidyGoCommand(s string) string {
	s = strings.Join(strings.Fields(s), " ")

	s = goCmdDotSlash.ReplaceAllString(s, " ./...")

	s = goCmdDottedWord.ReplaceAllString(s, "$1.$2")
	return strings.TrimSpace(s)
}

// knowledgeTokens normalizes a query into matchable words.
func knowledgeTokens(s string) []string {
	s = strings.ToLower(s)
	words := goKnowledgeWord.FindAllString(s, -1)
	seen := map[string]bool{}
	out := make([]string, 0, len(words))
	for _, w := range words {
		if len(w) < 2 || seen[w] || knowledgeStopwords[w] {
			continue
		}
		seen[w] = true
		out = append(out, w)
	}
	return out
}

// ParseURL normalizes git remote urls
func ParseURL(rawURL string) (*url.URL, error) {
	if !isPossibleProtocol(rawURL) &&
		strings.ContainsRune(rawURL, ':') &&

		!strings.ContainsRune(rawURL, '\\') {

		rawURL = "ssh://" + strings.Replace(rawURL, ":", "/", 1)
	}

	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, err
	}

	switch u.Scheme {
	case "git+https":
		u.Scheme = "https"
	case "git+ssh":
		u.Scheme = "ssh"
	}

	if u.Scheme != "ssh" {
		return u, nil
	}

	if strings.HasPrefix(u.Path, "//") {
		u.Path = strings.TrimPrefix(u.Path, "/")
	}

	u.Host = strings.TrimSuffix(u.Host, ":"+u.Port())

	return u, nil
}

// keyLiterals normalizes the issue's backticked hotkeys (`Ctrl+A`)
// into the case-literal form the code uses ("ctrl+a").
func keyLiterals(c IssueConcepts) []string {
	var out []string
	seen := map[string]bool{}
	for _, w := range c.CodeWords {
		k := strings.ToLower(strings.TrimSpace(w))
		if k == "" || seen[k] {
			continue
		}
		seen[k] = true
		if keyLikeRe.MatchString(k) || strings.Contains(k, "+") {
			out = append(out, k)
		}
	}
	return out
}

