// openDir opens the directory the file at path goes in, through safepaths,
// creating it and any missing parents: Dir, or with Output, the file's parent
// directory. Every file goes in the same directory, so it's opened once and
// closed by Close. An error opening it is returned as it is: it isn't about
// the file, even when it says a name exists, as it does when the directory is
// a dangling symlink.
func (w *fileWriter) openDir(path string) (*safepaths.Root, error) {
	if !w.opened {
		w.opened = true
		dir := w.dir
		if w.output != "" {
			dir = filepath.Dir(path)
		}
		w.root, w.rootErr = safepaths.OpenRootDir(dir, 0o755)
	}
	return w.root, w.rootErr
}

// rankSiblings orders the type's methods by overlap with the issue's
// vocabulary: the closest relatives of the requested method first.
func rankSiblings(methods []*Func, c IssueConcepts) []*Func {
	kw := map[string]bool{}
	for _, s := range wordTokens(c.Title) {
		kw[s] = true
	}
	for _, s := range wordTokens(c.Body) {
		kw[s] = true
	}
	type scored struct {
		fn	*Func
		score	int
	}
	var ss []scored
	for _, fn := range methods {
		score := 0
		for _, t := range tokenizeName(fn.Name) {
			if wordHit(t, kw) {
				score += 2
			}
		}
		ss = append(ss, scored{fn, score})
	}
	sort.Slice(ss, func(i, j int) bool {
		if ss[i].score != ss[j].score {
			return ss[i].score > ss[j].score
		}
		return ss[i].fn.Name < ss[j].fn.Name
	})
	var out []*Func
	for i, s := range ss {
		if i >= 4 {
			break
		}
		out = append(out, s.fn)
	}
	return out
}

