// makeBatches pads each bucket to its own max lengths.
func makeBatches(enc []encodedPair, size, padID int) []batch {
	var out []batch
	for i := 0; i < len(enc); i += size {
		end := i + size
		if end > len(enc) {
			end = len(enc)
		}
		grp := enc[i:end]
		maxIn, maxTg := 0, 0
		for _, p := range grp {
			if len(p.input) > maxIn {
				maxIn = len(p.input)
			}
			if len(p.target) > maxTg {
				maxTg = len(p.target)
			}
		}
		b := batch{}
		for _, p := range grp {
			in := make([]int, maxIn)
			copy(in, p.input)
			for k := len(p.input); k < maxIn; k++ {
				in[k] = padID
			}
			tg := make([]int, maxTg)
			copy(tg, p.target)
			for k := len(p.target); k < maxTg; k++ {
				tg[k] = padID
			}
			b.inputs = append(b.inputs, in)
			b.targets = append(b.targets, tg)
		}
		out = append(out, b)
	}
	return out
}

// padRight pads s to w columns, counting runes (box-drawing chars are
// multibyte). Overlong strings are truncated cleanly.
func padRight(s string, w int) string {
	s = truncateRunes(s, w)
	return s + strings.Repeat(" ", w-utf8.RuneCountInString(s))
}

