	_, _ = cfg.Check("beginner", fset, []*ast.File{f}, nil)
	return first
}

// parseArgs parses arguments into two distinct slices of flags and command. Parsing stops
// as soon as a non-flag argument is found assuming the remaining arguments are the command.
// It returns an error if a unary flag is provided without an argument.
func parseArgs(args []string, unaryFlags string) (cmdArgs, command []string, err error) {
	for i := 0; i < len(args); i++ {
		arg := args[i]

		if !strings.HasPrefix(arg, "-") {
			command = args[i:]
			break
		}

		cmdArgs = append(cmdArgs, arg)
		if len(arg) == 2 && strings.Contains(unaryFlags, arg[1:2]) {
			if i++; i == len(args) {
				return nil, nil, fmt.Errorf("flag: %s requires an argument", arg)
			}

			cmdArgs = append(cmdArgs, args[i])
		}
	}

	return cmdArgs, command, nil
}

// loadChunks parses every .go file under dir into semantic chunks for
// prompt context. Unparseable files are skipped. At most max chunks are
// returned.
func loadChunks(dir string, max int) []ast.CodeChunk {
	var chunks []ast.CodeChunk
	_ = filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			if d.Name() == ".git" || d.Name() == "vendor" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".go") {
			return nil
		}
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return nil
		}
		rel, _ := filepath.Rel(dir, path)
		cs, err := ast.ChunkFile(fset, f, rel)
		if err != nil {
			return nil
		}
		chunks = append(chunks, cs...)
		return nil
	})
	if len(chunks) > max {
		chunks = chunks[:max]
	}
	return chunks
}

// tryMutation parses every non-test Go file, applies m, and returns
// the rewritten file set. Files the mutation did not touch keep their
// original source. A false second return means nothing changed.
func tryMutation(files map[string]string, m mutation) (map[string]string, bool) {
	out := cloneFiles(files)
	changed := false
	for path, src := range out {
		if !isTunableFile(path) {
			continue
		}
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, path, src, parser.ParseComments)
		if err != nil {
			return nil, false
		}
		if !m.apply(f) {
			continue
		}
		var buf bytes.Buffer
		if err := format.Node(&buf, fset, f); err != nil {
			return nil, false
		}
		out[path] = buf.String()
		changed = true
	}
	return out, changed
}

// parseReviewers parses given Reviews and ReviewRequests
func parseReviewers(pr api.PullRequest) []*reviewerState {
	reviewerStates := make(map[string]*reviewerState)

	for _, review := range pr.Reviews.Nodes {
		if review.Author.Login != pr.Author.Login {
			name := review.AuthorLogin()
			if name == "" {
				name = ghostName
			}
			reviewerStates[name] = &reviewerState{
				Name:	name,
				State:	review.State,
			}
		}
	}

	for _, reviewRequest := range pr.ReviewRequests.Nodes {
		name := reviewRequest.RequestedReviewer.DisplayName()
		reviewerStates[name] = &reviewerState{
			Name:	name,
			State:	requestedReviewState,
		}
	}

	result := make([]*reviewerState, 0, len(reviewerStates))
	for _, reviewer := range reviewerStates {
		if reviewer.State == pendingReviewState {
			continue
		}
		result = append(result, reviewer)
	}

	return result
}

// parseBenchmarkLine parses one benchmark result line, e.g.
// "BenchmarkAdd-8  1000000  123.4 ns/op  48 B/op  2 allocs/op".
// The -N GOMAXPROCS suffix is stripped; MB/s columns are tolerated.
// Returns nil for non-result lines.
func parseBenchmarkLine(output string) *BenchmarkMetrics {
	line := strings.TrimSpace(output)
	parts := benchResultRe.FindStringSubmatch(line)
	if parts == nil {
		return nil
	}
	n, _ := strconv.Atoi(parts[2])
	nsPerOp, _ := strconv.ParseFloat(parts[3], 64)
	m := &BenchmarkMetrics{Name: parts[1], N: n, NsPerOp: nsPerOp}
	if b := benchBytesRe.FindStringSubmatch(line); b != nil {
		m.AllocBytesPerOp, _ = strconv.ParseInt(b[1], 10, 64)
	}
	if a := benchAllocsRe.FindStringSubmatch(line); a != nil {
		m.AllocsPerOp, _ = strconv.ParseInt(a[1], 10, 64)
	}
	return m
}

// parseFuncDecl parses one chunk's formatted source back into a
// *ast.FuncDecl. Chunk content is a declaration fragment, so it is
// wrapped in a package clause first.
func parseFuncDecl(content string) *ast.FuncDecl {
	if strings.TrimSpace(content) == "" {
		return nil
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "chunk.go", "package chunk\n"+content, parser.SkipObjectResolution)
	if err != nil || f == nil {
		return nil
	}
	for _, d := range f.Decls {
		if fn, ok := d.(*ast.FuncDecl); ok && fn != nil {
			return fn
		}
	}
	return nil
}

// ParseFlags parses persistent flag tree and local flags.
func (c *Command) ParseFlags(args []string) error {
	if c.DisableFlagParsing {
		return nil
	}

	if c.flagErrorBuf == nil {
		c.flagErrorBuf = new(bytes.Buffer)
	}
	beforeErrorBufLen := c.flagErrorBuf.Len()
	c.mergePersistentFlags()

	c.Flags().ParseErrorsAllowlist = flag.ParseErrorsAllowlist(c.FParseErrWhitelist)

	err := c.Flags().Parse(args)

	if c.flagErrorBuf.Len()-beforeErrorBufLen > 0 && err == nil {
		c.Print(c.flagErrorBuf.String())
	}

	return err
}

// synthesizeTrace parses req.ContextCode and traces the execution
