// ReadBranchConfig parses the `branch.BRANCH.(remote|merge|pushremote|gh-merge-base)` part of git config.
// If no branch config is found or there is an error in the command, it returns an empty BranchConfig.
// Downstream consumers of ReadBranchConfig should consider the behavior they desire if this errors,
// as an empty config is not necessarily breaking.
func (c *Client) ReadBranchConfig(ctx context.Context, branch string) (BranchConfig, error) {
	prefix := regexp.QuoteMeta(fmt.Sprintf("branch.%s.", branch))
	args := []string{"config", "--get-regexp", fmt.Sprintf("^%s(remote|merge|pushremote|%s)$", prefix, MergeBaseConfig)}
	cmd, err := c.Command(ctx, args...)
	if err != nil {
		return BranchConfig{}, err
	}

	branchCfgOut, err := cmd.Output()
	if err != nil {
		// This is the error we expect if the git command does not run successfully.
		// If the ExitCode is 1, then we just didn't find any config for the branch.
		var gitError *GitError
		if ok := errors.As(err, &gitError); ok && gitError.ExitCode != 1 {
			return BranchConfig{}, err
		}
		return BranchConfig{}, nil
	}

	return parseBranchConfig(outputLines(branchCfgOut)), nil
}

// findDispatchSites parses the anchor's file and looks for extension
// points in its body: switch statements and if/else chains that compare
// against literals — the shapes where new cases get added.
func findDispatchSites(root string, fn *Func) []dispatchSite {
	src, err := os.ReadFile(filepath.Join(root, fn.File))
	if err != nil {
		return nil
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, fn.File, src, 0)
	if err != nil {
		return nil
	}
	decl := findFuncDecl(file, fn)
	if decl == nil || decl.Body == nil {
		return nil
	}
	var sites []dispatchSite
	ast.Inspect(decl.Body, func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.SwitchStmt:
			if ex, more := switchExamples(fset, src, s); len(ex) >= 2 {
				sites = append(sites, dispatchSite{
					kind:		"switch",
					line:		fset.Position(s.Pos()).Line,
					examples:	ex,
					more:		more,
				})
			}
		case *ast.IfStmt:
			if ex, more, ok := chainExamples(fset, src, s); ok && len(ex) >= 2 {
				sites = append(sites, dispatchSite{
					kind:		"chain",
					line:		fset.Position(s.Pos()).Line,
					examples:	ex,
					more:		more,
				})
			}
		}
		return true
	})
	return sites
}

// HeaderHasMinimumScopes parses the comma separated scopesHeader string and returns an error
// if it lacks the minimum required scopes for performing API operations with gh.
func HeaderHasMinimumScopes(scopesHeader string) error {
	if scopesHeader == "" {

		return nil
	}

	search := map[string]bool{
		"repo":		false,
		"read:org":	false,
		"admin:org":	false,
	}
	for s := range strings.SplitSeq(scopesHeader, ",") {
		search[strings.TrimSpace(s)] = true
	}

	var missingScopes []string
	if !search["repo"] {
		missingScopes = append(missingScopes, "repo")
	}

	if !search["read:org"] && !search["write:org"] && !search["admin:org"] {
		missingScopes = append(missingScopes, "read:org")
	}

	if len(missingScopes) > 0 {
		return &MissingScopesError{MissingScopes: missingScopes}
	}
	return nil
}

