// ClipGrad performs L2-norm based gradient clipping on the tensor's data.
func (t *Tensor) ClipGrad(maxNorm float32) {
	if len(t.Data) == 0 {
		return
	}
	norm := float32(0.0)
	for _, v := range t.Data {
		norm += v * v
	}
	norm = float32(math.Sqrt(float64(norm)))
	if norm > maxNorm {
		scale := maxNorm / (norm + 1e-9)
		for i := range t.Data {
			t.Data[i] *= scale
		}
	}
}

