// Periodically check whether there is a reason to keep the connection alive, and if so, notify the codespace to do so
func (i *invoker) heartbeat(ctx context.Context, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			reason := ""

			if i.keepAliveOverride {
				reason = keepAliveEventName
			} else {
				reason = i.fwd.GetKeepAliveReason()
			}
			_ = i.notifyCodespaceOfClientActivity(ctx, reason)
		}
	}
}

// Save persists the BPE tokenizer (vocab + merges) to a GOB file.
func (b *BPETokenizer) Save(path string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("mkdir %s: %w", dir, err)
	}
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create %s: %w", path, err)
	}
	defer f.Close()
	return gob.NewEncoder(f).Encode(b)
}

// writeTo persists the lock file through an open file handle.
func writeTo(f *os.File, lf *file) error {
	data, err := json.MarshalIndent(lf, "", "  ")
	if err != nil {
		return err
	}

	if _, err := f.Seek(0, 0); err != nil {
		return err
	}
	if err := f.Truncate(0); err != nil {
		return err
	}
	_, err = f.Write(data)
	return err
}

// bestOption picks the *Option type whose example user is a method on
// the target type — the closest shape to the method being added.
func bestOption(tp *typeMethodPlan) *Type {
	for _, t := range tp.optTypes {
		if u := tp.optUser[t.Name]; u != nil &&
			strings.TrimPrefix(u.Receiver, "*") == tp.typ.Name {
			return t
		}
	}
	if len(tp.optTypes) > 0 {
		return tp.optTypes[0]
	}
	return nil
}

// detectPrimitive picks the dominant Go primitive mentioned in the
// query or code, defaulting to "function".
func detectPrimitive(query, code string) string {
	hay := strings.ToLower(query + "\n" + code)
	for _, pk := range primitiveKeywords {
		if strings.Contains(hay, pk.word) {
			return pk.primitive
		}
	}
	return "function"
}

// findFlow picks the orchestrating function behind candidate funcs: walk
// each candidate's callers up toward main and take the non-main function
// with the most callees. Constructors never orchestrate a feature.
func (p *Project) findFlow(cands []*Func) *Func {
	seen := map[string]*Func{}
	var walk func(fn *Func)
	walk = func(fn *Func) {
		if fn == nil || seen[fn.ID] != nil {
			return
		}
		seen[fn.ID] = fn
		for _, id := range fn.Callers {
			walk(p.byID[id])
		}
	}
	for _, c := range cands {
		walk(c)
	}
	var best *Func
	for _, fn := range seen {
		if fn.IsMain || fn.IsTest || fn.IsInit || isConstructor(fn.Name) {
			continue
		}
		if best == nil || len(fn.Calls) > len(best.Calls) {
			best = fn
		}
	}
	return best
}

// topNew picks the proposed-new keys worth naming: short config-ish
// words first (retry, limit), not values or prose.
func topNew(keys []string, n int) []string {
	var good, rest []string
	for _, k := range keys {
		if len(k) <= 12 && !strings.ContainsAny(k, "_-") {
			good = append(good, k)
		} else {
			rest = append(rest, k)
		}
	}
	out := append(good, rest...)
	if len(out) > n {
		out = out[:n]
	}
	return out
}

// simplestFunc picks the shortest signature: the smallest complete
// method is the best template for a beginner to copy.
func simplestFunc(fns []*Func) *Func {
	var best *Func
	for _, fn := range fns {
		if best == nil || len(fn.Sig) < len(best.Sig) ||
			(len(fn.Sig) == len(best.Sig) && fn.Name < best.Name) {
			best = fn
		}
	}
	return best
}

// resolveEntrySymbol picks the trace entry from the query: a
// quoted/backticked symbol first, then an exact name match, then the
// unique uncalled function (the flow's root), then main, then the
// first declared function.
func resolveEntrySymbol(query string, names []string, graph map[string][]string) (string, error) {
	if len(names) == 0 {
		return "", fmt.Errorf("xray: no functions declared in ContextCode")
	}
	if m := quotedSymbol.FindStringSubmatch(query); m != nil {
		want := m[1]
		if want == "" {
			want = m[2]
		}
		for _, n := range names {
			if n == want {
				return n, nil
			}
		}
		return "", fmt.Errorf("xray: no function %q in ContextCode (have: %s)", want, strings.Join(names, ", "))
	}
	lower := strings.ToLower(query)
	for _, n := range names {
		if strings.ToLower(n) == lower {
			return n, nil
		}
		for _, tok := range strings.FieldsFunc(lower, func(r rune) bool {
			return r < 'a' || r > 'z'
		}) {
			if tok == strings.ToLower(n) {
				return n, nil
			}
		}
	}
	if root, ok := uniqueRoot(graph); ok {
		return root, nil
	}
	for _, n := range names {
		if n == "main" {
			return n, nil
		}
	}
	return names[0], nil
}

// errorStyle picks the winning style by plurality; ties prefer the
// stdlib-only style, so %w or pkg/errors are only recommended when
// they are the clear habit.
func (m *styleMiner) errorStyle() string {
	best, style := m.stdErr, ErrorStyleStandard
	if m.fmtWrap > best {
		best, style = m.fmtWrap, ErrorStyleFmtWrap
	}
	if m.pkgErrors > best {
		best, style = m.pkgErrors, ErrorStylePkgErrors
	}
	return style
}

