// visitFuncDecl records context.Context usage and doc comments for
// exported functions and methods.
func (m *styleMiner) visitFuncDecl(d *ast.FuncDecl, info *types.Info) {
	if d == nil || d.Name == nil || !d.Name.IsExported() {
		return
	}
	m.exportedFuncs++
	m.exportedIdents++
	if d.Doc != nil {
		m.documented++
	}

	if d.Type != nil && d.Type.Params != nil && len(d.Type.Params.List) > 0 {
		if isContextType(d.Type.Params.List[0].Type, info) {
			m.ctxFuncs++
		}
	}
}

// visitGenDecl records doc comments for exported package-level types,
// consts, vars, and exported struct fields.
func (m *styleMiner) visitGenDecl(d *ast.GenDecl) {
	if d == nil {
		return
	}
	for _, spec := range d.Specs {
		switch s := spec.(type) {
		case *ast.TypeSpec:
			if s == nil || s.Name == nil || !s.Name.IsExported() {
				continue
			}
			m.exportedIdents++
			if s.Doc != nil || d.Doc != nil {
				m.documented++
			}
			if st, ok := s.Type.(*ast.StructType); ok {
				m.visitStructFieldsDocs(st)
			}
		case *ast.ValueSpec:
			if s == nil {
				continue
			}
			for _, name := range s.Names {
				if name == nil || !name.IsExported() {
					continue
				}
				m.exportedIdents++
				if s.Doc != nil || d.Doc != nil {
					m.documented++
				}
			}
		}
	}
}

// collectNilChecks records every variable ever compared against nil in
// the function body. A dereference of such a variable outside a
// nil-guarded region is suspicious: the author knew nil was possible.
func (a *analyzer) collectNilChecks(body *ast.BlockStmt) {
	ast.Inspect(body, func(n ast.Node) bool {
		b, ok := n.(*ast.BinaryExpr)
		if !ok || (b.Op != token.EQL && b.Op != token.NEQ) {
			return true
		}
		var v ast.Expr
		switch {
		case isNilLit(b.X):
			v = b.Y
		case isNilLit(b.Y):
			v = b.X
		default:
			return true
		}
		if id, ok := v.(*ast.Ident); ok {
			a.nilChecked[a.vkey(id)] = true
		}
		return true
	})
}

