// drawRaw redraws prompt+buf and places the cursor at pos, handling
// lines that wrap the terminal width. prevRows is how many rows the
// last draw occupied; it returns the rows the new draw occupies.
func (r *LineReader) drawRaw(prompt string, buf []rune, pos int, prevRows int) int {
	width := termWidth(r.term)
	if width < 10 {
		width = 80
	}
	promptCells := len([]rune(prompt))
	rows := (promptCells+len(buf))/width + 1

	var sb strings.Builder
	if prevRows > 1 {
		fmt.Fprintf(&sb, "\x1b[%dA", prevRows-1)
	}
	sb.WriteString("\r\x1b[J")
	sb.WriteString(prompt)
	sb.WriteString(string(buf))

	cursorAbs := promptCells + pos
	up := rows - 1 - cursorAbs/width
	if up > 0 {
		fmt.Fprintf(&sb, "\x1b[%dA", up)
	}
	sb.WriteString("\r")
	if col := cursorAbs % width; col > 0 {
		fmt.Fprintf(&sb, "\x1b[%dC", col)
	}
	fmt.Fprint(os.Stdout, sb.String())
	return rows
}

// comparableDestination reduces a destination goldmark reported to the single
// form used to decide whether a run of source is the node it came from. Percent
// encoding is left as written, since goldmark reports it unchanged and both
// sides of every comparison therefore carry it.
func comparableDestination(dest string) string {
	return unescapePunctuation(dest)
}

// comparableSource reduces a destination read straight from the source to that
// same form. It still carries the syntax goldmark had already removed: the
// whitespace separating the destination from the rest of the link, and the
// angle brackets that let a destination hold a space. Whitespace inside those
// brackets is part of the name, so only the whitespace outside them goes.
func comparableSource(raw string) string {
	return comparableDestination(trimAngles(strings.TrimSpace(raw)))
}

// getPackageName reduces a fully qualified function name to the package name
// There really ought to be a better way...
func getPackageName(f string) string {
	for {
		lastPeriod := strings.LastIndex(f, ".")
		lastSlash := strings.LastIndex(f, "/")
		if lastPeriod > lastSlash {
			f = f[:lastPeriod]
		} else {
			break
		}
	}

	return f
}

// stem reduces a word to a crude root so "deletion", "delete" and
// "deleted" match each other.
func stem(w string) string {
	w = strings.ToLower(w)

	if strings.HasSuffix(w, "es") && len(w) > 4 {
		for _, suf := range []string{"ses", "xes", "zes", "ches", "shes"} {
			if strings.HasSuffix(w, suf) {
				return w[:len(w)-2]
			}
		}
	}
	for _, suf := range []string{"ing", "ion", "ed", "s"} {
		if strings.HasSuffix(w, suf) && len(w) > len(suf)+2 {
			if suf == "s" && strings.HasSuffix(w, "ss") {
				continue
			}
			return w[:len(w)-len(suf)]
		}
	}
	return w
}

