// stripGitHubMetadata removes github-* keys from the metadata map and re-serializes.
func stripGitHubMetadata(content string) (string, error) {
	result, err := frontmatter.Parse(content)
	if err != nil {
		return "", err
	}

	meta, ok := result.RawYAML["metadata"].(map[string]any)
	if !ok {
		return content, nil
	}

	for k := range meta {
		if strings.HasPrefix(k, "github-") {
			delete(meta, k)
		}
	}

	if len(meta) == 0 {
		delete(result.RawYAML, "metadata")
	} else {
		result.RawYAML["metadata"] = meta
	}

	return frontmatter.Serialize(result.RawYAML, result.Body)
}

// stripCodeFences removes markdown fence lines LLMs like to wrap code
// in; the file markers carry the structure.
func stripCodeFences(s string) string {
	lines := strings.Split(s, "\n")
	out := lines[:0]
	for _, line := range lines {
		t := strings.TrimSpace(line)
		if t == "```" || t == "```go" {
			continue
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n")
}

// removeRepeatedChar removes multiple consecutive 'char's from a string.
// if s == "/a//b///c////" && char == '/', it returns "/a/b/c/"
func removeRepeatedChar(s string, char byte) string {

	hasRepeatedChar := false
	for i := 1; i < len(s); i++ {
		if s[i] == char && s[i-1] == char {
			hasRepeatedChar = true
			break
		}
	}
	if !hasRepeatedChar {
		return s
	}

	buf := make([]byte, 0, stackBufSize)

	r := 0
	w := 0

	for n := len(s); r < n; {
		if s[r] == char {

			bufApp(&buf, s, w, char)
			w++
			r++

			for r < n && s[r] == char {
				r++
			}
		} else {

			bufApp(&buf, s, w, s[r])
			w++
			r++
		}
	}

	if len(buf) == 0 {
		return s[:w]
	}
	return string(buf[:w])
}

// RemoveCommand removes one or more commands from a parent command.
func (c *Command) RemoveCommand(cmds ...*Command) {
	commands := []*Command{}
main:
	for _, command := range c.commands {
		for _, cmd := range cmds {
			if command == cmd {
				command.parent = nil
				continue main
			}
		}
		commands = append(commands, command)
	}
	c.commands = commands

	c.commandsMaxUseLen = 0
	c.commandsMaxCommandPathLen = 0
	c.commandsMaxNameLen = 0
	for _, command := range c.commands {
		usageLen := len(command.Use)
		if usageLen > c.commandsMaxUseLen {
			c.commandsMaxUseLen = usageLen
		}
		commandPathLen := len(command.CommandPath())
		if commandPathLen > c.commandsMaxCommandPathLen {
			c.commandsMaxCommandPathLen = commandPathLen
		}
		nameLen := len(command.Name())
		if nameLen > c.commandsMaxNameLen {
			c.commandsMaxNameLen = nameLen
		}
	}
}

// argsMinusFirstX removes only the first x from args.  Otherwise, commands that look like
// openshift admin policy add-role-to-user admin my-user, lose the admin argument (arg[4]).
// Special care needs to be taken not to remove a flag value.
func (c *Command) argsMinusFirstX(args []string, x string) []string {
	if len(args) == 0 {
		return args
	}
	c.mergePersistentFlags()
	flags := c.Flags()

Loop:
	for pos := 0; pos < len(args); pos++ {
		s := args[pos]
		switch {
		case s == "--":

			break Loop
		case strings.HasPrefix(s, "--") && !strings.Contains(s, "=") && !hasNoOptDefVal(s[2:], flags):
			fallthrough
		case strings.HasPrefix(s, "-") && !strings.Contains(s, "=") && len(s) == 2 && !shortHasNoOptDefVal(s[1:], flags):

			pos++
			continue
		case !strings.HasPrefix(s, "-"):

			if s == x {
				ret := make([]string, 0, len(args)-1)
				ret = append(ret, args[:pos]...)
				ret = append(ret, args[pos+1:]...)
				return ret
			}
		}
	}
	return args
}

