	return fs[:idx+int(p)+1]
}

// articleJoin renders ["File"] as "a file", ["For", "Win"] as "for win"
// (prepositions take no article), ["HTTP"] as "an http".
func articleJoin(words []string) string {
	if len(words) == 0 {
		return ""
	}
	lower := make([]string, len(words))
	for i, w := range words {
		lower[i] = strings.ToLower(w)
	}
	s := strings.Join(lower, " ")
	if s == "" {
		return ""
	}

	switch lower[0] {
	case "for", "to", "with", "by", "from", "of", "in", "on", "at", "as", "via", "and", "or":
		return s
	}
	art := "a"
	if strings.ContainsRune("aeiou", rune(s[0])) {
		art = "an"
	} else if w := words[0]; w == strings.ToUpper(w) && strings.ContainsRune("HFMLNRSX", rune(w[0])) {

		art = "an"
	}
	return art + " " + s
}

// methodSymbol renders "(*Server).Start" for pointer receivers and
// "Server.Start" for value receivers (including generic receivers like
// "Box[T].Get", where the base name is used).
func methodSymbol(fn *ast.FuncDecl) string {
	if fn.Recv == nil || len(fn.Recv.List) == 0 || fn.Recv.List[0] == nil {
		return fn.Name.Name
	}
	base := baseTypeName(fn.Recv.List[0].Type)
	if base == "" {
		return fn.Name.Name
	}
	if _, ok := fn.Recv.List[0].Type.(*ast.StarExpr); ok {
		return "(*" + base + ")." + fn.Name.Name
	}
	return base + "." + fn.Name.Name
}

