// effectPhrases renders a function's direct effects in plain words:
// "writes files (os.WriteFile)".
func effectPhrases(fn *Func) []string {
	var writes, reads, net []string
	for _, e := range fn.ExtCalls {
		for _, fx := range callEffects[e] {
			switch fx {
			case fxWrite:
				writes = append(writes, e)
			case fxRead:
				reads = append(reads, e)
			case fxNet:
				net = append(net, e)
			}
		}
	}
	var out []string
	if len(writes) > 0 {
		out = append(out, "writes files ("+strings.Join(writes, ", ")+")")
	}
	if len(reads) > 0 {
		out = append(out, "reads files ("+strings.Join(reads, ", ")+")")
	}
	if len(net) > 0 {
		out = append(out, "uses the network ("+strings.Join(net, ", ")+")")
	}
	return out
}

func RenderJobsCompact(cs *iostreams.ColorScheme, jobs []Job) string {
	lines := []string{}
	for _, job := range jobs {
		elapsed := job.CompletedAt.Sub(job.StartedAt)
		elapsedStr := fmt.Sprintf(" in %s", elapsed)
		if elapsed < 0 {
			elapsedStr = ""
		}
		symbol, symbolColor := Symbol(cs, job.Status, job.Conclusion)
		id := cs.Cyanf("%d", job.ID)
		lines = append(lines, fmt.Sprintf("%s %s%s (ID %s)", symbolColor(symbol), cs.Bold(job.Name), elapsedStr, id))

		if job.Status == Completed && job.Conclusion == Success {
			continue
		}

		var inProgressStepLine string
		var failedStepLines []string

		for _, step := range job.Steps {
			stepSymbol, stepSymColor := Symbol(cs, step.Status, step.Conclusion)
			stepLine := fmt.Sprintf("  %s %s", stepSymColor(stepSymbol), step.Name)

			if IsFailureState(step.Conclusion) {
				failedStepLines = append(failedStepLines, stepLine)
			}

			if step.Status == InProgress {
				inProgressStepLine = stepLine
			}
		}

		lines = append(lines, failedStepLines...)

		if inProgressStepLine != "" {
			lines = append(lines, inProgressStepLine)
		}
	}

	return strings.Join(lines, "\n")
}

func RenderJobs(cs *iostreams.ColorScheme, jobs []Job, verbose bool) string {
	lines := []string{}
	for _, job := range jobs {
		elapsed := job.CompletedAt.Sub(job.StartedAt)
		elapsedStr := fmt.Sprintf(" in %s", elapsed)
		if elapsed < 0 {
			elapsedStr = ""
		}
		symbol, symbolColor := Symbol(cs, job.Status, job.Conclusion)
		id := cs.Cyanf("%d", job.ID)
		lines = append(lines, fmt.Sprintf("%s %s%s (ID %s)", symbolColor(symbol), cs.Bold(job.Name), elapsedStr, id))
		if verbose || IsFailureState(job.Conclusion) {
			for _, step := range job.Steps {
				stepSymbol, stepSymColor := Symbol(cs, step.Status, step.Conclusion)
				lines = append(lines, fmt.Sprintf("  %s %s", stepSymColor(stepSymbol), step.Name))
			}
		}
	}

	return strings.Join(lines, "\n")
}

// tupleStrings renders a parameter or result tuple as "name type" for
// named entries and the bare type string for unnamed ones.
func tupleStrings(t *types.Tuple, qf types.Qualifier) []string {
	out := []string{}
	if t == nil {
		return out
	}
	for i := 0; i < t.Len(); i++ {
		v := t.At(i)
		if v == nil {
			continue
		}
		var typeStr string
		if vt := v.Type(); vt != nil {
			typeStr = types.TypeString(vt, qf)
		}
		if name := v.Name(); name != "" {
			out = append(out, name+" "+strings.TrimSpace(typeStr))
		} else {
			out = append(out, typeStr)
		}
	}
	return out
}

// paramTypeName renders a parameter type as "pkg.Type".
func paramTypeName(pkg *Package, e ast.Expr) string {
	for {
		if s, ok := e.(*ast.StarExpr); ok {
			e = s.X
			continue
		}
		break
	}
	switch t := e.(type) {
	case *ast.SelectorExpr:
		if id, ok := t.X.(*ast.Ident); ok {
			return id.Name + "." + t.Sel.Name
		}
	case *ast.Ident:
		return pkg.Name + "." + t.Name
	}
	return ""
}

// LinkPath renders a project-relative file path as a terminal-clickable
// link. When the analyzed project isn't the working directory — a fresh
// clone in ./example, a repo in ~/elsewhere — the path is rewritten
// relative to the working directory, so file:line links click through
// to the file. When the project is the working directory, the path is
// unchanged.
func (p *Project) LinkPath(rel string) string {
	if p.Root == "" || rel == "" {
		return rel
	}
	cwd, err := os.Getwd()
	if err != nil {
		return rel
	}
	if r, err := filepath.Rel(cwd, filepath.Join(p.Root, rel)); err == nil && r != "" {
		return r
	}
	return rel
}

// exprName renders a receiver/field type expression to a short name.
func exprName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return exprName(t.X)
	case *ast.IndexExpr:
		return exprName(t.X)
	case *ast.IndexListExpr:
		return exprName(t.X)
	case *ast.SelectorExpr:
		return t.Sel.Name
	}
	return ""
}

// snippetOf renders a short source snippet identifying the offending
// code. It never fails: unrecognized nodes degrade to "".
func snippetOf(n ast.Node) string {
	if e, ok := n.(ast.Expr); ok {
		return exprText(e)
	}
	return ""
}

// signatureStrings renders a signature's parameter and result lists.
// The final parameter of a variadic signature is rendered as "...T"
// rather than "[]T", matching how it is written in source.
func signatureStrings(sig *types.Signature, qf types.Qualifier) (params, results []string) {
	params = tupleStrings(sig.Params(), qf)
	if sig.Variadic() && sig.Params() != nil && sig.Params().Len() > 0 {
		last := sig.Params().At(sig.Params().Len() - 1)
		if last != nil {
			if slice, ok := last.Type().(*types.Slice); ok && slice != nil {
				var elem string
				if et := slice.Elem(); et != nil {
					elem = types.TypeString(et, qf)
				}
				name := ""
				if n := last.Name(); n != "" {
					name = n + " "
				}
				params[len(params)-1] = name + "..." + strings.TrimSpace(elem)
			}
		}
	}
	results = tupleStrings(sig.Results(), qf)
	return params, results
}

