// FailurePhrase renders failure modes as plain sentences.
func (fn *Func) FailurePhrase(p *Project) string {
	fm := fn.AnalyzeFailures(p)
	var parts []string

	if !fm.CanFail && len(fm.ErrorChecks) == 0 {
		return "no error handling — cannot fail (or failures are unchecked)"
	}

	if fm.CanFail {
		parts = append(parts, "can return an error")
	}
	if len(fm.ErrorChecks) > 0 {
		parts = append(parts, fmt.Sprintf("checks %d error condition(s)", len(fm.ErrorChecks)))
	}
	if len(fm.HandledBy) > 0 {

		seen := map[string]bool{}
		var unique []string
		for _, h := range fm.HandledBy {
			if !seen[h] {
				seen[h] = true
				unique = append(unique, h)
			}
		}
		parts = append(parts, fmt.Sprintf("errors handled by: %s", strings.Join(unique, ", ")))
	} else if fm.CanFail {
		parts = append(parts, "errors NOT handled by callers (may propagate up)")
	}
	if fm.RetrySafe {
		parts = append(parts, "safe to retry (no writes)")
	} else {
		parts = append(parts, "NOT safe to retry (has side effects)")
	}
	if len(fm.Panics) > 0 {
		parts = append(parts, "can panic")
	}

	return strings.Join(parts, "; ")
}

// Document renders full markdown documentation for the project: package
// overview, then every function and type with its signature and summary.
func (p *Project) Document() string {
	var b strings.Builder
	b.WriteString(fmt.Sprintf("# %s\n\n", p.Module))
	if p.Module == "" {
		b.WriteString("# Project\n\n")
	}
	b.WriteString(fmt.Sprintf("%d packages, %d files, %d lines\n\n", len(p.Packages), p.Files, p.Lines))

	for _, pkg := range p.Packages {
		b.WriteString(fmt.Sprintf("## Package %s\n\n", pkg.Name))
		if pkg.Doc != "" {
			b.WriteString(pkg.Doc + "\n\n")
		}
		b.WriteString(fmt.Sprintf("Directory: `%s` — %d functions, %d types\n\n",
			pkg.Dir, len(pkg.Funcs), len(pkg.Types)))

		if len(pkg.Types) > 0 {
			b.WriteString("### Types\n\n")
			for _, t := range pkg.Types {
				b.WriteString(t.Document(p))
				b.WriteString("\n")
			}
		}

		if len(pkg.Funcs) > 0 {
			b.WriteString("### Functions\n\n")
			fns := append([]*Func{}, pkg.Funcs...)
			sort.Slice(fns, func(i, j int) bool { return fns[i].Name < fns[j].Name })
			for _, fn := range fns {
				if fn.IsTest {
					continue
				}
				b.WriteString(fn.Document(p))
				b.WriteString("\n")
			}
		}
	}
	return b.String()
}

// ImportGraph renders internal package dependencies as text edges.
func (p *Project) ImportGraph() string {
	var b strings.Builder
	b.WriteString("PACKAGE DEPENDENCIES\n")
	any := false
	for _, pkg := range p.Packages {
		if len(pkg.Internal) == 0 {
			continue
		}
		any = true
		from := pkg.Dir
		if from == "" {
			from = "."
		}
		to := make([]string, len(pkg.Internal))
		copy(to, pkg.Internal)
		for i, d := range to {
			if d == "" {
				to[i] = "."
			}
		}
		sort.Strings(to)
		fmt.Fprintf(&b, "  %s → %s\n", from, strings.Join(to, ", "))
	}
	if !any {
		b.WriteString("  (no internal dependencies — packages are independent)\n")
	}
	return b.String()
}

// Document renders markdown documentation for a single function: signature,
// location, summary, and what it calls.
func (fn *Func) Document(p *Project) string {
	var b strings.Builder
	b.WriteString(fmt.Sprintf("#### `%s`\n\n", fn.Sig))
	b.WriteString(fmt.Sprintf("Defined at `%s:%d`\n\n", fn.File, fn.Line))
	if s := fn.Summary(); s != "" {
		b.WriteString(s + "\n\n")
	}
	if len(fn.Calls) > 0 {
		b.WriteString("Calls: ")
		var names []string
		seen := map[string]bool{}
		for _, id := range fn.Calls {
			if callee := p.byID[id]; callee != nil && !seen[callee.ID] {
				seen[callee.ID] = true
				names = append(names, "`"+callee.Display()+"`")
			}
			if len(names) >= 10 {
				break
			}
		}
		b.WriteString(strings.Join(names, ", ") + "\n\n")
	}
	return b.String()
}

