// formatQualifiers renders qualifiers into a plain query.
//
// The formatter is a custom formatting function that can be used to modify the
// output of each qualifier. If the formatter returns (nil, false) the default
// formatting will be applied.
func formatQualifiers(qs Qualifiers, formatter func(qualifier string, vs []string) (s []string, applicable bool)) []string {
	type entry struct {
		key	string
		values	[]string
	}

	var all []entry
	for k, vs := range qs.Map() {
		if len(vs) == 0 {
			continue
		}

		e := entry{key: k}

		if formatter != nil {
			if s, applicable := formatter(k, vs); applicable {
				e.values = s
				all = append(all, e)
				continue
			}
		}

		for _, v := range vs {
			e.values = append(e.values, fmt.Sprintf("%s:%s", k, quote(v)))
		}
		if len(e.values) > 1 {
			slices.Sort(e.values)
		}
		all = append(all, e)
	}

	slices.SortFunc(all, func(a, b entry) int {
		return strings.Compare(a.key, b.key)
	})

	result := make([]string, 0, len(all))
	for _, e := range all {
		result = append(result, e.values...)
	}
	return result
}

// buildRepairPrompt renders sandbox failures and the previous code
// into a follow-up repair prompt.
func buildRepairPrompt(task string, candidates map[string]string, errs []runner.TestError) string {
	var sb strings.Builder
	sb.WriteString("The generated Go code failed validation with the following compiler/test errors:\n")
	for _, e := range errs {
		fmt.Fprintf(&sb, "[File: %s, Line: %d, Error: %s]\n", e.FilePath, e.LineNumber, e.Message)
	}
	sb.WriteString("\nPrevious Code:\n")
	names := sortedKeys(candidates)
	if len(names) == 0 {
		sb.WriteString("(none)\n")
	}
	for _, name := range names {
