	}
	fmt.Fprintf(&sb, "\nOriginal task: %s\n\n", task)
	sb.WriteString("Please fix the Go syntax/type errors and return only the corrected Go code, ")
	sb.WriteString("using the same === FILE: <module-relative path> === format (one block per file, no explanations, no markdown fences).")
	return sb.String()
}

// exprText renders small expressions canonically for fact keys.
func exprText(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		if x := exprText(t.X); x != "" {
			return x + "." + t.Sel.Name
		}
	case *ast.CallExpr:
		if f := exprText(t.Fun); f != "" {
			return f + "(...)"
		}
	case *ast.IndexExpr:
		if x := exprText(t.X); x != "" {
			return x + "[" + exprText(t.Index) + "]"
		}
	case *ast.BasicLit:
		return t.Value
	}
	return ""
}

