// isPathWord reports whether a backticked word looks like a repo path:
// has a slash, no whitespace, not a URL or module path (first segment
// has no dot, so golang.org/x/sys is out), and looks like a file or
// directory (trailing slash, .go suffix, or at least two slashes — so
// allocs/op is out).
func isPathWord(w string) bool {
	if !strings.Contains(w, "/") || strings.ContainsAny(w, " \t\n") ||
		strings.Contains(w, "://") {
		return false
	}
	if strings.Contains(strings.Split(w, "/")[0], ".") {
		return false
	}
	if strings.HasSuffix(w, "/") || strings.HasSuffix(w, ".go") {
		return true
	}
	return strings.Count(w, "/") >= 2
}

// blockReturns reports whether a block ends in a return statement.
func blockReturns(b *ast.BlockStmt) bool {
	if b == nil || len(b.List) == 0 {
		return false
	}
	_, ok := b.List[len(b.List)-1].(*ast.ReturnStmt)
	return ok
}

// isSyntaxError reports whether a compiler message is a parse failure.
func isSyntaxError(msg string) bool {
	lower := strings.ToLower(msg)
	return strings.Contains(lower, "syntax error") || strings.HasPrefix(lower, "expected")
}

// coherent reports whether a concept's matches look like each other:
// the most common non-concept, non-stopword name token recurs in at
// least half the matches. CheckForWin/CheckWin cohere ("check");
// buildGameGrid/handleGameProgressTick don't.
func coherent(concept string, funcs []*Func) bool {
	if len(funcs) == 0 {
		return false
	}
	toks := map[string]int{}
	for _, fn := range funcs {
		for _, t := range tokenizeName(fn.Name) {
			if t == concept || planStopwords[t] {
				continue
			}
			toks[t]++
		}
	}
	for _, n := range toks {
		if n*2 >= len(funcs) {
			return true
		}
	}
	return false
}

// flagLikeCond reports whether a condition reads like an option/flag
// check: a bare bool parameter (if dryRun), a selector on a parameter
// typed by a project package (if cfg.DryRun), or a local alias of such
// a value (dry := cfg.DryRun; if dry). err != nil and friends don't
// match any shape.
func flagLikeCond(cond ast.Expr, paramNames map[string]bool, paramPkgs map[string]*Package, aliasOf map[string]string) bool {
	for {
		switch c := cond.(type) {
		case *ast.ParenExpr:
			cond = c.X
		case *ast.UnaryExpr:
			cond = c.X
		default:
			goto done
		}
	}
done:
	switch c := cond.(type) {
	case *ast.Ident:
		return paramNames[c.Name] || aliasOf[c.Name] != ""
	case *ast.SelectorExpr:
		if id, ok := c.X.(*ast.Ident); ok {
			_, isParam := paramPkgs[id.Name]
			return isParam || paramNames[id.Name]
		}
	}
	return false
}

// isRemoteDestination reports whether a destination addresses somewhere other
// than the filesystem, so that an attached file is never confused with a URI.
//
// A one letter scheme is a Windows volume rather than a scheme, which keeps
// "C:\pictures\login.png" a path. A host with no scheme is the protocol
// relative form, which inherits the scheme of the page it sits on. Anything too
// malformed to parse is left to the path lookup, which will not match it.
func isRemoteDestination(dest string) bool {
	u, err := url.Parse(dest)
	if err != nil {
		return false
	}
	return len(u.Scheme) > 1 || u.Host != ""
}

// IsCodeIntentFamily reports whether a domain uses the codeintent model
// architecture and training pipeline (cross-attention, encoder-side copy
// gate, pointer-generator aux loss, no synonym augmentation, capped
// vocab). Both codeintent and the copyexp falsification experiment do.
func IsCodeIntentFamily(domain string) bool {
	return domain == CodeIntentDomain || domain == CopyExpDomain || domain == CodeIntentBigDomain
}

// callWraps reports whether a fmt.Errorf call wraps with %w, based on
// a string-literal format argument.
func callWraps(c *ast.CallExpr) bool {
	if c == nil || len(c.Args) == 0 {
		return false
	}
	lit, ok := c.Args[0].(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return false
	}
	s, err := strconv.Unquote(lit.Value)
	if err != nil {
		return false
	}
	return strings.Contains(s, "%w")
}

// isRunnableGoCommand reports whether a gocli reply is safe to offer for
// execution: a single go/gofmt invocation with no shell metacharacters.
func isRunnableGoCommand(reply string) bool {
	r := strings.TrimSpace(reply)
	return runnableGoCommand.MatchString(r) && !shellMetachars.MatchString(r)
}

// looksLikeCompilerError reports whether a message reads as a
// type-check/build failure rather than a failed test expectation.
func looksLikeCompilerError(msg string) bool {
	lower := strings.ToLower(msg)
	for _, marker := range compilerMarkers {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return false
}

// wordHit reports whether a name token matches an issue keyword,
// tolerating stemmer wobble ("scanning" stems to "scann" but "Scan"
// stems to "scan") via prefix match. Only used for ranking — never
// for a semantic claim.
func wordHit(tok string, kw map[string]bool) bool {
	if kw[tok] {
		return true
	}
	for k := range kw {
		if len(tok) >= 4 && len(k) >= 4 &&
			(strings.HasPrefix(tok, k) || strings.HasPrefix(k, tok)) {
			return true
		}
	}
	return false
}

// IsSkillPath reports whether a skill selector looks like a repo-relative path
// rather than a simple skill name.
func IsSkillPath(name string) bool {
	name = strings.TrimSuffix(name, "/")
	if name == "" {
		return false
	}
	if strings.HasSuffix(name, "/SKILL.md") {
		return true
	}
	if strings.HasPrefix(name, "skills/") || strings.HasPrefix(name, "plugins/") {
		return true
	}
	if strings.Contains(name, "/skills/") || strings.Contains(name, "/plugins/") {
		return true
	}
	if strings.Count(name, "/") >= 2 {
		return true
	}
	return false
}

