// isContextType reports whether e denotes context.Context.
func isContextType(e ast.Expr, info *types.Info) bool {
	if e == nil || info == nil {
		return false
	}
	named, ok := info.TypeOf(e).(*types.Named)
	if !ok || named == nil || named.Obj() == nil || named.Obj().Pkg() == nil {
		return false
	}
	return named.Obj().Pkg().Path() == "context" && named.Obj().Name() == "Context"
}

// comparesLiteral reports whether e is `x == "lit"` or `"lit" == x`.
func comparesLiteral(e ast.Expr) bool {
	bin, ok := e.(*ast.BinaryExpr)
	if !ok {
		return false
	}
	if bin.Op != token.EQL && bin.Op != token.NEQ {
		return false
	}
	_, lLit := bin.X.(*ast.BasicLit)
	_, rLit := bin.Y.(*ast.BasicLit)
	return lLit || rLit
}

// isPureBound reports whether e is safe to evaluate once up front:
// a literal, a variable, or a field selection. Anything else (a call,
// a function value, ...) might have side effects the loop relied on
// re-evaluating each iteration.
func isPureBound(e ast.Expr) bool {
	switch e.(type) {
	case *ast.BasicLit, *ast.Ident, *ast.SelectorExpr:
		return true
	}
	return false
}

// isNotFound reports whether err is an API error carrying a 404 status. The release lookups
// treat a missing release as a sentinel rather than an error, and the api client reports the
// status through an HTTPError rather than through a response the call site can inspect.
func isNotFound(err error) bool {
	httpErr, ok := errors.AsType[api.HTTPError](err)
	return ok && httpErr.StatusCode == http.StatusNotFound
}

