// isTunableFile reports whether path is a candidate for mutation:
// Go source, not a test (tests are the harness, never the subject).
func isTunableFile(path string) bool {
	return strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go")
}

// IsHTMLFile reports whether path is an HTML file, which create reads as an
// HTML document. It goes by the .html and .htm extensions, in any case.
func IsHTMLFile(path string) bool {
	ext := filepath.Ext(path)
	return strings.EqualFold(ext, ".html") || strings.EqualFold(ext, ".htm")
}

// IsShortcutFile reports whether path is an Internet Shortcut file, which
// artifact commands read as a link. Like Windows, it goes by the .url
// extension, in any case.
func IsShortcutFile(path string) bool {
	return strings.EqualFold(filepath.Ext(path), ".url")
}

// isRelativePath reports whether path is relative to a directory, and so can
// be placed inside the one the markdown was read from. filepath.IsAbs is not
// enough on Windows, where "\x" is rooted on the current drive and "C:x" names
// a drive of its own, though neither is absolute.
func isRelativePath(path string) bool {
	if path == "" || filepath.IsAbs(path) || filepath.VolumeName(path) != "" {
		return false
	}
	return !os.IsPathSeparator(path[0])
}

func (e *Extension) IsPinned() bool {
	e.mu.RLock()
	if e.isPinned != nil {
		defer e.mu.RUnlock()
		return *e.isPinned
	}
	e.mu.RUnlock()

	var isPinned bool
	switch e.kind {
	case LocalKind:
	case BinaryKind:
		if manifest, err := e.loadManifest(); err == nil {
			isPinned = manifest.IsPinned
		}
	case GitKind:
		extDir := filepath.Dir(e.path)
		pinPath := filepath.Join(extDir, fmt.Sprintf(".pin-%s", e.CurrentVersion()))
		if _, err := os.Stat(pinPath); err == nil {
			isPinned = true
		} else {
			isPinned = false
		}
	}

	e.mu.Lock()
	e.isPinned = &isPinned
	e.mu.Unlock()

	return *e.isPinned
}

// IsExplainQuestion reports whether q seeks an explanation of a symbol —
// the what-does, what-for, what-is, explain, tell-me-about, and how-works
// families — and returns the cleaned symbol name for fact extraction.
// It mirrors the Answer dispatch order (qWhatFor before qWhatIs; qSig is
// deterministic and excluded) so the neural explainer and the template
// path agree on which questions they handle.
func IsExplainQuestion(q string) (string, bool) {
	if qSig.MatchString(q) {
		return "", false
	}
	for _, re := range []*regexp.Regexp{qWhatDoes, qHowWorks, qExplain, qTellAbt, qWhatFor, qWhatIs} {
		if m := re.FindStringSubmatch(q); m != nil {
			if sym := cleanSymbol(m[1]); sym != "" && !startsWithArticle(sym) {
				return sym, true
			}
		}
	}
	return "", false
}

// standsAlone reports whether replacing a node with a bare URL will render as
// a player.
//
// GitHub promotes a bare asset URL to a video exactly when it is the whole
// content of a paragraph, wherever that paragraph sits: a blockquote or a
// loose list item qualifies, a URL alone on a source line inside a wrapped
// paragraph does not. A tight list item holds no paragraph, only a text
// block, which is why a lone reference there stays a link. goldmark draws the
// same distinction, so testing for a paragraph is the whole rule.
func standsAlone(src []byte, block ast.Node, node byteRange) bool {
	if _, ok := block.(*ast.Paragraph); !ok {
		return false
	}
	lo, hi, ok := blockRange(block, len(src))

	if !ok || node.start < lo || node.stop > hi {
		return false
	}
	for _, c := range src[lo:node.start] {
		if !isSpace(c) {
			return false
		}
	}
	for _, c := range src[node.stop:hi] {
		if !isSpace(c) {
			return false
		}
	}
	return true
}

// isASCII reports whether s contains only ASCII characters.
// See https://stackoverflow.com/questions/53069040/checking-a-string-contains-only-ascii-characters.
func isASCII(s string) bool {
	for i := range len(s) {
		if s[i] > unicode.MaxASCII {
			return false
		}
	}
	return true
}

// terminates reports whether s never falls through (return or panic).
func (a *analyzer) terminates(s ast.Stmt) bool {
	switch t := s.(type) {
	case *ast.ReturnStmt:
		return true
	case *ast.ExprStmt:
		if call, ok := t.X.(*ast.CallExpr); ok {
			if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "panic" {
				return true
			}
		}
	case *ast.IfStmt:
		thenTerm := t.Body != nil && a.blockTerminates(t.Body)
		var elseTerm bool
		switch e := t.Else.(type) {
		case *ast.IfStmt:
			elseTerm = a.terminates(e)
		case *ast.BlockStmt:
			elseTerm = a.blockTerminates(e)
		}
		return thenTerm && elseTerm && t.Else != nil
	}
	return false
}

// isPkg reports whether sel denotes a member of the given package path.
func (a *analyzer) isPkg(sel *ast.SelectorExpr, path string) bool {
	if a.info == nil {
