// loopAppendsTo reports whether the loop body contains `name =
// append(name, ...)` (plain assignment, not :=) and no redefinition
// of name anywhere in the loop (which would shadow the outer var).
func loopAppendsTo(stmt ast.Stmt, name string) bool {
	var body *ast.BlockStmt
	switch l := stmt.(type) {
	case *ast.RangeStmt:
		body = l.Body
	case *ast.ForStmt:
		body = l.Body
	default:
		return false
	}
	appends := false
	ok := true
	ast.Inspect(body, func(n ast.Node) bool {
		if !ok {
			return false
		}
		as, isAssign := n.(*ast.AssignStmt)
		if !isAssign {
			return true
		}
		for _, lhs := range as.Lhs {
			id, isIdent := lhs.(*ast.Ident)
			if !isIdent || id.Name != name {
				continue
			}
			if as.Tok == token.DEFINE {
				ok = false
				return false
			}
			if as.Tok == token.ASSIGN && len(as.Lhs) == 1 && len(as.Rhs) == 1 {
				if call, isCall := as.Rhs[0].(*ast.CallExpr); isCall {
					if fun, isIdent := call.Fun.(*ast.Ident); isIdent && fun.Name == "append" {
						if arg, isIdent := call.Args[0].(*ast.Ident); isIdent && arg.Name == name {
							appends = true
						}
					}
				}
			}
		}
		return true
	})
	return ok && appends
}

// siteMatchesTitle reports whether the mechanism site is what the issue
// title is about: the title names a mechanism word and that mechanism
// lives in the site's package. Otherwise a single anchor misleads —
// "Add Deletion Report Export" anchored on the file manager because the
// issue says "files" — and the multi-file plan takes over.
func (p *Project) siteMatchesTitle(c IssueConcepts, site *MechanismSite) bool {
	if site == nil {
		return false
	}
	words := map[string]bool{}
	for _, w := range strings.FieldsFunc(strings.ToLower(c.Title),
		func(r rune) bool { return r < 'a' || r > 'z' }) {
		words[w] = true
		words[singular(w)] = true
	}
	for _, m := range mechanismTable {
		if words[m] {
			if s := p.FindMechanism(m); s != nil && s.Pkg == site.Pkg {
				return true
			}
		}
	}
	return false
}

