// ZeroGrad resets the gradient of the tensor to zeros.
func (t *Tensor) ZeroGrad() {
	if t.RequiresGrad {
		if t.Grad == nil {
			t.Grad = NewTensor(t.Shape, make([]float32, len(t.Data)), false)
		} else {
			for i := range t.Grad.Data {
				t.Grad.Data[i] = 0
			}
		}
	}
}

// ZeroGrad resets the gradients of all parameters in parallel.
func (o *Adam) ZeroGrad() {
	var wg sync.WaitGroup
	numWorkers := runtime.NumCPU()
	if numWorkers > 16 {
		numWorkers = 16
	}

	workCh := make(chan *Tensor, len(o.parameters))
	for _, p := range o.parameters {
		workCh <- p
	}
	close(workCh)

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for p := range workCh {
				p.ZeroGrad()
			}
		}()
	}
	wg.Wait()
}

// ZeroGrad resets the gradients of all parameters.
func (o *CoolingOptimizer) ZeroGrad() {
	o.Base.ZeroGrad()
}

// reuseFuncs resolves "reuse X()" references: identifiers the issue
// says to reuse, resolved against the index.
func (p *Project) reuseFuncs(c IssueConcepts) []*Func {
	if !strings.Contains(strings.ToLower(c.Title+"\n"+c.Body), "reus") {
		return nil
	}
	var out []*Func
	seen := map[string]bool{}
	for _, m := range identParenRe.FindAllStringSubmatch(c.Title+"\n"+c.Body, -1) {
		name := m[1]
		if seen[name] {
			continue
		}
		seen[name] = true
		if fn, _, _, _ := p.resolve(name); fn != nil {
			out = append(out, fn)
		}
	}
	return out
}

