// topCallees resolves fn's callees to *Func, deduplicated in call-site
// order, skipping tests and init functions. The limit caps breadth.
func (p *Project) topCallees(fn *Func, limit int) []*Func {
	var out []*Func
	seen := map[string]bool{}
	for _, id := range fn.Calls {
		if seen[id] {
			continue
		}
		seen[id] = true
		c, ok := p.byID[id]
		if !ok || c.IsTest || c.IsInit {
			continue
		}
		out = append(out, c)
		if len(out) >= limit {
			break
		}
	}
	return out
}

// ShowRefs resolves fully-qualified refs to commit hashes.
func (c *Client) ShowRefs(ctx context.Context, refs []string) ([]Ref, error) {
	args := append([]string{"show-ref", "--verify", "--"}, refs...)
	cmd, err := c.Command(ctx, args...)
	if err != nil {
		return nil, err
	}

	out, err := cmd.Output()
	var verified []Ref
	for _, line := range outputLines(out) {
		parts := strings.SplitN(line, " ", 2)
		if len(parts) < 2 {
			continue
		}
		verified = append(verified, Ref{
			Hash:	parts[0],
			Name:	parts[1],
		})
	}
	return verified, err
}

