// rhsValue resolves the value of an assignment RHS to a "pkg.Type.Field"
// when it's a field read (cfg.DryRun) or a chained alias (x := dry).
// Anything else clears the alias.
func rhsValue(e ast.Expr, typeName func(string) string, aliasOf map[string]string) string {
	switch e := e.(type) {
	case *ast.SelectorExpr:
		if id, ok := e.X.(*ast.Ident); ok {
			if t := typeName(id.Name); t != "" {
				return t + "." + e.Sel.Name
			}
		}
	case *ast.Ident:
		return aliasOf[e.Name]
	}
	return ""
}

// loadTrainingCheckpoint restores a killed run's best weights for -resume.
// It refuses (returns an error) when the sidecar is missing or the
// vocabulary no longer matches, so a stale checkpoint can never corrupt a
// fresh run — the caller falls back to training from epoch 1.
func loadTrainingCheckpoint(tok *tokenizer.Tokenizer, curFP uint64, ckptPath, metaPath string) (*seq2seq.Seq2Seq, ckptMeta, error) {
	var meta ckptMeta
	data, err := os.ReadFile(metaPath)
	if err != nil {
		return nil, meta, fmt.Errorf("no checkpoint sidecar: %w", err)
	}
	if err := json.Unmarshal(data, &meta); err != nil {
		return nil, meta, fmt.Errorf("bad checkpoint sidecar: %w", err)
	}
	if meta.VocabFP != curFP {
		return nil, meta, fmt.Errorf("checkpoint vocab fingerprint %d != current %d: data changed, refusing resume", meta.VocabFP, curFP)
	}
	model, err := seq2seq.Load(ckptPath, tok)
	if err != nil {
		return nil, meta, fmt.Errorf("loading checkpoint weights: %w", err)
	}
	return model, meta, nil
}

// LoadState restores Adam optimizer state sequentially.
func (o *Adam) LoadState(path string) error {
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("optimizer LoadState: open: %w", err)
	}
	defer f.Close()
	gz, err := gzip.NewReader(f)
	if err != nil {
		return fmt.Errorf("optimizer LoadState: gzip: %w", err)
	}
	defer gz.Close()
	dec := gob.NewDecoder(gz)

	var t, count int
	if err := dec.Decode(&t); err != nil {
		return err
	}
	if err := dec.Decode(&count); err != nil {
		return err
	}
	o.t = t

	for i, p := range o.parameters {
		if i >= count {
			break
		}
		var mData, vData []float32
		if err := dec.Decode(&mData); err != nil {
			return err
		}
		if err := dec.Decode(&vData); err != nil {
			return err
		}

		if len(mData) == len(p.Data) {
			o.m[p] = NewTensor(p.Shape, mData, false)
		}
		if len(vData) == len(p.Data) {
			o.v[p] = NewTensor(p.Shape, vData, false)
		}
	}
	return nil
}

