			tag = 'd'
		} else if j < bj {
			tag = 'i'
		}
		if tag > 0 {
			opCodes = append(opCodes, OpCode{tag, i, ai, j, bj})
		}
		i, j = ai+size, bj+size

		if size > 0 {
			opCodes = append(opCodes, OpCode{'e', ai, i, bj, j})
