	formatted, err := format.Source([]byte(c.Snippet))
	if err != nil {
		return nil, fmt.Errorf("beginner: internal snippet error for %q: %w", key, err)
	}
	out := c
	out.Snippet = string(formatted)
	return &out, nil
}

