// callRoots returns exported functions nothing calls, by importance —
// the API surface a library is used through.
func (p *Project) callRoots(n int) []*Func {
	var roots []*Func
	for _, fn := range p.byID {
		if fn.Exported && !fn.IsTest && !fn.IsInit && len(fn.Callers) == 0 {
			roots = append(roots, fn)
		}
	}
	sort.Slice(roots, func(i, j int) bool {
		if roots[i].Score != roots[j].Score {
			return roots[i].Score > roots[j].Score
		}
		return roots[i].ID < roots[j].ID
	})
	if len(roots) > n {
		roots = roots[:n]
	}
	return roots
}

// KeyTypes returns exported struct/interface types, interfaces with
// implementers first, then by method count.
func (p *Project) KeyTypes(n int) []*Type {
	var out []*Type
	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t.Exported && (t.Kind == "struct" || t.Kind == "interface") {
				out = append(out, t)
			}
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].ImplCount != out[j].ImplCount {
			return out[i].ImplCount > out[j].ImplCount
		}
		if len(out[i].Methods) != len(out[j].Methods) {
			return len(out[i].Methods) > len(out[j].Methods)
		}
		return out[i].Name < out[j].Name
	})
	if len(out) > n {
		out = out[:n]
	}
	return out
}

