// lenArg returns the array argument if e is a len(...) call.
func lenArg(e ast.Expr) ast.Expr {
	c, ok := e.(*ast.CallExpr)
	if !ok || len(c.Args) != 1 {
		return nil
	}
	if id, ok := c.Fun.(*ast.Ident); !ok || id.Name != "len" {
