// FindNonLegacy returns the list of template file paths from the template folder (according to the "upgraded multiple template builder")
func FindNonLegacy(rootDir string, name string) []string {
	results := []string{}

	candidateDirs := []string{
		path.Join(rootDir, ".github"),
		rootDir,
		path.Join(rootDir, "docs"),
	}

mainLoop:
	for _, dir := range candidateDirs {
		files, err := os.ReadDir(dir)
		if err != nil {
			continue
		}

		for _, file := range files {
			if strings.EqualFold(file.Name(), name) && file.IsDir() {
				templates, err := os.ReadDir(path.Join(dir, file.Name()))
				if err != nil {
					break
				}
				for _, tf := range templates {
					if strings.HasSuffix(tf.Name(), ".md") &&
						file.Type() != fs.ModeSymlink {
						results = append(results, path.Join(dir, file.Name(), tf.Name()))
					}
				}
				if len(results) > 0 {
					break mainLoop
				}
				break
			}
		}
	}

	sort.Strings(results)
	return results
}

// checkoutFor returns the local directory to analyze for owner/repo: the
// checkout the chat is already looking at when its git origin matches
// (so file links point at the folder you cloned to), else the cached
// shallow clone.
func checkoutFor(owner, repo string) (string, error) {
	if want := strings.ToLower(owner + "/" + repo); lastAnalyzeRoot != "" && gitOriginRepo(lastAnalyzeRoot) == want {
		if rel, err := filepath.Rel(cwd(), lastAnalyzeRoot); err == nil {
			fmt.Printf("   using your %s checkout…\n", rel)
		}
		return lastAnalyzeRoot, nil
	}
	fmt.Printf("   cloning %s/%s (once, cached)…\n", owner, repo)
	dir, err := ensureGitHubRepo("github.com/" + owner + "/" + repo)
	if err != nil {
		return "", fmt.Errorf("couldn't clone %s/%s: %w", owner, repo, err)
	}
	return dir, nil
}

// LocalFlags returns the local FlagSet specifically set in the current command.
// This function does not modify the flags of the current command, it's purpose is to return the current state.
func (c *Command) LocalFlags() *flag.FlagSet {
	c.mergePersistentFlags()

	if c.lflags == nil {
		c.lflags = flag.NewFlagSet(c.DisplayName(), flag.ContinueOnError)
		if c.flagErrorBuf == nil {
			c.flagErrorBuf = new(bytes.Buffer)
		}
		c.lflags.SetOutput(c.flagErrorBuf)
	}
	c.lflags.SortFlags = c.Flags().SortFlags
	if c.globNormFunc != nil {
		c.lflags.SetNormalizeFunc(c.globNormFunc)
	}

	addToLocal := func(f *flag.Flag) {

		if c.lflags.Lookup(f.Name) == nil && f != c.parentsPflags.Lookup(f.Name) {
			c.lflags.AddFlag(f)
		}
	}
	c.Flags().VisitAll(addToLocal)
	c.PersistentFlags().VisitAll(addToLocal)
	return c.lflags
}

