func (a *analyzer) report() *SafetyReport {
	score := 100.0
	critical := 0
	for _, v := range a.violations {
		if v.Severity == SeverityCritical {
			score -= 25
			critical++
		} else {
			score -= 10
		}
	}
	if score < 0 {
