// titleNouns returns the significant stemmed words of the issue title,
// plus the unstemmed words for display.
func titleNouns(title string) (stems, words []string) {
	seen := map[string]bool{}
	for _, w := range strings.FieldsFunc(strings.ToLower(title),
		func(r rune) bool { return r < 'a' || r > 'z' }) {
		if len(w) < 3 || planStopwords[w] {
			continue
		}
		s := stem(w)
		if !seen[s] {
			seen[s] = true
			stems = append(stems, s)
			words = append(words, w)
		}
	}
	return stems, words
}

// uniqueRoot returns the single function that no other declared
// function calls — the entry point of the flow.
func uniqueRoot(graph map[string][]string) (string, bool) {
	called := map[string]bool{}
	for _, calls := range graph {
		for _, c := range calls {
			called[c] = true
		}
	}
	var roots []string
	for name := range graph {
		if !called[name] {
			roots = append(roots, name)
		}
	}
	if len(roots) == 1 {
		return roots[0], true
	}
	return "", false
}

// posEncSinusoidal returns the sinusoidal positional encoding for position
// pos with dimension d. Standard transformer formulation.
func posEncSinusoidal(pos, d int) []float32 {
	pe := make([]float32, d)
	for i := 0; i < d; i += 2 {
		div := float32(math.Pow(10000, float64(i)/float64(d)))
		pe[i] = float32(math.Sin(float64(pos) / float64(div)))
		if i+1 < d {
			pe[i+1] = float32(math.Cos(float64(pos) / float64(div)))
		}
	}
	return pe
}

// CurrentChunkSize returns the size of the current chunk (rows, cols).
// It handles cases where the last chunk in a dimension might be smaller.
func (it *MatMul4DIterator) CurrentChunkSize() (rows, cols int) {

	rows = it.chunkSizeRows
	cols = it.chunkSizeCols

	if it.currentI+rows > it.resultRows {
		rows = it.resultRows - it.currentI
	}
	if it.currentJ+cols > it.resultCols {
		cols = it.resultCols - it.currentJ
	}
	return rows, cols
}

