	return getTyped[int8](c, key)
}

// GetInt returns the value associated with the key as an integer.
func (c *Context) GetInt(key any) int {
	return getTyped[int](c, key)
}

// GetUint16 returns the value associated with the key as an unsigned integer 16.
func (c *Context) GetUint16(key any) uint16 {
	return getTyped[uint16](c, key)
}

// GetUint32 returns the value associated with the key as an unsigned integer 32.
func (c *Context) GetUint32(key any) uint32 {
	return getTyped[uint32](c, key)
}

// GetUint64 returns the value associated with the key as an unsigned integer 64.
func (c *Context) GetUint64(key any) uint64 {
	return getTyped[uint64](c, key)
}

// GetUint8 returns the value associated with the key as an unsigned integer 8.
func (c *Context) GetUint8(key any) uint8 {
	return getTyped[uint8](c, key)
}

// GetUint returns the value associated with the key as an unsigned integer.
func (c *Context) GetUint(key any) uint {
	return getTyped[uint](c, key)
}

// GetTime returns the value associated with the key as time.
func (c *Context) GetTime(key any) time.Time {
	return getTyped[time.Time](c, key)
}

// Value returns the value associated with this context for key, or nil
// if no value is associated with key. Successive calls to Value with
// the same key returns the same result.
func (c *Context) Value(key any) any {
	if key == ContextRequestKey {
		return c.Request
	}
	if key == ContextKey {
		return c
	}
	if keyAsString, ok := key.(string); ok {
		if val, exists := c.Get(keyAsString); exists {
			return val
		}
	}
	if !c.hasRequestContext() {
		return nil
	}
	return c.Request.Context().Value(key)
}

// MustGet returns the value for the given key if it exists, otherwise it panics.
func (c *Context) MustGet(key any) any {
	if value, exists := c.Get(key); exists {
		return value
	}
	panic(fmt.Sprintf("key %v does not exist", key))
}

// Get returns the value for the given key, ie: (value, true).
// If the value does not exist it returns (nil, false)
func (c *Context) Get(key any) (value any, exists bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	value, exists = c.Keys[key]
	return
}

// PushDefault returns the value of push.default in the config. If the value
// is not set, it returns "simple" (the default git value). See
// https://git-scm.com/docs/git-config#Documentation/git-config.txt-pushdefault
func (c *Client) PushDefault(ctx context.Context) (PushDefault, error) {
	pushDefault, err := c.Config(ctx, "push.default")
	if err == nil {
		return ParsePushDefault(pushDefault)
	}

	// If there is an error that the config key is not set, return the default value
	// that git uses since 2.0.
	var gitError *GitError
	if ok := errors.As(err, &gitError); ok && gitError.ExitCode == 1 {
		return PushDefaultSimple, nil
	}
	return "", err
}

// RemotePushDefault returns the value of remote.pushDefault in the config. If
// the value is not set, it returns an empty string.
func (c *Client) RemotePushDefault(ctx context.Context) (string, error) {
	remotePushDefault, err := c.Config(ctx, "remote.pushDefault")
	if err == nil {
		return remotePushDefault, nil
	}

	var gitError *GitError
	if ok := errors.As(err, &gitError); ok && gitError.ExitCode == 1 {
		return "", nil
	}

	return "", err
}

// GetActiveHelpConfig returns the value of the ActiveHelp environment variable
// <PROGRAM>_ACTIVE_HELP where <PROGRAM> is the name of the root command in upper
// case, with all non-ASCII-alphanumeric characters replaced by `_`.
// It will always return "0" if the global environment variable COBRA_ACTIVE_HELP
// is set to "0".
func GetActiveHelpConfig(cmd *Command) string {
	activeHelpCfg := os.Getenv(activeHelpGlobalEnvVar)
	if activeHelpCfg != activeHelpGlobalDisable {
		activeHelpCfg = os.Getenv(activeHelpEnvVar(cmd.Root().Name()))
	}
	return activeHelpCfg
}

// getEnvConfig returns the value of the configuration environment variable
// <PROGRAM>_<SUFFIX> where <PROGRAM> is the name of the root command in upper
// case, with all non-ASCII-alphanumeric characters replaced by `_`.
// If the value is empty or not set, the value of the environment variable
// COBRA_<SUFFIX> is returned instead.
func getEnvConfig(cmd *Command, suffix string) string {
	v := os.Getenv(configEnvVar(cmd.Root().Name(), suffix))
	if v == "" {
		v = os.Getenv(configEnvVar(configEnvVarGlobalPrefix, suffix))
	}
	return v
}

// Get returns the value of the first Param which key matches the given name and a boolean true.
// If no matching Param is found, an empty string is returned and a boolean false .
func (ps Params) Get(name string) (string, bool) {
	for _, entry := range ps {
		if entry.Key == name {
			return entry.Value, true
		}
	}
	return "", false
}

// ByName returns the value of the first Param which key matches the given name.
// If no matching Param is found, an empty string is returned.
func (ps Params) ByName(name string) (va string) {
	va, _ = ps.Get(name)
	return
}

// Param returns the value of the URL param.
// It is a shortcut for c.Params.ByName(key)
//
//	router.GET("/user/:id", func(c *gin.Context) {
//	    // a GET request to /user/john
//	    id := c.Param("id") // id == "john"
//	    // a GET request to /user/john/
//	    id := c.Param("id") // id == "/john/"
//	})
func (c *Context) Param(key string) string {
	return c.Params.ByName(key)
}

// FindVersion returns the version numbered number from an artifact's edit
// history, or nil for the current version. Versions come newest first, so the
// newest version's number means the current version, like 0 does. A number
// the API didn't return is an error.
func FindVersion(a *client.ArtifactWithVersions, number int) (*client.Version, error) {
	if number == 0 {
		return nil, nil
	}
	i := slices.IndexFunc(a.Versions, func(v client.Version) bool { return v.Version == number })
	switch {
	case i < 0:
		return nil, fmt.Errorf("version %d not found for artifact %d", number, a.Number)
	case i == 0:
		return nil, nil
	}
	return &a.Versions[i], nil
}

// getVersionTemplateFunc returns the version template function for the command
// going up the command tree if necessary.
func (c *Command) getVersionTemplateFunc() func(w io.Writer, data interface{}) error {
	if c.versionTemplate != nil {
		return c.versionTemplate.fn
	}

	if c.HasParent() {
		return c.parent.getVersionTemplateFunc()
	}
	return defaultVersionFunc
}

func (c *cfg) Version() o.Option[string] {
	return c.get("", versionKey)
}

// candidatePaths returns the ways a destination could name a file on disk.
// goldmark reports the destination alone, without the angle brackets or the
// whitespace that separated it from the rest of the link, so what arrives is
// already the name. Backslash escapes and percent encoding survive, and either
// can stand in for a character legal in a filename. A space must be written as
// "<./my file.png>" or "./my%20file.png" to parse at all, which is also why a
// space inside the brackets belongs to the name and is kept.
func candidatePaths(dest string) []string {
	out := []string{dest}
	if unescaped := unescapePunctuation(dest); unescaped != dest {
		out = append(out, unescaped)
	}
	for _, s := range append([]string{}, out...) {
		if decoded, err := url.PathUnescape(s); err == nil && decoded != s {
			out = append(out, decoded)
		}
	}
	return out
}

// TerminalWidth returns the width of the terminal that controls the process
func (s *IOStreams) TerminalWidth() int {
	w, _, err := s.term.Size()
	if err == nil && w > 0 {
		return w
	}
	return DefaultWidth
}

// GetWord returns the word for a given token ID, or an empty string if not found.
func (v *Vocabulary) GetWord(id int) string {
	if id >= 0 && id < len(v.TokenToWord) {
		return v.TokenToWord[id]
	}
	return ""
}

// cwd returns the working directory, or "" when it can't be told.
