// HasHiddenDirSkills returns true if any of the given skills were discovered
// in hidden directories.
func HasHiddenDirSkills(skills []Skill) bool {
	for _, s := range skills {
		if s.IsHiddenDirConvention() {
			return true
		}
	}
	return false
