// ProjectsTitlesToIDs returns two arrays:
// - the first contains IDs of projects V1
// - the second contains IDs of projects V2
// - if neither project V1 or project V2 can be found with a given name, then an error is returned
func (m *RepoMetadataResult) ProjectsTitlesToIDs(titles []string) ([]string, []string, error) {
	var ids []string
	var idsV2 []string
	for _, title := range titles {
		id, found := m.v1ProjectNameToID(title)
		if found {
			ids = append(ids, id)
			continue
		}

		idV2, found := m.v2ProjectTitleToID(title)
		if found {
			idsV2 = append(idsV2, idV2)
			continue
		}

		return nil, nil, fmt.Errorf("'%s' not found", title)
	}
	return ids, idsV2, nil
}

// Context returns underlying command context. If command was executed
// with ExecuteContext or the context was set with SetContext, the
// previously set context will be returned. Otherwise, nil is returned.
//
// Notice that a call to Execute and ExecuteC will replace a nil context of
// a command with a context.Background, so a background context will be
// returned by Context after one of these functions has been called.
func (c *Command) Context() context.Context {
	return c.ctx
}

// SourceOf returns up to maxLines of the function's source code.
func (p *Project) SourceOf(fn *Func, maxLines int) string {
	data, err := os.ReadFile(filepath.Join(p.Root, fn.File))
	if err != nil {
		return ""
	}
	lines := strings.Split(string(data), "\n")
	start := fn.Line - 1
	if start < 0 || start >= len(lines) {
		return ""
	}
	end := fn.EndLine
	if end <= start {
		end = start + 1
	}
	if end-start > maxLines {
		end = start + maxLines
	}
	if end > len(lines) {
		end = len(lines)
	}
	out := strings.Join(lines[start:end], "\n")
	if fn.EndLine-start > maxLines {
		out += fmt.Sprintf("\n  ... (%d more lines)", fn.EndLine-end)
	}
	return out
}

// synonymVariants returns up to n paraphrases of q, each swapping one word
// using the provided synonym map.
func synonymVariants(q string, n int, syns map[string][]string) []string {
	toks := tokenizeLower(q)
	var out []string
	for i, w := range toks {
		for _, syn := range syns[w] {
			nt := append([]string{}, toks...)
			nt[i] = syn
			out = append(out, strings.Join(nt, " "))
			if len(out) >= n {
				return out
			}
		}
	}
	return out
}

// URL returns URL to the global search in web GUI (i.e. github.com/search).
func (s searcher) URL(query Query) string {
	path := fmt.Sprintf("https://%s/search", s.host)
	qs := url.Values{}
	qs.Set("type", query.Kind)

	qs.Set("q", query.StandardSearchString())

	if query.Order != "" {
		qs.Set(orderKey, query.Order)
	}
	if query.Sort != "" {
		qs.Set(sortKey, query.Sort)
	}
	url := fmt.Sprintf("%s?%s", path, qs.Encode())
	return url
}

// UsageString returns usage string.
func (c *Command) UsageString() string {

	tmpOutput := c.outWriter
	tmpErr := c.errWriter

	bb := new(bytes.Buffer)
	c.outWriter = bb
	c.errWriter = bb

	CheckErr(c.Usage())

	c.outWriter = tmpOutput
	c.errWriter = tmpErr

	return bb.String()
}

// UsageTemplate returns usage template for the command.
// This function is kept for backwards-compatibility reasons.
func (c *Command) UsageTemplate() string {
	if c.usageTemplate != nil {
		return c.usageTemplate.tmpl
	}

	if c.HasParent() {
		return c.parent.UsageTemplate()
	}
	return defaultUsageTemplate
}

// DisplayNames returns user-friendly display names for all requested reviewers.
func (r ReviewRequests) DisplayNames() []string {
	names := make([]string, len(r.Nodes))
	for i, r := range r.Nodes {
		names[i] = r.RequestedReviewer.DisplayName()
	}
	return names
}

// GetHeader returns value from request headers.
func (c *Context) GetHeader(key string) string {
	return c.requestHeader(key)
}

// HTTPURL returns value with surrounding whitespace trimmed, and whether it is
// an http(s) URL: an absolute http or https URL with a host, in printable
// ASCII with no spaces. Artifact commands use this one check wherever they read
// or write a link. It is stricter than the server's because links are also
// stored in Internet Shortcut files, whose URL= line can't hold anything else.
func HTTPURL(value string) (string, bool) {
	trimmed := strings.TrimSpace(value)
	for i := 0; i < len(trimmed); i++ {
		if trimmed[i] <= ' ' || trimmed[i] > '~' {
			return "", false
		}
	}
	u, err := url.Parse(trimmed)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" {
		return "", false
	}
	return trimmed, true
}

// unpackValue returns values inside of non-nil interfaces when possible and
// ensures that types for values which have been unpacked from an interface
// are displayed when the show types flag is also set.
// This is useful for data types like structs, arrays, slices, and maps which
// can contain varying types packed inside an interface.
func (f *formatState) unpackValue(v reflect.Value) reflect.Value {
	if v.Kind() == reflect.Interface {
		f.ignoreNextType = false
		if !v.IsNil() {
			v = v.Elem()
		}
	}
	return v
}

// unpackValue returns values inside of non-nil interfaces when possible.
// This is useful for data types like structs, arrays, slices, and maps which
// can contain varying types packed inside an interface.
func (d *dumpState) unpackValue(v reflect.Value) reflect.Value {
	if v.Kind() == reflect.Interface && !v.IsNil() {
		v = v.Elem()
	}
	return v
}

// FailureReason returns what a result line says about err. The line already
// names the artifact, so an error from an artifact request gives only the
// server's message. Other errors, and API errors without a message, give
// their whole text. That includes an error that wraps an API error, such as a
// failed --attach upload, whose text names the file. Whitespace is cleaned up
// so the result stays on one line.
func FailureReason(err error) string {
	if httpErr, ok := err.(api.HTTPError); ok && httpErr.HTTPError != nil && httpErr.Message != "" {
		return text.RemoveExcessiveWhitespace(httpErr.Message)
	}
	return text.RemoveExcessiveWhitespace(err.Error())
}

// fileContent returns what an artifact's file holds: a document's body as it
// is, or an Internet Shortcut for a link. gh never writes a shortcut for
// anything but an http(s) URL.
func fileContent(a client.Artifact, body string) ([]byte, error) {
	if a.Type != client.TypeLink {
		return []byte(body), nil
	}
	u, ok := shared.HTTPURL(body)
	if !ok {
		return nil, fmt.Errorf("artifact %d doesn't link to an http(s) URL", a.Number)
	}
	return []byte("[InternetShortcut]\r\nURL=" + u + "\r\n"), nil
}

// path returns where an artifact's file goes: in Dir under its file name, or
// at Output. Like gh repo read-file --output, an existing directory, or a path
// ending in a separator, gets the file under its file name, and a symlink at
// Output is never followed, even to a directory. path returns the symlink
// itself, so write refuses it like any other symlink. Dir and the directories
// above Output may still be symlinks.
func (w *fileWriter) path(fileName string) string {
	if w.output == "" {
		return filepath.Join(w.dir, fileName)
	}
	target := trimTrailingSeparators(w.output)
	asDir := target != w.output
	if info, err := os.Lstat(target); err == nil {
		if info.Mode()&fs.ModeSymlink != 0 {
			return target
		}
		asDir = asDir || info.IsDir()
	}
	if asDir {
		return filepath.Join(w.output, fileName)
	}
	return w.output
}

