// CalculateFitness scores a candidate: +50 for passing tests, +20 for
// compiling with no syntax/compiler errors, minus 2 per allocation
// per op and minus ns/op divided by 1000. Nil arguments contribute
// nothing.
func CalculateFitness(res *runner.ExecutionResult, bench *runner.BenchmarkMetrics) float64 {
	score := 0.0
	if res != nil {
		if res.Passed {
			score += 50
		}
		compilesClean := true
		for _, e := range res.Errors {
			if e.Category == runner.CategoryCompiler || e.Category == runner.CategorySyntax {
				compilesClean = false
				break
			}
		}
		if compilesClean {
			score += 20
		}
	}
	if bench != nil {
		score -= float64(bench.AllocsPerOp) * 2
		score -= bench.NsPerOp / 1000
	}
	return score
}

// Rank scores every function by structural importance: how many distinct
// project functions call it, with bonuses for being exported, an entry
// point, or part of package main, and a penalty for test helpers.
func (p *Project) Rank() {
	for _, fn := range p.byID {
		s := 2 * len(fn.Callers)
		if fn.Exported {
			s += 3
		}
		if fn.IsMain {
			s += 10
		}
		if fn.IsInit {
			s += 1
		}
		if fn.Pkg == "main" {
			s += 2
		}
		if fn.Receiver != "" && fn.Exported {
			s += 1
		}
		if fn.IsTest {
			s -= 5
		}
		fn.Score = s
	}

	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t.Kind != "interface" || len(t.Methods) == 0 {
				continue
			}
			need := map[string]bool{}
			for _, m := range t.Methods {
				need[m] = true
			}
			for _, other := range pkg.Types {
				if other == t || other.Kind != "struct" {
					continue
				}
				have := map[string]bool{}
				for _, m := range p.methodsOf(other) {
					have[m] = true
				}
				ok := true
				for m := range need {
					if !have[m] {
						ok = false
						break
					}
				}
				if ok {
					t.ImplCount++
				}
			}
		}
	}
}

// Search for a wildcard segment and check the name for invalid characters.
// Returns -1 as index, if no wildcard was found.
func findWildcard(path string) (wildcard string, i int, valid bool) {

	escapeColon := false
	for start, c := range []byte(path) {
		if escapeColon {
			escapeColon = false
			if c == ':' {
				continue
			}
			panic("invalid escape string in path '" + path + "'")
		}
		if c == '\\' {
			escapeColon = true
			continue
		}

		if c != ':' && c != '*' {
			continue
		}

		valid = true
		for end, c := range []byte(path[start+1:]) {
			switch c {
			case '/':
				return path[start : start+1+end], start, valid
			case ':', '*':
				valid = false
			}
		}
		return path[start:], start, valid
	}
	return "", -1, false
}

