// Write serializes data into JSON output written to w. If the object passed as data implements exportable,
// or if data is a map or slice of exportable object, ExportData() will be called on each object to obtain
// raw data for serialization.
func (e *jsonExporter) Write(ios *iostreams.IOStreams, data any) error {
	buf := bytes.Buffer{}
	encoder := json.NewEncoder(&buf)
	encoder.SetEscapeHTML(false)
	if err := encoder.Encode(e.exportData(reflect.ValueOf(data))); err != nil {
		return err
	}

	w := ios.Out
	if e.filter != "" {
		indent := ""
		if ios.IsStdoutTTY() {
			indent = "  "
		}
		if err := jq.EvaluateFormatted(&buf, w, e.filter, indent, ios.ColorEnabled()); err != nil {
			return err
		}
	} else if e.template != "" {
		t := template.New(w, ios.TerminalWidth(), ios.ColorEnabled())
		if err := t.Parse(e.template); err != nil {
			return err
		}
		if err := t.Execute(&buf); err != nil {
			return err
		}
		return t.Flush()
	} else if ios.ColorEnabled() {
		return jsoncolor.Write(w, &buf, "  ")
	}

	_, err := io.Copy(w, &buf)
	return err
}

// SaveState serializes the Adam optimizer state (step counter + m/v moments)
// to a gzip-compressed gob file sequentially to avoid massive OOM spikes.
func (o *Adam) SaveState(path string) error {
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("optimizer SaveState: create file: %w", err)
	}
	defer f.Close()
	gz := gzip.NewWriter(f)
	defer gz.Close()
	enc := gob.NewEncoder(gz)

	if err := enc.Encode(o.t); err != nil {
		return err
	}
	if err := enc.Encode(len(o.parameters)); err != nil {
		return err
	}
	for _, p := range o.parameters {
		if m, ok := o.m[p]; ok {
			if err := enc.Encode(m.Data); err != nil {
				return err
			}
		} else {
			if err := enc.Encode([]float32(nil)); err != nil {
				return err
			}
		}
		if v, ok := o.v[p]; ok {
			if err := enc.Encode(v.Data); err != nil {
				return err
			}
		} else {
			if err := enc.Encode([]float32(nil)); err != nil {
				return err
			}
		}
	}
	return nil
}

