// scanTitle skips the optional title following a destination and returns the
// index just past it. i may point at anything: a byte that opens no title
// leaves the index untouched. A title is delimited by double quotes, single
// quotes, or parentheses.
func scanTitle(src []byte, i, hi int) (int, bool) {
	var closer byte
	switch src[i] {
	case '"', '\'':
		closer = src[i]
	case '(':
		closer = ')'
	default:
		return i, true
	}
	i++
	for i < hi && src[i] != closer {
		if src[i] == '\\' && i+1 < hi {
			i++
		}
		i++
	}
	if i >= hi {
		return 0, false
	}
	return i + 1, true
}

// paginate slices results to the requested page window.
func paginate(skills []skillResult, page, limit int) ([]skillResult, int) {
	total := len(skills)
	totalPages := (total + limit - 1) / limit
	start := (page - 1) * limit
	if start >= total {
		return nil, totalPages
	}
	end := min(start+limit, total)
	return skills[start:end], totalPages
}

// nodeText slices the source text of a node.
func nodeText(fset *token.FileSet, src []byte, n ast.Node) string {
	start := fset.Position(n.Pos()).Offset
	end := fset.Position(n.End()).Offset
	if start < 0 || end > len(src) || start >= end {
		return ""
	}
	return strings.TrimSpace(string(src[start:end]))
}

// Finish snapshots the recorded events once and sends their payload after releasing the lock.
// Sampling and telemetry eligibility apply to immediate and pending events alike.
func (s *service) Finish() {
	s.mu.Lock()

	if s.finished {
		s.mu.Unlock()
		return
	}
	s.finished = true

	if s.sampleRate > 0 && s.sampleRate < 100 && int(s.sampleBucket) >= s.sampleRate {
		s.mu.Unlock()
		return
	}

	events := s.events
	if s.disabled {
		events = nil
	}

	payload := SendTelemetryPayload{
		Events: make([]PayloadEvent, len(events)),
	}

	for i, recorded := range events {
		event := recorded.event

		dimensions := map[string]string{
			"timestamp": recorded.recordedAt.UTC().Format("2006-01-02T15:04:05.000Z"),
		}
		maps.Copy(dimensions, s.commonDimensions)
		maps.Copy(dimensions, event.Dimensions)

		payload.Events[i] = PayloadEvent{
			Type:		event.Type,
			Dimensions:	dimensions,
			Measures:	maps.Clone(event.Measures),
		}
	}
	s.mu.Unlock()

	s.flush(payload)
}

