// Split a string on "\n" while preserving them. The output can be used
// as input for UnifiedDiff and ContextDiff structures.
func SplitLines(s string) []string {
	lines := strings.SplitAfter(s, "\n")
	lines[len(lines)-1] += "\n"
	return lines
}

// splitMethodSymbol splits "(*Server).Start" into ("Server", "Start").
func splitMethodSymbol(sym string) (recv, method string) {
	if i := strings.LastIndex(sym, ")."); i >= 0 {
		return strings.TrimPrefix(sym[:i], "(*"), sym[i+2:]
	}
	if j := strings.LastIndex(sym, "."); j >= 0 {
		return sym[:j], sym[j+1:]
	}
	return "", sym
}

// splitRepo splits "owner/repo" into its components.
func splitRepo(fullName string) (string, string) {
	parts := strings.SplitN(fullName, "/", 2)
	if len(parts) != 2 {
		return fullName, ""
	}
	return parts[0], parts[1]
}

// camelSplit splits "ServeHTTP" into ["Serve", "HTTP"], "userID" into
// ["user", "ID"]. Used to match task keywords against symbol names.
func camelSplit(s string) []string {
	var words []string
	start := 0
	runes := []rune(s)
	for i := 1; i <= len(runes); i++ {
		if i == len(runes) || (isUpper(runes[i]) && !isUpper(runes[i-1])) ||
			(isUpper(runes[i-1]) && i < len(runes) && !isUpper(runes[i])) {
			if i > start {
				words = append(words, string(runes[start:i]))
			}
			start = i
		}
	}
	return words
}

// parseImpactSymbol splits "User" and "Store.Get" / "(*Store).Get"
// into receiver and name parts.
func parseImpactSymbol(s string) (recv, name string, isMethod bool, err error) {
	s = strings.TrimSpace(s)
	if i := strings.LastIndex(s, "."); i >= 0 {
		recv = strings.TrimSpace(s[:i])
		name = strings.TrimSpace(s[i+1:])
		recv = strings.Trim(recv, "()")
		recv = strings.TrimPrefix(recv, "*")
		isMethod = true
	} else {
		name = s
	}
	if !isGoIdent(name) || (isMethod && !isGoIdent(recv)) {
		return "", "", false, fmt.Errorf("impact: invalid symbol %q (want \"Name\" or \"Type.Method\")", s)
	}
	return recv, name, isMethod, nil
}

// splitName splits a CamelCase identifier for intent reading:
// "DeleteFile" -> ["Delete", "File"], "ServeHTTP" -> ["Serve", "HTTP"],
// "Copy" -> ["Copy"]. (The shared camelSplit over-splits single words.)
func splitName(s string) []string {
	var words []string
	start := 0
	runes := []rune(s)
	isUpper := func(r rune) bool { return r >= 'A' && r <= 'Z' }
	isLower := func(r rune) bool { return r >= 'a' && r <= 'z' }
	for i := 1; i < len(runes); i++ {
		r, prev := runes[i], runes[i-1]
		split := false
		switch {
		case isUpper(r) && (isLower(prev) || prev >= '0' && prev <= '9'):
			split = true
		case isUpper(r) && isUpper(prev) && i+1 < len(runes) && isLower(runes[i+1]):
			split = true
		}
		if split {
			words = append(words, string(runes[start:i]))
			start = i
		}
	}
	words = append(words, string(runes[start:]))
	return words
}

// tokenizeName splits a camelCase identifier into stemmed words:
// WriteJSONLog -> [write json log], LogDeletionToFileAsJson ->
// [log delet to file as json]. Consecutive capitals stay together
// unless followed by a lowercase letter (JSONLog -> JSON + Log).
func tokenizeName(name string) []string {
	isUpper := func(r rune) bool { return r >= 'A' && r <= 'Z' }
	isLower := func(r rune) bool { return r >= 'a' && r <= 'z' }
	isDigit := func(r rune) bool { return r >= '0' && r <= '9' }
	runes := []rune(name)
	var toks []string
	start := 0
	flush := func(end int) {
		if w := stem(string(runes[start:end])); w != "" {
			toks = append(toks, w)
		}
		start = end
	}
	for i := 1; i < len(runes); i++ {
		r, prev := runes[i], runes[i-1]
		switch {
		case r == '_' || r == '-':
			flush(i)
			start = i + 1
		case isUpper(r) && (isLower(prev) || isDigit(prev)):
			flush(i)
		case isUpper(r) && isUpper(prev) && i+1 < len(runes) && isLower(runes[i+1]):
			flush(i)
		case (isDigit(r) && !isDigit(prev)) || (!isDigit(r) && isDigit(prev)):
			flush(i)
		}
	}
	flush(len(runes))
	return toks
}

