// parseFilesFromResponse splits a raw LLM response into module-relative
// path -> Go source. Markdown fences are stripped; chatter before the
// first marker is ignored. Paths are validated with the same jail
// rules the sandbox enforces.
func parseFilesFromResponse(resp string) (map[string]string, error) {
	resp = stripCodeFences(resp)
	files := make(map[string]string)
	var cur string
	var sb strings.Builder
	flush := func() {
		if cur != "" {
			files[cur] = strings.Trim(sb.String(), "\n") + "\n"
			sb.Reset()
		}
	}
	for _, line := range strings.Split(resp, "\n") {
		if m := fileMarkerRe.FindStringSubmatch(strings.TrimSpace(line)); m != nil {
			flush()
			path := filepath.Clean(m[1])
			if err := validCandidatePath(path); err != nil {
				return nil, fmt.Errorf("invalid file path %q: %w", m[1], err)
			}
			cur = path
			continue
		}
		if cur == "" {
			continue
		}
		sb.WriteString(line)
		sb.WriteByte('\n')
	}
	flush()
	if len(files) == 0 {
		return nil, fmt.Errorf("no === FILE: <path> === blocks found")
	}
	return files, nil
}

// Tokenize splits a string into words based on whitespace and JSON punctuation.
func Tokenize(text string) []string {
	var tokens []string
	runes := []rune(text)
	i := 0
	for i < len(runes) {
		r := runes[i]

		if unicode.IsSpace(r) {
			i++
			continue
		}

		if strings.ContainsRune(`{}[],:"?!.`, r) {
			tokens = append(tokens, string(r))
			i++
			continue
		}

		start := i
		for i < len(runes) && !unicode.IsSpace(runes[i]) && !strings.ContainsRune(`{}[],:"?!.`, runes[i]) {
			i++
		}
		token := string(runes[start:i])
		if token != "" {
			tokens = append(tokens, token)
		}
	}
	return tokens
}

// Split splits a tensor into multiple tensors along a specified axis.
// The `splitSizes` argument specifies the size of each chunk along the split axis.
// The sum of `splitSizes` must equal the size of the tensor along the split axis.
func Split(t *Tensor, axis int, splitSizes []int) ([]*Tensor, error) {
	if t == nil {
		return nil, fmt.Errorf("Split: input tensor is nil")
	}
	if axis < 0 || axis >= len(t.Shape) {
		return nil, fmt.Errorf("axis %d out of bounds for tensor with shape %v", axis, t.Shape)
	}

	totalSplitSize := 0
	for _, size := range splitSizes {
		totalSplitSize += size
	}

	if totalSplitSize != t.Shape[axis] {
		return nil, fmt.Errorf("sum of split sizes (%d) does not match tensor dimension along axis %d (%d)", totalSplitSize, axis, t.Shape[axis])
	}

	var resultTensors []*Tensor
	currentStart := 0
	for _, size := range splitSizes {
		end := currentStart + size
		slicedTensor, err := t.Slice(axis, currentStart, end)
		if err != nil {
			return nil, fmt.Errorf("error slicing tensor during split: %w", err)
		}
		resultTensors = append(resultTensors, slicedTensor)
		currentStart = end
	}

	return resultTensors, nil
}

// splitDiffSections splits a unified diff string into per-file sections.
// Each section starts with "diff --git" and includes all content up to (but
// not including) the next "diff --git" line.
func splitDiffSections(diff string) []string {
	marker := "\ndiff --git "
	parts := strings.Split(diff, marker)
	if len(parts) == 1 {
		return []string{diff}
	}
	sections := make([]string, 0, len(parts))
	for i, p := range parts {
		if i == 0 {
			if len(p) > 0 {
				sections = append(sections, p+"\n")
			}
		} else {
			sections = append(sections, "diff --git "+p)
		}
	}
	return sections
}

// SplitFileArg splits an argument of the form <file>#<text>, the way --attach
// reads '<file>#<image alt text>'. An existing path wins over the delimiter,
// since `#` is legal in filenames. path is arg itself when there was no `#` to
// split at. gh issue artifact create uses it for <file>#<name>, so `#` means
// the same there as in --attach.
func SplitFileArg(arg string) (path, text string) {
	if _, err := os.Stat(arg); err == nil {
		return arg, ""
	}

	for i := strings.LastIndex(arg, "#"); i > 0; i = strings.LastIndex(arg[:i], "#") {
		if _, err := os.Stat(arg[:i]); err == nil {
			return arg[:i], arg[i+1:]
		}
	}

	if idx := strings.LastIndex(arg, "#"); idx > 0 {
		return arg[:idx], arg[idx+1:]
	}
	return arg, ""
}

// wordTokens splits free text into stemmed words of length 2+.
func wordTokens(s string) []string {
	var out []string
	for _, w := range strings.FieldsFunc(strings.ToLower(s),
		func(r rune) bool { return r < 'a' || r > 'z' }) {
		if len(w) >= 2 {
			out = append(out, stem(w))
		}
	}
	return out
}

// tokenizeSource splits Go source code into tokens (preserving identifiers, keywords, operators).
func tokenizeSource(text string) []string {
	var tokens []string
	var current strings.Builder
	runes := []rune(text)

	flush := func() {
		if current.Len() > 0 {
			tokens = append(tokens, current.String())
			current.Reset()
		}
	}

	for _, r := range runes {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			current.WriteRune(r)
		} else {
			flush()
			if !unicode.IsSpace(r) {

				tokens = append(tokens, string(r))
			}
		}
	}
	flush()
	return tokens
}

// tokenizeText splits natural language text into word tokens.
func tokenizeText(text string) []string {
	var tokens []string
	var current strings.Builder

	flush := func() {
		if current.Len() > 0 {
			word := strings.ToLower(current.String())
			if word != "" {
				tokens = append(tokens, word)
			}
			current.Reset()
		}
	}

	for _, r := range text {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '\'' || r == '_' {
			current.WriteRune(r)
		} else {
			flush()
			if !unicode.IsSpace(r) {
				tokens = append(tokens, string(r))
			}
		}
	}
	flush()
	return tokens
}

