func stem(w string) string {
	if len(w) > 3 && strings.HasSuffix(w, "s") && !strings.HasSuffix(w, "ss") {
		return w[:len(w)-1]
	}
	return w
}

// cleanSymbol strips articles, quotes, and role words from a symbol name.
// It never invents a symbol: a multi-word phrase that isn't a known
// "X function" / "X method" form is returned as-is and won't resolve,
// so e.g. "what does make chat do" can't become "chat".
func cleanSymbol(s string) string {
	s = strings.TrimSpace(s)
	s = strings.Trim(s, `"'().,?!`)
	s = strings.TrimPrefix(s, "the ")
	for _, w := range []string{" function", " func", " method", " type", " struct", " package"} {
		s = strings.TrimSuffix(s, w)
	}
	return strings.TrimSpace(strings.Trim(s, `"'().,?!`))
}

// simplifyURL strips given URL of extra parts like extra path segments (i.e.,
// anything beyond `/owner/repo`), query strings, or fragments. This function
// never returns an error.
//
// The rationale behind this function is to let users clone a repo with any
// URL related to the repo; like:
//   - (Tree)              github.com/owner/repo/blob/main/foo/bar
//   - (Deep-link to line) github.com/owner/repo/blob/main/foo/bar#L168
//   - (Issue/PR comment)  github.com/owner/repo/pull/999#issue-9999999999
//   - (Commit history)    github.com/owner/repo/commits/main/?author=foo
func simplifyURL(u *url.URL) *url.URL {
	result := &url.URL{
		Scheme:	u.Scheme,
		User:	u.User,
		Host:	u.Host,
		Path:	u.Path,
	}

	pathParts := strings.SplitN(strings.Trim(u.Path, "/"), "/", 3)
	if len(pathParts) <= 2 {
		return result
	}

	result.Path = strings.Join(pathParts[0:2], "/")
	return result
}

// baseTypeName strips pointer and generic arguments: "*Server" and
// "Box[T]" both become "Server" and "Box".
func baseTypeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		if t == nil {
			return ""
		}
		return t.Name
	case *ast.StarExpr:
		if t == nil {
			return ""
		}
		return baseTypeName(t.X)
	case *ast.IndexExpr:
		if t == nil {
			return ""
		}
		return baseTypeName(t.X)
	case *ast.IndexListExpr:
		if t == nil {
			return ""
		}
		return baseTypeName(t.X)
	default:
		return ""
	}
}

// baseTypeName strips pointer and generic type arguments to the bare
// type name: "*Server" -> "Server", "Box[T]" -> "Box".
func baseTypeName(e ast.Expr) string {
	switch t := e.(type) {
