// enableRawMode switches the terminal to raw mode (no echo, no line
// buffering, no signal chars) and returns a function restoring the
// original mode. ok is false when the fd isn't a terminal.
func enableRawMode(f *os.File) (func(), bool) {
	orig, err := tcgetattr(f)
	if err != nil {
		return nil, false
	}
	raw := *orig
	raw.Iflag &^= ignbrk | brkint | istrip | inlcr | igncr | icrnl | ixon
	raw.Oflag &^= opost
	raw.Lflag &^= echo | echonl | icanon | isig | iexten
	raw.Cflag &^= csize | parenb
	raw.Cflag |= cs8
	raw.Cc[vmin] = 1
	raw.Cc[vtime] = 0
	if err := tcsetattr(f, &raw); err != nil {
		return nil, false
	}
	return func() { tcsetattr(f, orig) }, true
}

// syncBranchCmds syncs a branch to ref: a hard reset when force is set,
// otherwise a fast-forward-only merge. A non-empty path runs the commands there.
func syncBranchCmds(path, ref string, force bool) [][]string {
	var prefix []string
	if path != "" {
		prefix = []string{"-C", path}
	}
	if force {
		return [][]string{append(prefix, "reset", "--hard", ref)}
	}

	return [][]string{append(prefix, "merge", "--ff-only", ref)}
}

