// containsElement try loop over the list check if the list includes the element.
// return (false, false) if impossible.
// return (true, false) if element was not found.
// return (true, true) if element was found.
func containsElement(list interface{}, element interface{}) (ok, found bool) {
	listValue := reflect.ValueOf(list)
	listType := reflect.TypeOf(list)
	if listType == nil {
		return false, false
	}
	listKind := listType.Kind()
	defer func() {
		if e := recover(); e != nil {
			ok = false
			found = false
		}
	}()

	if listKind == reflect.String {
		elementValue := reflect.ValueOf(element)
		return true, strings.Contains(listValue.String(), elementValue.String())
	}

	if listKind == reflect.Map {
		mapKeys := listValue.MapKeys()
		for i := 0; i < len(mapKeys); i++ {
			if ObjectsAreEqual(mapKeys[i].Interface(), element) {
				return true, true
			}
		}
		return true, false
	}

	for i := 0; i < listValue.Len(); i++ {
		if ObjectsAreEqual(listValue.Index(i).Interface(), element) {
			return true, true
		}
	}
	return true, false
}

// humanize turns a camelCase function name into words:
// parseJSONBody -> "Parse JSON body". All-caps runs (JSON, JWT,
// HTTP, DB, URL, ID) are preserved.
func humanize(name string) string {
	var words []string
	runes := []rune(name)
	start := 0
	flush := func(end int) {
		if end > start {
			words = append(words, string(runes[start:end]))
		}
		start = end
	}
	isUpper := func(r rune) bool { return r >= 'A' && r <= 'Z' }
	isLower := func(r rune) bool { return r >= 'a' && r <= 'z' }
	isDigit := func(r rune) bool { return r >= '0' && r <= '9' }
	for i := 1; i < len(runes); i++ {
		prev, cur := runes[i-1], runes[i]
		switch {
		case isLower(prev) && isUpper(cur):
			flush(i)
		case isUpper(prev) && isUpper(cur) && i+1 < len(runes) && isLower(runes[i+1]):
			flush(i)
		case (isDigit(prev) || isDigit(cur)) && isDigit(prev) != isDigit(cur) &&
			(isLower(prev) || isUpper(prev) || isLower(cur) || isUpper(cur)):
			flush(i)
		}
	}
	flush(len(runes))
	for i, w := range words {
		if i == 0 {
			words[i] = strings.ToUpper(w[:1]) + w[1:]
			continue
		}
		if w == strings.ToUpper(w) {
			continue
		}
		words[i] = strings.ToLower(w)
	}
	return strings.Join(words, " ")
}

// verbPhrase turns a function name into a plain verb phrase:
// "DeleteFile" -> "deletes a file" (third=true) or "delete a file"
// (third=false, for "why does X call Y" — "to delete a file").
// "CopyOrCloneFile" -> "copies or clones a file".
func verbPhrase(name string, third bool) string {
	words := splitName(name)
	var parts []string
	i := 0
	for ; i < len(words); i++ {
		w := words[i]
		if w == "Or" || w == "And" {
			parts = append(parts, strings.ToLower(w))
			continue
		}
		v, ok := verbLexicon[w]
		if !ok {
			break
		}
		if third {
			v = thirdPerson(v)
		}
		parts = append(parts, v)
	}
	rest := words[i:]
	if len(parts) == 0 {
		return "handles " + articleJoin(rest)
	}
	out := strings.Join(parts, " ")
	if len(rest) > 0 {
		out += " " + articleJoin(rest)
	}
	return out
}

// resolveAnalyzeRoot turns a user-supplied path or GitHub URL into a local
// directory: ~ is expanded, github.com URLs are shallow-cloned into
// ~/workspace/codebase-maps (cached between runs).
func resolveAnalyzeRoot(raw string) (string, error) {
	if githubURL.MatchString(raw) {
		return ensureGitHubRepo(raw)
	}
	path := raw
	if strings.HasPrefix(path, "~") {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", fmt.Errorf("can't expand ~: %w", err)
		}
		path = filepath.Join(home, strings.TrimPrefix(path, "~"))
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	fi, err := os.Stat(abs)
	if err != nil {
		return "", fmt.Errorf("no such directory: %s", raw)
	}
	if !fi.IsDir() {
		return "", fmt.Errorf("%s is not a directory", raw)
	}
	return abs, nil
}

