// bodyForWrite uploads the assets and reports whether the body it produced is
// worth writing. A failed upload that produced nothing writes nothing, since
// there is nothing to salvage and a comment that promises an attachment it
// does not have only compounds the failure.
//
// Callers must call this after every prompt, since nothing that can prompt or
// cancel may follow an upload.
func bodyForWrite(opts *CommentableOptions, uploader *attachments.Uploader) (body string, write bool, err error) {
	if uploader == nil {
		return opts.Body, true, nil
	}
	body, uploadResult, err := uploader.UploadAndAttach(context.Background(), opts.Body, opts.BodyDir, opts.Assets)
	opts.AttachEvent.RecordOperations(uploadResult)
	if err != nil && uploadResult.Uploaded == 0 {
		return "", false, err
	}
	return body, true, err
}

// SaveUploadedFile uploads the form file to specific dst.
// An optional perm argument specifies the permission bits used when creating
// the destination directory. If not provided, the default is 0750. The exact
// permission is enforced only on the destination directory and only when it is
// newly created by this call; pre-existing directories (e.g. /tmp) are not
// modified.
func (c *Context) SaveUploadedFile(file *multipart.FileHeader, dst string, perm ...fs.FileMode) error {
	src, err := file.Open()
	if err != nil {
		return err
	}
	defer src.Close()

	var mode os.FileMode = 0o750
	if len(perm) > 0 {
		mode = perm[0]
	}
	dir := filepath.Dir(dst)

	_, statErr := os.Stat(dir)
	if err = os.MkdirAll(dir, mode); err != nil {
		return err
	}
	if errors.Is(statErr, os.ErrNotExist) {
		if err = os.Chmod(dir, mode); err != nil {
			return err
		}
	}

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	_, err = io.Copy(out, src)
	return err
}

// Uploads the provided SSH key. Returns true if the key was uploaded, false if it was not.
func SSHKeyUpload(httpClient *http.Client, hostname string, keyFile io.Reader, title string) (bool, error) {
	u, err := safeurl.JoinPath("user", "keys")
	if err != nil {
		return false, err
	}

	keyBytes, err := io.ReadAll(keyFile)
	if err != nil {
		return false, err
	}

	fullUserKey := string(keyBytes)
	splitKey := strings.Fields(fullUserKey)
	if len(splitKey) < 2 {
		return false, errors.New("provided key is not in a valid format")
	}

	keyToCompare := splitKey[0] + " " + splitKey[1]

	keys, err := shared.UserKeys(httpClient, hostname, "")
	if err != nil {
		return false, err
	}

	for _, k := range keys {
		if k.Key == keyToCompare {
			return false, nil
		}
	}

	payload := map[string]string{
		"title":	title,
		"key":		fullUserKey,
	}

	err = keyUpload(httpClient, hostname, u, payload)

	if err != nil {
		return false, err
	}

	return true, nil
}

