// findModuleRoot walks up from dir to the directory containing go.mod.
func findModuleRoot(dir string) (string, error) {
	d, err := filepath.Abs(dir)
	if err != nil {
		return "", fmt.Errorf("resolve dir %q: %w", dir, err)
	}
	for {
		if _, serr := os.Stat(filepath.Join(d, "go.mod")); serr == nil {
			return d, nil
		}
		parent := filepath.Dir(d)
		if parent == d {
			return "", fmt.Errorf("no go.mod found above %q", dir)
		}
		d = parent
	}
}

// Warn if the pull request and the remote branch have diverged.
func (m *mergeContext) warnIfDiverged() {
	if m.opts.SelectorArg != "" || len(m.pr.Commits.Nodes) == 0 {
		return
	}

	localBranchLastCommit, err := m.opts.GitClient.LastCommit(context.Background())
	if err != nil {
		return
	}

	if localBranchLastCommit.Sha == m.pr.Commits.Nodes[len(m.pr.Commits.Nodes)-1].Commit.OID {
		return
	}

	_ = m.warnf("%s Pull request %s#%d (%s) has diverged from local branch\n", m.cs.Yellow("!"), ghrepo.FullName(m.baseRepo), m.pr.Number, m.pr.Title)
}

// printReviewHint warns the user to review installed skills and suggests preview commands.
// When sha is non-empty the suggested commands include @SHA so the user previews
// exactly the version that was installed. When allowHiddenDirs is true, the
// suggested commands include --allow-hidden-dirs so previewing hidden-dir
// skills works without an extra manual step.
func printReviewHint(w io.Writer, cs *iostreams.ColorScheme, repo, sha string, skillNames []string, allowHiddenDirs bool) {
	if len(skillNames) == 0 {
		return
	}
	fmt.Fprintf(w, "\n%s Skills may contain prompt injections or malicious scripts.\n", cs.WarningIcon())
	if repo == "" {
		fmt.Fprintln(w, "  Review the installed files before use.")
		return
	}
	fmt.Fprintln(w, "  Review installed content before use:")
	fmt.Fprintln(w)
	hiddenFlag := ""
	if allowHiddenDirs {
		hiddenFlag = " --allow-hidden-dirs"
	}
	for _, name := range skillNames {
		if sha != "" {
			fmt.Fprintf(w, "    gh skill preview %s %s@%s%s\n", repo, name, sha, hiddenFlag)
		} else {
			fmt.Fprintf(w, "    gh skill preview %s %s%s\n", repo, name, hiddenFlag)
		}
	}
	fmt.Fprintln(w)
}

// checkInstalledSkillDirs warns when agent host skill directories exist
// in the repo and are not gitignored.
func checkInstalledSkillDirs(gitClient *git.Client, repoDir string) []publishDiagnostic {
	var diagnostics []publishDiagnostic

	for _, relPath := range registry.UniqueProjectDirs() {

		if !strings.HasPrefix(relPath, ".") {
			continue
		}
		absPath := filepath.Join(repoDir, relPath)
		if _, err := os.Stat(absPath); os.IsNotExist(err) {
			continue
		}

		if gitClient != nil {
			ignoreGitClient := gitClient.Copy()
			ignoreGitClient.RepoDir = repoDir
			ignored, err := ignoreGitClient.IsIgnored(context.Background(), relPath)
			if ignored {
				continue
			}
			if err != nil {
				diagnostics = append(diagnostics, publishDiagnostic{
					severity:	"warning",
					message:	fmt.Sprintf("%s/ may contain installed skills that are not gitignored (could not verify: %v)", relPath, err),
				})
				continue
			}
		}

		diagnostics = append(diagnostics, publishDiagnostic{
			severity:	"warning",
			message: fmt.Sprintf(
				"%s/ contains installed skills and should be added to .gitignore to avoid publishing other authors' content",
				relPath),
		})
	}

	return diagnostics
}

