	http.ServeFile(c.Writer, c.Request, filepath)
}

// DataFromReader writes the specified reader into the body stream and updates the HTTP code.
func (c *Context) DataFromReader(code int, contentLength int64, contentType string, reader io.Reader, extraHeaders map[string]string) {
	c.Render(code, render.Reader{
		Headers:	extraHeaders,
		ContentType:	contentType,
		ContentLength:	contentLength,
		Reader:		reader,
	})
}

// writeTable writes the TTY listing as a TYPE/NAME/SIZE table. Names are colored
// by entry type and directories and submodules show "-" since git reports no size
// for them.
func writeTable(io *iostreams.IOStreams, dir *repoDir) error {
	cs := io.ColorScheme()
	tp := tableprinter.New(io, tableprinter.WithHeader("TYPE", "NAME", "SIZE"))
	for _, e := range dir.Entries {
		entryType := e.Type
		if e.Type == "file" && e.isExecutable() {
			entryType = "file*"
		}

		var color string
		switch e.Type {
		case "dir":
			color = "blue"
		case "symlink":
			color = "cyan"
		case "submodule":
			color = "yellow"
		case "file":
			if e.isExecutable() {
				color = "green"
			}
		}

		size := "-"
		if e.Type == "file" || e.Type == "symlink" {
			size = text.FormatSize(int64(e.Size))
		}

		tp.AddField(entryType)
		tp.AddField(e.Name, tableprinter.WithColor(cs.ColorFromString(color)))
		tp.AddField(size)
		tp.EndRow()
	}
	return tp.Render()
}

// writeError writes Twirp errors in the response and triggers hooks.
func writeError(ctx context.Context, resp http.ResponseWriter, err error, hooks *twirp.ServerHooks) {
	// Convert to a twirp.Error. Non-twirp errors are converted to internal errors.
	var twerr twirp.Error
	if !errors.As(err, &twerr) {
		twerr = twirp.InternalErrorWith(err)
	}

	statusCode := twirp.ServerHTTPStatusFromErrorCode(twerr.Code())
	ctx = ctxsetters.WithStatusCode(ctx, statusCode)
	ctx = callError(ctx, hooks, twerr)

	respBody := marshalErrorToJSON(twerr)

	resp.Header().Set("Content-Type", "application/json")
	resp.Header().Set("Content-Length", strconv.Itoa(len(respBody)))
	resp.WriteHeader(statusCode)

	_, writeErr := resp.Write(respBody)
	if writeErr != nil {

		_ = writeErr
	}

	callResponseSent(ctx, hooks)
}

// ➜ git rev-parse --symbolic-full-name bar/baz@{push}
// refs/remotes/foo/bar/baz
// ```
//
// When using this ref, git assumes it means `remote: foo` `branch: bar/baz`.
func ParseRemoteTrackingRef(s string) (RemoteTrackingRef, error) {
	prefix := "refs/remotes/"
	if !strings.HasPrefix(s, prefix) {
		return RemoteTrackingRef{}, fmt.Errorf("remote tracking branch must have format refs/remotes/<remote>/<branch> but was: %s", s)
	}

	refName := strings.TrimPrefix(s, prefix)
	refNameParts := strings.SplitN(refName, "/", 2)
	if len(refNameParts) != 2 {
		return RemoteTrackingRef{}, fmt.Errorf("remote tracking branch must have format refs/remotes/<remote>/<branch> but was: %s", s)
	}

	return RemoteTrackingRef{
		Remote:	refNameParts[0],
		Branch:	refNameParts[1],
	}, nil
}
